plot_histogram <- function(df, bins = 30, title = "", base_size = 10, xlims = NULL, fill = "gray25", color = "gray50", ylab = "Count", pb = FALSE) {
  data <- NULL
  plot <- list()
  df <- data.frame(df, id = 1:nrow(data.frame(df)), check.names = FALSE)
  df <- df[, sapply(df, is.numeric)]
  if (length(names(df)) == 2) {
    names(df)[1] <- ""
  }
  if(pb)
    progress <- txtProgressBar(min = 0, max = length(df), style = 3)
  for (i in 1:(length(df) - 1)) {
    if(pb) setTxtProgressBar(progress, i)
    vector <- data.frame(data = df[, i])
    plot[[names(df)[i]]] <- ggplot(vector, aes(x = data)) +
      geom_histogram(bins = bins, fill = fill, color = color, na.rm = TRUE) +
      theme_bw(base_size = base_size) +
      labs(
        title = title,
        # x=str_aes(names(df)[i],proper=TRUE),
        x = names(df)[i],
        y = ylab,
        caption = paste0(
          "\nObservations=", length(vector[complete.cases(vector), ]),
          "\nMean=", round(mean(vector[, 1], na.rm = TRUE), 2),
          "\nSD=", round(stats::sd(vector[, 1], na.rm = TRUE), 2),
          "\nMedian=", round(stats::median(vector[, 1], na.rm = TRUE), 2)
        )
      ) +
      if (!is.null(xlims)) {
        lims(x = xlims)
      }
  }
  if(pb) close(progress)
  return(plot)
}

compute_descriptives <- function(df, dv, iv = NULL, file = NULL) {
  comment <- list(
    factor = "independent variable",
    levels = "levels of independent variable\n\ndiscrete variables observed in independent variable",
    variable = "dependent variable\n\ncontinous variable",
    n = "sample size",
    mean = "measure of central tendency\n\nmean",
    sd = "measure of dispersion\nstandard deviation\n\nlow values indicate low dispersion of observations from the mean",
    median = "measure of central tendency\n\nmedian\n\nvalue separating lower half from higher half of ordered observations",
    trimmed = "measure of central tendency\n\ntrimmed mean\n\nmean after droping .1 of minimum and maximum values in data",
    mad = "measure of dispersion\n\nmedian absolute deviation\n\nlow values indicate low dispersion of observations from the median",
    min = "minimum value observed",
    max = "maximum value observed",
    range = "measure of dispersion\n\nrange\n\ndifference between minimum and maximum value",
    skew = "skewness\nnegative values indicate a left skewed distribution\n\npositive values indicate a right skewed distribution\n\ndeviations from 0 indicate deviation from normality",
    kurtosis = "kurtosis\n\nnegative values generally indicate flat peak\n\npositive values generally indicate sharp peak\n\ndeviations from 0 indicate deviation from normality",
    se = "measure of dispersion\n\nstandard error\n\nlow values indicate low dispersion of observations from the mean",
    IQR = "measure of dispersion\n\ninterquantile range\n\nthe range around the median where 50% of observations fall",
    Q0.1 = "percentile\n\n10% of observations fall bellow this value",
    Q0.25 = "percentile\n\n25% of observations fall bellow this value",
    Q0.5 = "percentile\n\n50% of observations fall bellow this value",
    Q0.75 = "percentile\n\n75% of observations fall bellow this value",
    Q0.9 = "percentile\n\n90% of observations fall bellow this value"
  )
  result_df <- data.frame()
  describe <- function(x) psych::describe(x, skew = TRUE, ranges = TRUE, check = TRUE, fast = FALSE, IQR = TRUE, quant = c(.1, .25, .5, .75, .90), na.rm = TRUE)
  if (missing(iv)) {
    for (i in names(df)[dv]) {
      result_df <- plyr::rbind.fill(result_df, data.frame(variable = i, describe(df[, i])))
    }
  } else {
    for (i in names(df)[dv]) {
      for (y in names(df)[iv]) {
        temp <- data.frame(df[, i], df[, y])
        names(temp) <- c(i, y)
        temp <- temp[complete.cases(temp), ]
        if (nrow(temp) > 1) {
          if (is.factor(temp[, y])) {
            temp[, y] <- droplevels(temp[, y])
          }
          result <- tapply(temp[, i], temp[, y], FUN = describe)
          result <- data.frame(levels = names(result), do.call(rbind.data.frame, result))
          result_df <- plyr::rbind.fill(result_df, data.frame(factor = y, variable = i, result, row.names = NULL, check.names = FALSE))
        }
      }
    }
  }
  result_df$vars <- NULL
  report_dataframe(result_df, file = file, sheet = "Descriptives", comment = comment)
  return(result_df)
}

compute_aggregate <- function(df, iv, file = NULL) {
  result_df_mean <- result_df_sd <- result_df_obs <- list()
  factornames <- names(df)[iv]
  result_mean <- data.frame(statistic = "mean", plyr::ddply(df, factornames, plyr::numcolwise(mean, na.rm = TRUE)))
  result_sd <- data.frame(statistic = "SD", plyr::ddply(df, factornames, plyr::numcolwise(sd, na.rm = TRUE)))
  result_median <- data.frame(statistic = "median", plyr::ddply(df, factornames, plyr::numcolwise(median, na.rm = TRUE)))
  result_mad <- data.frame(statistic = "mad", plyr::ddply(df, factornames, plyr::numcolwise(stats::mad, na.rm = TRUE)))
  result_trimmed_mean <- data.frame(statistic = "trmmed mean", plyr::ddply(df, factornames, plyr::numcolwise(mean, trim = .5, na.rm = TRUE)))
  result_obs <- data.frame(statistic = "N", plyr::ddply(df, factornames, plyr::numcolwise(length)))
  result_min <- data.frame(statistic = "min", plyr::ddply(df, factornames, plyr::numcolwise(min, na.rm = TRUE)))
  result_max <- data.frame(statistic = "max", plyr::ddply(df, factornames, plyr::numcolwise(max, na.rm = TRUE)))
  result_range <- data.frame(statistic = "range", plyr::ddply(df, factornames, plyr::numcolwise(function(x) max(x, na.rm = TRUE) - min(x, na.rm = TRUE))))
  result_skewness <- data.frame(statistic = "skewness", plyr::ddply(df, factornames, plyr::numcolwise(compute_skewness)))
  result_kurtosis <- data.frame(statistic = "kurtosis", plyr::ddply(df, factornames, plyr::numcolwise(compute_kurtosis)))
  result_iqr <- data.frame(statistic = "IQR", plyr::ddply(df, factornames, plyr::numcolwise(IQR, na.rm = TRUE, type = 7)))
  result_se <- data.frame(statistic = "SE", plyr::ddply(df, factornames, plyr::numcolwise(compute_standard_error)))
  result_df <- plyr::rbind.fill(
    result_mean, result_sd, result_median, result_mad, result_trimmed_mean, result_obs,
    result_min, result_max, result_range, result_skewness, result_kurtosis,
    result_iqr, result_se
  )
  report_dataframe(result_df, file = file, sheet = "Descriptives")
  return(result_df)
}

plot_response_frequencies <- function(df, factor_index, base_size = 10, title = "", width = 100, reorder = FALSE) {
  Freq <- NULL
  plots <- list()
  for (i in names(df[, factor_index])) {
    tempdata <- df[complete.cases(df[, i]), i]
    tempdata <- data.frame(table(tempdata))
    if (nrow(tempdata) > 0) {
      if (reorder) {
        plots[[i]] <- ggplot(data.frame(tempdata), aes(x = stats::reorder(tempdata, Freq), y = Freq)) +
          geom_bar(stat = "identity") +
          labs(x = "", y = "Count", title = paste(title, str_wrap(i, width = width), collapse = "\n"), caption = paste0("Observations:", sum(tempdata$Freq))) +
          coord_flip() +
          theme_bw(base_size = base_size)
      } else {
        plots[[i]] <- ggplot(data.frame(tempdata), aes(x = tempdata, y = Freq)) +
          geom_bar(stat = "identity") +
          labs(x = "", y = "Count", title = paste(title, str_wrap(i, width = width), collapse = "\n"), caption = paste0("Observations:", sum(tempdata$Freq))) +
          coord_flip() +
          theme_bw(base_size = base_size)
      }
    }
  }
  return(plots)
}

change_data_type <- function(df, type) {
  if (type == "character") {
    df[] <- lapply(df, function(x) as.character(trimws(x, which = "both", whitespace = "[\t\r\n]")))
  }
  if (type == "numeric") {
    df[] <- lapply(df, function(x) as.numeric(trimws(as.character(x), which = "both", whitespace = "[\t\r\n]")))
  }
  if (type == "factor") {
    df[] <- lapply(df, as.factor)
  }
  if (type == "factor_character") {
    df[] <- apply(df, 1:2, function(x) {
      if (is.factor(x)) as.character(x) else x
    })
  }
  if (type == "character_factor") {
    df[] <- apply(df, 1:2, function(x) {
      if (is.character(x)) factor(x) else x
    })
  }
  return(df)
}

rbind_all <- function(df1, df2) {
  df1_diff <- setdiff(colnames(df1), colnames(df2))
  df2_diff <- setdiff(colnames(df2), colnames(df1))
  df1[, c(as.character(df2_diff))] <- NA
  df2[, c(as.character(df1_diff))] <- NA
  row_names <- c(row.names(df1), row.names(df2))
  result <- rbind(df1, df2)
  ndf1 <- deparse(substitute(df1))
  ndf2 <- deparse(substitute(df2))
  row_names_df1 <- row.names(df1)
  row_names_df2 <- row.names(df2)
  if (!TRUE %in% duplicated(row_names)) {
    row.names(result) <- c(row_names_df1, row_names_df2)
  }
  return(result)
}

remove_nc <- function(df, value = NA, remove_rows = FALSE, aggressive = FALSE, remove_cols = FALSE, remove_zero_variance = FALSE) {
  df[is.na(df)] <- value
  # df[sapply(df,is.nan)]<-value
  # df[sapply(df,is.infinite)]<-value
  df[df == Inf] <- value
  df[df == -Inf] <- value
  df[df == NaN] <- value
  df[df == ""] <- value
  if (remove_rows) {
    if (aggressive) {
      df <- df[rowSums(is.na(df)) == 0, ]
    } else {
      df <- df[apply(df, 1, function(x) any(!is.na(x))), ]
    }
  }
  if (remove_cols) {
    df <- df[, colSums(!is.na(df)) > 0]
    if (remove_zero_variance) {
      # df<-df[,!0==apply(df,2,function(x) stats::sd(x,na.rm=TRUE))]
      df <- df[, apply(df, 2, function(x) length(table(x))) > 1]
    }
  }
  return(df)
}

comparison_combinations <- function(df, all_orders = TRUE) {
  combinations <- data.frame(t(utils::combn(names(df), 2)), stringsAsFactors = FALSE)
  names(combinations) <- c("X1", "X2")
  if (all_orders) {
    combinations <- rbind(combinations, data.frame(X1 = combinations$X2, X2 = combinations$X1))
    combinations <- combinations[order(combinations$X1, combinations$X2), ]
  }
  return(combinations)
}

cdf <- function(df, name_length = (getOption("width") / 3), digits = 2, nuniques = 0, parralel = FALSE, file = NULL) {
  if (parralel) {
    future::plan(future::multisession, gc = TRUE, .cleanup = TRUE, workers = future::availableCores("mc.cores"))
  } else {
    future::plan(future::sequential)
  }
  check_df <- future.apply::future_sapply(df, function(y) {
    return(list(
      EMPTY = length(which(as.character(y) == "")),
      null = length(which(is.null(y))),
      na = length(which(is.na(y))),
      NOT_NA = length(which(!is.na(y))),
      NAN = length(which(is.nan(unlist(y)))),
      INF = length(which(is.infinite(unlist(y)))),
      FIN = length(which(is.finite(unlist(y)))),
      RANGE = length(unique(y)),
      MEAN = if (is.numeric(y)) round(mean(y, na.rm = TRUE), 2) else NA,
      MEDIAN = if (is.numeric(y)) round(stats::median(y, na.rm = TRUE), 2) else NA,
      SD = if (is.numeric(y)) round(stats::sd(y, na.rm = TRUE), 2) else NA,
      MIN = if (is.double(y)) min(y, na.rm = TRUE) else gtools::mixedsort(as.character(na.omit(unique(y))))[1],
      MAX = if (is.double(y)) max(y, na.rm = TRUE) else gtools::mixedsort(as.character(na.omit(unique(y))))[length(na.omit(unique(y)))],
      MODE = mode(y),
      TYPE = typeof(y),
      CLASS = class(y),
      FACTOR = is.factor(y)
    ))
  })
  check_df <- data.frame(NAMES = names(df), t(check_df), stringsAsFactors = FALSE, check.names = FALSE)
  summary_dataframe <- data.frame(
    COLLUMNS = length(df),
    ROWS = nrow(df),
    TOTAL = length(df) * nrow(df),
    EMPTY = sum(as.numeric(check_df$EMPTY), na.rm = TRUE),
    null = sum(as.numeric(check_df$null), na.rm = TRUE),
    NAN = sum(as.numeric(check_df$NAN), na.rm = TRUE),
    na = sum(as.numeric(check_df$na), na.rm = TRUE),
    INF = sum(as.numeric(check_df$INF), na.rm = TRUE),
    FIN = sum(as.numeric(check_df$FIN), na.rm = TRUE),
    FACTOR = sum(future.apply::future_sapply(df, function(y) length(which(is.factor(y))))),
    row.names = NULL,
    check.names = FALSE,
    stringsAsFactors = FALSE
  )
  if (nuniques > 0) {
    uniques <- future.apply::future_apply(df, 2, unique)
    level <- future.apply::future_sapply(df, function(y) levels(y))
    uniques_df <- levels_df <- data.frame()
    for (i in 1:length(uniques)) {
      if (length(uniques[[i]]) > nuniques) {
        uniques[[i]] <- paste(length(uniques[[i]]), "Uniques")
      }
      if (length(level[[i]]) > nuniques) {
        level[[i]] <- paste(length(level[[i]]), "Levels")
      }
      uniques_df <- plyr::rbind.fill(uniques_df, data.frame(UNIQUES = toString(t(sort(uniques[[i]]))), check.names = FALSE))
      levels_df <- plyr::rbind.fill(levels_df, data.frame(LEVELS = toString(level[[i]]), check.names = FALSE))
    }
    if (all(levels_df$LEVELS == "")) {
      check_df <- data.frame(check_df, uniques_df, check.names = FALSE)
    } else {
      check_df <- data.frame(check_df, uniques_df, levels_df, check.names = FALSE)
    }
  }
  if (!is.null(file)) {
    filename <- paste0(file, ".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb <- openxlsx::createWorkbook()
    excel_critical_value(df = check_df, workbook = wb, sheet = "variables", numFmt = "#0.00")
    excel_critical_value(summary_dataframe, workbook = wb, sheet = "summary", numFmt = "#0.00")
    openxlsx::saveWorkbook(wb = wb, file = filename, overwrite = TRUE)
  }
  check_df$NAMES <- substr(check_df$NAMES, 1, name_length)
  check_df$MIN <- substr(check_df$MIN, 1, floor(name_length / 6))
  check_df$MAX <- substr(check_df$MAX, 1, floor(name_length / 6))

  row.names(check_df) <- NULL
  result <- list(summary = summary_dataframe, check = check_df)
  return(result)
}

write_txt <- function(input, file = NULL) {
  if (!is.null(file)) {
    results <- file(invisible(paste0(file, ".log")))
    sink(results, append = TRUE)
    sink(results, append = TRUE, type = "message")
  }
  print(input)
  if (!is.null(file)) {
    sink()
    sink(type = "message")
    cat(readLines(invisible(paste0(file, ".log"))), sep = "\n")
  }
}

excel_generic_format <- function(df, workbook, sheet = "output", title = NULL, comment = NULL, numFmt = "#0.00") {
  comment <- comment[intersect(names(comment), names(df))]
  if (!is.null(title)) {
    comment_text <- createComment(comment = title, author = Sys.getenv("USER"), style = NULL, visible = FALSE)
    writeComment(workbook, sheet = sheet, col = 1, row = 1, comment = comment_text)
  }
  if (!is.null(comment)) {
    for (i in names(comment)) {
      comment_text <- createComment(comment = comment[[i]], author = Sys.getenv("USER"), style = NULL, visible = FALSE, width = 100)
      writeComment(workbook, sheet = sheet, col = which(i == names(df)) + 1, row = 1, comment = comment_text)
    }
  }
  integer_names <- names(which(sapply(df, function(y) all(if (is.numeric(y)) y == round(y))) == TRUE))
  non_integer_names <- names(which(sapply(df, function(y) !all(if (is.numeric(y)) y == round(y))) == TRUE))
  freezePane(workbook, sheet, firstActiveRow = 1, firstActiveCol = 1, firstRow = TRUE, firstCol = TRUE)
  modifyBaseFont(workbook, fontSize = 10, fontColour = "#000000", fontName = "Liberation Sans")
  content_style <- createStyle(border = "TopBottomLeftRight", borderColour = "gray", borderStyle = "thin", valign = "bottom", wrapText = FALSE, numFmt = numFmt)
  content_style_integer <- createStyle(border = "TopBottomLeftRight", borderColour = "gray", borderStyle = "thin", valign = "bottom", wrapText = FALSE, numFmt = "#0")
  header_style <- createStyle(border = "TopBottomLeftRight", borderColour = "black", borderStyle = "thin", valign = "bottom", wrapText = FALSE, bgFill = NULL, numFmt = numFmt)
  for (i in non_integer_names) {
    addStyle(workbook, sheet = sheet, style = content_style, rows = 2:(nrow(df) + 1), cols = which(names(df) == i) + 1, gridExpand = TRUE, stack = TRUE)
  }
  for (i in integer_names) {
    addStyle(workbook, sheet = sheet, style = content_style_integer, rows = 2:(nrow(df) + 1), cols = which(names(df) == i) + 1, gridExpand = TRUE, stack = TRUE)
  }
  addStyle(workbook, sheet = sheet, style = header_style, rows = 1:(nrow(df) + 1), cols = 1, gridExpand = TRUE, stack = TRUE)
  addStyle(workbook, sheet = sheet, style = header_style, rows = 1, cols = 1:(length(df) + 1), gridExpand = TRUE, stack = TRUE)
  removeColWidths(workbook, sheet, cols = 1:(length(df) + 1))
  setColWidths(workbook, sheet = sheet, cols = 1:(length(df) + 1), widths = "auto")
}

excel_matrix <- function(df, workbook, sheet = "output", title = NULL, comment = NULL, numFmt = "#0.00", conditional_formatting = FALSE, diagonal = FALSE, diagonal_length = nrow(df)) {
  df <- data.frame(df, stringsAsFactors = FALSE, check.names = FALSE)
  openxlsx::addWorksheet(workbook, sheet)
  openxlsx::writeData(workbook, sheet, df, rowNames = TRUE)
  excel_generic_format(df = df, workbook = workbook, sheet = sheet, title = title, comment = comment, numFmt = numFmt)
  if (conditional_formatting) {
    openxlsx::conditionalFormatting(workbook, sheet = sheet, cols = 1:length(df) + 1, rows = 1:nrow(df) + 1, style = c("red", "yellow", "green"), type = "colourScale")
  }
  if (diagonal) {
    diagonal_style <- openxlsx::createStyle(fgFill = "red")
    if (nrow(df) == ncol(df)) {
      for (i in 1:diagonal_length + 1) {
        openxlsx::addStyle(workbook, sheet = sheet, style = diagonal_style, rows = i, cols = i, gridExpand = TRUE, stack = FALSE)
      }
    }
  }
}

excel_critical_value <- function(df, workbook, sheet = "output", title = NULL, comment = NULL, numFmt = "#0.00", critical = NULL) {
  openxlsx::addWorksheet(workbook, sheet)
  openxlsx::writeData(workbook, sheet, df, rowNames = TRUE)
  excel_generic_format(df = df, workbook = workbook, sheet = sheet, title = title, comment = comment, numFmt = numFmt)
  if (!is.null(critical)) {
    for (i in names(critical)) {
      df <- remove_nc(df, value = NA, remove_rows = FALSE, aggressive = FALSE, remove_cols = FALSE, remove_zero_variance = FALSE)
      if (length(critical[[i]]) > 1) {
        critical_value_min <- createStyle(bgFill = "red", numFmt = numFmt)
        critical_value_max <- createStyle(bgFill = "purple", numFmt = numFmt)
        rows <- which(!is.na(df[, i])) + 1
        for (r in rows) {
          conditionalFormatting(workbook, sheet, cols = which(i == names(df)) + 1, rows = r, type = "expression", rule = critical[[i]][1], style = critical_value_min)
          conditionalFormatting(workbook, sheet, cols = which(i == names(df)) + 1, rows = r, type = "expression", rule = critical[[i]][2], style = critical_value_max)
        }
      } else {
        critical_value <- createStyle(bgFill = "red", numFmt = numFmt)
        rows <- which(!is.na(df[, i])) + 1
        for (r in rows) {
          conditionalFormatting(workbook, sheet, cols = which(i == names(df)) + 1, rows = r, type = "expression", rule = critical[[i]], style = critical_value)
        }
      }
    }
  }
}

excel_confusion_matrix <- function(df, workbook, title = "Rows: Expected Collumns: Observed") {
  numFmt <- "#0"
  sheet <- "Confusion Matrix"
  comment <- NULL
  content_style1 <- createStyle(border = "TopBottomLeftRight", borderColour = "gray", borderStyle = "thin", valign = "bottom", wrapText = FALSE, numFmt = numFmt, fgFill = "yellow")
  content_style2 <- createStyle(border = "TopBottomLeftRight", borderColour = "gray", borderStyle = "thin", valign = "bottom", wrapText = FALSE, numFmt = "#0.00", fgFill = "yellow")
  df <- change_data_type(df, type = "numeric")
  openxlsx::addWorksheet(workbook, sheet = sheet)
  openxlsx::writeData(workbook, sheet = sheet, df, rowNames = TRUE)
  excel_generic_format(df = df, workbook = workbook, sheet = sheet, title = title, comment = comment, numFmt = numFmt)
  conditionalFormatting(workbook, sheet = sheet, cols = 1:(length(df) - 1), rows = 1:(nrow(df) - 1), style = c("white", "green"), type = "colourScale", numFmt = numFmt)
  addStyle(workbook, sheet = sheet, style = content_style1, rows = nrow(df), cols = 2:(ncol(df) + 1), gridExpand = TRUE, stack = TRUE)
  addStyle(workbook, sheet = sheet, style = content_style1, rows = 2:(nrow(df) + 1), cols = ncol(df), gridExpand = TRUE, stack = TRUE)
  addStyle(workbook, sheet = sheet, style = content_style2, rows = nrow(df) + 1, cols = 2:(ncol(df) + 1), gridExpand = TRUE, stack = TRUE)
  addStyle(workbook, sheet = sheet, style = content_style2, rows = 2:(nrow(df) + 1), cols = ncol(df) + 1, gridExpand = TRUE, stack = TRUE)
  removeColWidths(workbook, sheet, cols = 1:(length(df) + 1))
  setColWidths(workbook, sheet = sheet, cols = 1:(length(df) + 1), widths = "auto")
}

report_dataframe <- function(df, file = NULL, type = "critical_value", ...) {
  filename <- paste0(file, ".xlsx")
  if (!is.null(file)) {
    if (file.exists(filename)) file.remove(filename)
    workbook <- openxlsx::createWorkbook()
    if (type == "critical_value") {
      excel_critical_value(df = df, workbook = workbook, ...)
    }
    if (type == "matrix") {
      excel_matrix(df = df, workbook = workbook, ...)
    }
    openxlsx::saveWorkbook(wb = workbook, file = filename, overwrite = TRUE, returnValue = FALSE)
  } else {
    return(df)
  }
}

generate_data <- function(nrows = 10, ncols = 5, mean = 0, sd = 1, min = 1, max = 5, type = "normal") {
  df <- data.frame(matrix(NA, ncol = ncols, nrow = nrows))
  if (type == "normal") {
    df[] <- sapply(df, function(x) x <- stats::rnorm(n = nrows, mean = mean, sd = sd))
  }
  if (type == "uniform") {
    df[] <- sapply(df, function(x) x <- sample(min:max, nrows, replace = TRUE))
  }
  return(df)
}

generate_correlation_matrix <- function(correlation_martix, nrows = 10) {
  if (missing(correlation_martix)) {
    correlation_martix <- symmetric_matrix(as.matrix(generate_data(ncols = nrows, nrows = nrows, min = 0.1, max = 1, type = "uniform")))
    diag(correlation_martix) <- 1
  }
  L <- chol(correlation_martix)
  nvars <- dim(L)[1]
  t(L) %*% L
  r <- t(L) %*% matrix(stats::rnorm(nvars * nrows), nrow = nvars, ncol = nrows)
  r <- data.frame(t(r))
  return(r)
}

simulate_correlation_from_sample <- function(cordata, nrows = 10) {
  cordata_cov <- cov(cordata, use = "pairwise.complete.obs")
  cordata_means <- colMeans(cordata, na.rm = TRUE)
  result <- data.frame(MASS::mvrnorm(nrows, Sigma = cordata_cov, mu = cordata_means))
  return(result)
}

rad2deg<-function(radians){(radians*180)/(pi)}

matrix_triangle<-function(m,off_diagonal=NA,diagonal=NULL,type="lower") {
  m<-as.matrix(m)
  if (!is.null(dim(m))) {
    matrix_diagonal<-diag(m)
    if(type=="lower") {
      md<-lower.tri(m,diag=TRUE)*m
      md[upper.tri(md)]<-off_diagonal
    }
    if(type=="upper") {
      md<-upper.tri(m,diag=TRUE)*m
      md[lower.tri(md)]<-off_diagonal
    }
    if(!is.null(diagonal))
      diag(md)<-diagonal
    return(md)
  } else
    return(m)
}

symmetric_matrix<-function(matrix,duplicate="lower",diagonal=NULL) {
  if (missing(diagonal))
    diagonal<-diag(matrix)
  if(duplicate=="lower")
    matrix[upper.tri(matrix)]<-t(matrix)[upper.tri(matrix)]
  if(duplicate=="upper")
    matrix[lower.tri(matrix)]<-t(matrix)[lower.tri(matrix)]
  rownames(matrix)<-colnames(matrix)
  diag(matrix)<-diagonal
  return(matrix)
}

off_diagonal_index<-function(length){
  index<-data.frame(x1=0,x2=0,x3=0,x4=0)
  for (i in 1:length) {
    p<-i+1
    m<-i-1
    index[i,]=c(i,i,p,m)
  }
  return(index)
}

plot_multiplot <- function(..., plotlist = NULL, cols = 2, layout = NULL) {
  p <- list()
  plots <- c(list(...), plotlist)
  nplots <- length(plots)
  if (is.null(layout)) {
    layout <- matrix(seq(1, cols * ceiling(nplots / cols)),
      ncol = cols,
      nrow = ceiling(nplots / cols), byrow = TRUE
    )
  }
  if (nplots == 1) {
    return(plots[[1]])
  } else {
    pages <- ceiling(nplots / max(layout))
    plots_per_page <- max(layout)
    counter <- 1
    for (page in 1:pages) {
      grid::grid.newpage()
      grid::pushViewport(viewport(layout = grid.layout(nrow(layout), ncol(layout))))
      for (i in 1:plots_per_page) {
        position <- as.data.frame(which(layout == i, arr.ind = TRUE))
        if (counter <= nplots) {
          print(plots[[counter]], vp = grid::viewport(layout.pos.row = position$row, layout.pos.col = position$col))
        }
        counter <- counter + 1
      }
      p[[page]] <- grDevices::recordPlot()
    }
  }
  return(p)
}

report_pdf <- function(..., plotlist = NULL, file = NULL, title = NULL, w = 10, h = 10, print_plot = TRUE) {
  plotlist <- c(list(...), plotlist)
  if (!is.null(title)) {
    title <- paste0("_", title)
  }
  if (!is.null(file)) {
    cairo_pdf(invisible(paste0(file, title, ".pdf")), onefile = TRUE, width = w, height = h)
    purrr::walk(plotlist, function(p) {
      print(p)
    })
    grDevices::dev.off()
  }
  if (print_plot) {
    purrr::walk(plotlist, function(p) {
      print(p)
    })
  }
}

flatten_list <- function(mydata) {
  result <- plyr::ldply(lapply(mydata, function(x) {
    data.frame(x, stringsAsFactors = FALSE)
  }))
  return(result)
}

compute_adjustment <- function(a, ntests) {
  sidak <- 1 - ((1 - a)^(1 / ntests))
  bonferroni <- a / ntests
  result <- list(sidak = sidak, bonferroni = bonferroni)
  return(result)
}

compute_skewness <- function(vector) {
  vector <- na.omit(vector)
  n <- length(vector)
  x <- vector - mean(vector)
  y <- sqrt(n) * sum(x^3) / (sum(x^2)^(3 / 2))
  y <- y * ((1 - 1 / n))^(3 / 2)
  return(y)
}

compute_kurtosis <- function(vector) {
  vector <- na.omit(vector)
  n <- length(vector)
  x <- vector - mean(vector)
  r <- n * sum(x^4) / (sum(x^2)^2)
  y <- r * (1 - 1 / n)^2 - 3
  return(y)
}

compute_standard_error <- function(vector) {
  x <- na.omit(vector)
  y <- sqrt(var(x) / length(x))
  return(y)
}

fixed <- function(pattern) {
  structure(pattern, class = "fixed_pattern")
}

str_replace_all <- function(string, pattern, replacement) {
  if (inherits(pattern, "fixed_pattern")) {
    gsub(as.character(pattern), replacement, string, fixed = TRUE)
  } else if (is.character(pattern) && length(pattern) > 1 && !is.null(names(pattern))) {
    for (i in seq_along(pattern)) {
      string <- gsub(names(pattern)[i], pattern[i], string, perl = TRUE)
    }
    string
  } else {
    gsub(pattern, replacement, string, perl = TRUE)
  }
}

str_replace <- function(string, pattern, replacement) {
  if (inherits(pattern, "fixed_pattern")) {
    sub(as.character(pattern), replacement, string, fixed = TRUE)
  } else {
    sub(pattern, replacement, string, perl = TRUE)
  }
}

str_wrap <- function(string, width = 80) {
  vapply(string, function(x) paste(strwrap(x, width = width), collapse = "\n"),
    character(1),
    USE.NAMES = FALSE
  )
}

str_split_fixed <- function(string, pattern, n) {
  if (inherits(pattern, "fixed_pattern")) {
    parts <- strsplit(string, as.character(pattern), fixed = TRUE)
  } else {
    parts <- strsplit(string, pattern, perl = TRUE)
  }
  t(vapply(parts, function(x) {
    length(x) <- n
    x[is.na(x)] <- ""
    x
  }, character(n)))
}

str_pad <- function(string, width, side = "right", pad = " ") {
  string <- as.character(string)
  vapply(string, function(s) {
    n <- width - nchar(s)
    if (n <= 0) {
      return(s)
    }
    padding <- paste(rep(pad, n), collapse = "")
    switch(side,
      right = paste0(s, padding),
      left = paste0(padding, s),
      both = {
        lpad <- paste(rep(pad, floor(n / 2)), collapse = "")
        rpad <- paste(rep(pad, ceiling(n / 2)), collapse = "")
        paste0(lpad, s, rpad)
      }
    )
  }, character(1), USE.NAMES = FALSE)
}

str_squish <- function(string) {
  trimws(gsub("\\s+", " ", string))
}

str_proper <- function(x) paste0(toupper(substr(x, 1, 1)), tolower(substring(x, 2)))

str_aes <- function(vector, characterlist = c(".", "_", "-", ",", "$", "<p>", "</p>", "<br>", "<br/>", "<B>", "</B>", "<BR/>", "|", "/", "&nbsp"), proper = TRUE) {
  for (i in characterlist) {
    vector <- gsub(i, " ", vector, fixed = TRUE)
  }
  result <- trimws(vector, which = "both")
  if (proper) {
    result <- str_proper(vector)
  }
  result <- str_squish(result)
  return(result)
}

call_to_string <- function(model) {
  result <- toString(deparse(model$call))
  if (result == "NULL") {
    result <- toString(deparse(model$Call))
  }
  result <- gsub(" ", "", result, fixed = TRUE)
  return(result)
}

output_separator <- function(string, output = NULL, instruction = NULL, length = getOption("width") / 2) {
  separator_title <- paste0(rep("#", length), sep = "", collapse = "")
  separator_subtitle <- paste0(rep("#", length / 2), sep = "", collapse = "")
  print(separator_title)
  print(string)
  print(separator_title)
  if (!is.null(instruction)) {
    print(instruction)
    print(separator_subtitle)
  }
  if (!is.null(output)) {
    print(output)
  }
}

plot_roc<-function(observed,predicted,base_size=10,title="") {
  plotlist<-list()
  rco1<-pROC::roc(observed,predicted,ci=TRUE,levels=as.factor(rev(sort(unique(observed)))),quiet=TRUE)
  rco2<-pROC::roc(observed,predicted,ci=TRUE,levels=as.factor(sort(unique(observed))),quiet=TRUE)
  rp<-function(rco) {
    plot<-pROC::ggroc(rco,alpha=0.5)+
      geom_abline(intercept=1,slope=1)+
      labs(title=paste("ROC",title),
           caption=paste0("Observations:",length(observed),
                          "\nAUC:",round(as.numeric(as.character(rco$auc))*100,2),"%",
                          "\nControl Level:",as.character(rco$levels),
                          "\nDirection:",rco$direction))+
      theme_bw(base_size=base_size)+
      coord_fixed()
    return(plot)
  }
  plotlist[[toString(rco1$levels)]]<-rp(rco1)
  plotlist[[toString(rco2$levels)]]<-rp(rco2)
  return(plotlist)
}

plot_confusion<-function(observed,predicted,base_size=10,title="") {
  value<-NULL
  cmatrixp<-confusion_matrix_percent(observed=observed,predicted=predicted)
  cmatrix<-confusion(observed=observed,predicted=predicted)
  pa<-proportion_accurate(observed=observed,predicted=predicted)
  observations<-sum(cmatrix)
  cmatrix<-reshape2::melt(cmatrix)
  cmatrix$observed<-factor(cmatrix$observed,levels=rev(sort(unique(cmatrix$observed))))
  cmatrix$predicted<-factor(cmatrix$predicted,levels=sort(unique(cmatrix$predicted)))
  plot_confusion<-ggplot(cmatrix,aes(x=observed,y=predicted,fill=value))+
    geom_tile(color="white")+
    geom_text(aes(x=observed,y=predicted,label=value),color="black",size=base_size/2)+
    theme_bw(base_size=base_size)+
    theme(axis.ticks.x=element_blank(),
          axis.ticks.y=element_blank(),
          panel.grid.major=element_blank(),
          panel.grid.minor=element_blank(),
          panel.border=element_blank(),
          panel.background=element_blank(),
          legend.position="none")+
    scale_fill_continuous(low="#fafaff")+
    scale_x_discrete(position="top")+
    labs(title=paste("Confusion Matrix",title),
         caption=paste0("Observations:",observations,
                        "\nAccuracy:",round(pa$cm_diagonal,2),
                        "\nAccuracy with off diagonals:",round(pa$cm_off_diagonal,2),
                        "\nKappa unweighted:",round(pa$kappa_unweighted,2),
                        "\nKappa linear:",round(pa$kappa_linear,2),
                        "\nKappa squared:",round(pa$kappa_squared,2)))+
    coord_fixed()
  return(plot_confusion)
}

plot_separability<-function(observed,predicted,base_size=10,title="") {
  df<-data.frame(observed=as.factor(observed),predicted=predicted)
  plot<-ggplot(df,aes(x=predicted,color=factor(observed)))+
    geom_density(size=1)+
    labs(title=paste("Predicted proportion vs Observed category",title),
         color="observed",
         caption=paste0("Observations:",nrow(df)))+
    theme_bw(base_size=base_size)
  return(plot)
}

result_confusion_performance<-function(observed,predicted,step=.1,base_size=10,title="") {
  cut_point<-value<-variable<-NULL
  df_cut_performance<-data.frame()
  min_predicted<-min(predicted,na.rm=TRUE)
  max_predicted<-max(predicted,na.rm=TRUE)
  for(i in seq(min_predicted,max_predicted,by=step)) {
    confusion(observed=observed,predicted=ifelse(predicted>i,1,0))
    cmatrix<-confusion_matrix_percent(observed=observed,predicted=ifelse(predicted>i,1,0))
    collumn_proportion<-data.frame(Collumn_Observed=t(as.numeric(cmatrix[1:(nrow(cmatrix)-2),length(cmatrix)])))
    row_proportion<-data.frame(Row_Predicted=t(as.numeric(cmatrix[nrow(cmatrix),1:(length(cmatrix)-2)])))
    overall<-as.numeric(cmatrix[nrow(cmatrix),length(cmatrix)])
    result<-data.frame(cut_point=i,Overall=overall,collumn_proportion,row_proportion)
    df_cut_performance<-plyr::rbind.fill(df_cut_performance,result)
  }
  cp<-reshape2::melt(df_cut_performance,id.vars="cut_point")
  df_cut_performance$Mean_proportion<-rowMeans(df_cut_performance[,3:length(df_cut_performance)],na.rm=TRUE)
  mcp<-df_cut_performance[df_cut_performance$Mean_proportion %in% max(df_cut_performance$Mean_proportion),"cut_point"]
  cmatrix<-confusion(observed=observed,predicted=ifelse(predicted>mean(mcp,na.rm=TRUE),1,0))
  cmatrixp<-confusion_matrix_percent(observed=observed,predicted=ifelse(predicted>mean(mcp,na.rm=TRUE),1,0))
  plot_performance<-ggplot(cp,aes(x=cut_point,y=value,color=variable,linetype=variable))+
    geom_line(size=1)+
    geom_vline(xintercept=mcp,size=1)+
    labs(title=paste("Confusion Matrix Performance",title),
         x="Cut Point",
         y="Proportion Correct",
         caption=paste0("Observations:",nrow(df_cut_performance),"\nCut point:",round(mcp,4)))+
    theme(legend.title=element_blank())+
    scale_color_discrete(name="")+
    scale_linetype(name="")+
    theme_bw(base_size=base_size)
  result<-list(plot_performance=plot_performance,
               cut_performance=df_cut_performance,
               cut=mcp,
               confusion_matrix=cmatrixp)
  return(result)
}

k_fold<-function(df,model_formula,k=10) {
  variable_names<-names(stats::get_all_vars(model_formula,data=df))
  index<-sample(cut(1:nrow(df),breaks=k,labels=FALSE))
  rows<-1:nrow(df)
  fold<-xgboost<-list()
  df<-stats::get_all_vars(model_formula,df)
  predictors<-all.vars(model_formula[[3]])
  outcome<-all.vars(model_formula[[2]])
  for (i in 1:k) {
    k_index<-paste0("f",i)
    fold[["index"]][[k_index]]<-iteration_index<-which(index==i)
    fold[["train"]][[k_index]]<-train<-df[rows[-iteration_index],]
    fold[["test"]][[k_index]]<-test<-df[rows[iteration_index],]
    fold[["x_test"]][[k_index]]<-test[,predictors]
    fold[["y_test"]][[k_index]]<-test[,outcome]
    xgbtrain<-xgboost::xgb.DMatrix(data=data.matrix(train[,predictors]),label=train[,outcome])
    xgbtest<-xgboost::xgb.DMatrix(data=data.matrix(test[,predictors]),label=test[,outcome])
    evals<-list(train=xgbtrain,test=xgbtest)
    xgboost[[k_index]]<-list(train=xgbtrain,test=xgbtest,
                 evals=evals,
                 watchlist=evals,
                             ytrain=fold$train[[k_index]][,outcome],
                             ytest=fold$test[[k_index]][,outcome])
    cat("Fold Cases:",i,
        "Train:",nrow(train),
        "Test:",nrow(test),
        "Total:",sum(nrow(train),nrow(test)),
        "Unique Train:",length(unique(row.names(train))),
        "Unique Test:",length(unique(row.names(test))),"\n")
  }
  result<-list(f=fold,
               index=index,
               model_formula=model_formula,
               variables=variable_names,
               predictors=predictors,
               outcome=outcome,
               xgb=xgboost)
  return(result)
}

k_sample<-function(df,model_formula,k=1) {
  sv<-function(vector)
    split(vector,ceiling(seq_along(vector)/(length(vector)/2)))
  variable_names<-names(stats::get_all_vars(model_formula,data=df))
  if(k>1) {
    index<-sample(cut(1:nrow(df),breaks=k,labels=FALSE))
  } else {
    index<-rep(1,nrow(df))
  }
  rows<-1:nrow(df)
  fold<-xgb<-list()
  df<-stats::get_all_vars(model_formula,df)
  predictors<-all.vars(model_formula[[3]])
  outcome<-all.vars(model_formula[[2]])
  for (i in 1:k) {
    k_index<-paste0("fold",i)
    iteration_index<-sample(which(index==i))
    train_index<-as.numeric(sv(iteration_index)[[1]])
    test_validation_index<-as.numeric(sv(iteration_index)[[2]])
    test_index<-as.numeric(sv(test_validation_index)[[1]])
    validation_index<-as.numeric(sv(test_validation_index)[[2]])
    fold[["index"]][["train"]][[k_index]]<-rows[train_index]
    fold[["index"]][["test"]][[k_index]]<-rows[test_index]
    fold[["index"]][["validation"]][[k_index]]<-rows[validation_index]
    fold[["train"]][[k_index]]<-train<-df[rows[train_index],]
    fold[["test"]][[k_index]]<-test<-df[rows[test_index],]
    fold[["validation"]][[k_index]]<-validation<-df[rows[validation_index],]
    fold[["x_test"]][[k_index]]<-test[,predictors]
    fold[["y_test"]][[k_index]]<-test[,outcome]
    fold[["x_validation"]][[k_index]]<-validation[,predictors]
    fold[["y_validation"]][[k_index]]<-validation[,outcome]
    xgbtrain<-xgboost::xgb.DMatrix(data=data.matrix(train[,predictors]),label=train[,outcome])
    xgbtest<-xgboost::xgb.DMatrix(data=data.matrix(test[,predictors]),label=test[,outcome])
    xgbvalidation<-xgboost::xgb.DMatrix(data=data.matrix(validation[,predictors]),label=validation[,outcome])
    evals<-list(train=xgbtrain,test=xgbtest)
    xgb[[k_index]]<-list(train=xgbtrain,
                         test=xgbtest,
                         validation=xgbvalidation,
               evals=evals,
               watchlist=evals,
                         ytrain=fold$train[[k_index]][,outcome],
                         ytest=fold$test[[k_index]][,outcome],
                         yvalidation=fold$test[[k_index]][,outcome])
    cat("Fold Cases:",i,
        "Train:",nrow(train),
        "Test:",nrow(test),
        "Validation:",nrow(test),
        "Total:",sum(nrow(train),nrow(test),nrow(validation)),
        "Unique Train:",length(unique(row.names(train))),
        "Unique Test:",length(unique(row.names(test))),
        "Unique Validation:",length(unique(row.names(validation))),
        "\n")
  }
  result<-list(f=fold,
               index=index,
               model_formula=model_formula,
               variables=variable_names,
               predictors=predictors,
               outcome=outcome,
               xgb=xgb)
  
  return(result)
}

recode_scale_dummy<-function(df,categories=10) {
  index_numeric<-names(df[,sapply(df,is.numeric)])
  if(sum(sapply(df,function(x) is.character(x)|is.factor(x)))>1){
    index<-apply(df[,sapply(df,function(x) is.character(x)|is.factor(x))],2,function(x) length(table(x)))<categories
    index<-names(index)[index]
    dummy<-do.call(data.frame,sapply(df[,index],psych::dummy.code,na.rm=TRUE))
  }
  if(sum(sapply(df,function(x) is.character(x)|is.factor(x)))==1){
    index<-sapply(df,function(x) length(unique(x))<categories&&is.character(x)|is.factor(x))
    index<-names(index)[index]
    dummy<-psych::dummy.code(df[,index],na.rm=TRUE)
  }
  if(sum(sapply(df,function(x) is.character(x)|is.factor(x)))==0)
    dummy<-NULL
  maxs<-apply(df[,index_numeric],2,max,na.rm=TRUE)
  mins<-apply(df[,index_numeric],2,min,na.rm=TRUE)
  scale<-as.data.frame(scale(df[,index_numeric],center=mins,scale=maxs-mins))
  if(!is.null(dummy))
    result<-data.frame(dummy,scale)
  else
    result<-scale
  row.names(result)<-row.names(df)
  return(result)
}

proportion_accurate<-function(observed,predicted) {
  cmatrix<-confusion(observed=observed,predicted=predicted)
  train_test<-data.frame(observed=observed,predicted=predicted)
  cm_diagonal<-sum(diag(cmatrix))/sum(matrix(cmatrix,ncol=1))
  index<-off_diagonal_index(nrow(cmatrix))
  data<-c()
  for (i in 1:nrow(cmatrix)){
    data<-c(data,cmatrix[index[i,1],index[i,2]])
    if(index[i,3]>0 && index[i,3]<=nrow(cmatrix))
      data<-c(data,cmatrix[index[i,1],index[i,3]])
    if(index[i,4]>0 && index[i,4]<=nrow(cmatrix))
      data<-c(data,cmatrix[index[i,1],index[i,4]])
  }
  cm_off_diagonal<-sum(data)/sum(matrix(cmatrix,ncol=1))
  kappa_squared<-irr::kappa2(train_test,"squared",sort.levels=TRUE)
  kappa_linear<-irr::kappa2(train_test,"equal",sort.levels=TRUE)
  kappa_unweighted<-irr::kappa2(train_test,"unweighted",sort.levels=TRUE)
  result<-data.frame(cm_diagonal=cm_diagonal,
                     cm_off_diagonal=cm_off_diagonal,
                     kappa_unweighted=kappa_unweighted$value,
                     kappa_linear=kappa_linear$value,
                     kappa_squared=kappa_squared$value)
  return(result)
}

confusion<-function(observed,predicted) {
  levels<-gtools::mixedsort(as.character(unique(c(observed,predicted))),decreasing=FALSE)
  result<-table(predicted=factor(as.character(predicted),levels=levels),
                observed=factor(as.character(observed),levels=levels))
  return(result)
}

confusion_matrix_percent<-function(observed,predicted) {
  cmatrix<-confusion(observed=observed,predicted=predicted)
  overall_accuracy<-sum(as.numeric(diag(cmatrix)))/sum(as.numeric(matrix(cmatrix,ncol=1)))
  cmatrix<-cbind(cmatrix,sum=(apply(cmatrix[,1:ncol(cmatrix)],1,sum,na.rm=TRUE)))
  cmatrix<-rbind(cmatrix,sum=(apply(cmatrix[1:nrow(cmatrix),],2,sum,na.rm=TRUE)))
  dimensions<-dim(cmatrix)
  recall<-precision<-c()
  for (i in 1:dimensions[1]) {
    precision<-c(precision,cmatrix[i,i]/cmatrix[i,ncol(cmatrix)])
    recall<-c(recall,(cmatrix[i,i]/cmatrix[nrow(cmatrix),i]))
  }
  cmatrix<-rbind(cbind(cmatrix,precision),c(recall,overall_accuracy))
  row.names(cmatrix)[nrow(cmatrix)]<-"p"
  colnames(cmatrix)[dim(cmatrix)[[1]]]<-"p"
  cmatrix[is.nan(cmatrix)]<-0
  result<-data.frame(cmatrix,check.names=FALSE)
  result<-format(round(result,2),nsmall=2)
  return(result)
}

compute_kruskal_wallis_test <- function(formula, df) {
  x <- df[, all.vars(formula)[1]]
  g <- factor(df[, all.vars(formula)[2]])
  g <- factor(g)
  k <- nlevels(g)
  n <- length(x)
  r <- rank(x)
  ties <- table(x)
  h <- sum(tapply(r, g, "sum")^2 / tapply(r, g, "length"))
  H <- ((12 * h / (n * (n + 1)) - 3 * (n + 1)) / (1 - sum(ties^3 - ties) / (n^3 - n)))
  df <- (k - 1)
  p <- stats::pchisq(H, df, lower.tail = FALSE)
  etasq <- (H - k + 1) / (n - k)
  epsilonsq <- H / ((n^2 - 1) / (n + 1))
  method <- "Kruskal-Wallis rank sum test"
  result <- data.frame(formula = deparse(formula), method, etasq, epsilonsq, H = H, df = df, p = p, check.names = FALSE)
  return(result)
}

compute_one_way_test <- function(formula, df, var.equal = TRUE) {
  y <- df[, all.vars(formula)[1]]
  g <- factor(df[, all.vars(formula)[2]])
  k <- nlevels(g)
  n.i <- tapply(y, g, length)
  m.i <- tapply(y, g, mean)
  v.i <- tapply(y, g, var)
  w.i <- n.i / v.i
  sum.w.i <- sum(w.i)
  n <- sum(n.i)
  df_effect <- k - 1
  if (var.equal) {
    df_error <- n - k
    ss_effect <- sum(n.i * (m.i - mean(y))^2)
    ss_error <- sum((n.i - 1) * v.i)
    ms_effect <- ss_effect / df_effect
    ms_error <- ss_error / df_error
    method <- "Assuming homoscedasticity"
  } else {
    tmp <- sum((1 - w.i / sum.w.i)^2 / (n.i - 1)) / (k^2 - 1)
    df_error <- 1 / (3 * tmp)
    m <- sum(w.i * m.i) / sum.w.i
    ms_effect <- sum(w.i * (m.i - m)^2)
    ms_error <- df_effect * (1 + 2 * (k - 2) * tmp)
    ss_effect <- ms_effect * df_effect
    ss_error <- ms_error * df_error
    method <- "Assuming heteroscedasticity"
  }

  ss_total <- sum(ss_effect + ss_error)
  statistic <- ms_effect / ms_error
  p <- stats::pf(q = statistic, df1 = df_effect, df2 = df_error, lower.tail = FALSE)

  etasq <- ss_effect / ss_total
  partial.etasq <- ss_effect / (ss_effect + ss_error)
  omegasq <- (ss_effect - df_effect * ms_error) / (ss_total + ms_error)
  partial.omegasq <- (df_effect * (ms_effect - ms_error)) / (df_effect * ms_effect + (n - df_effect) * ms_error)
  cohens.f <- sqrt(etasq / (1 - etasq))
  lambda <- cohens.f * (df_effect + df_error + 1)
  power <- stats::pf(stats::qf(0.05, df_effect, df_error, lower = FALSE), df_effect, df_error, lambda, lower = FALSE)
  result <- data.frame(
    formula = deparse(formula), method, ss_effect, ss_error, ms_effect, ms_error,
    etasq, partial.etasq, omegasq, partial.omegasq, cohens.f, power,
    statistic, df_effect, df_error, p, check.names = FALSE
  )
  return(result)
}

report_oneway <- function(df, dv, iv, file = NULL, w = 10, h = 10, base_size = 10, note = "", title = "", type = "ci", plot_means = FALSE, plot_diagnostics = FALSE) {
  instruction <- list(
    fisher = "Fisher assumes heteroscedasticity",
    welch = "Welch does not assume heteroscedasticity",
    kruskal = "Kruskal Wallis procedure does not assume normality but it is not an alternative for violations of heteroscedasticity",
    tukey = "Posthoc Tuckey: not good for unequal sample sizes or heteroscedasticity",
    games_howell = "Posthoc Games Howell: good for unequal sample sizes and heteroscedasticity",
    homogeneity_instruction = "significant tests show heteroscedasticity and suggest the use of Welch or alternative procedures. Levene test depends on normality: Non normal distributions may result in false significant results. Sample size may affect test results"
  )

  df_fisher <- df_welch <- df_kruskal <- df_tukey <- df_games_howell <- df_levene <- df_bartlett <- data.frame()

  combinations <- expand.grid(names(df)[iv], names(df)[dv])
  names(combinations) <- c("iv", "dv")
  row.names(combinations) <- paste0(combinations$iv, "_", combinations$dv)
  combinations <- change_data_type(combinations, type = "character")
  pb <- txtProgressBar(min = 0, max = length(iv) * length(dv), style = 3)

  for (i in 1:nrow(combinations)) {
    setTxtProgressBar(pb, i)
    factors <- combinations$iv[i]
    cors <- combinations$dv[i]

    tempdata <- df[complete.cases(df[, c(factors, cors)]), ]
    tempdata <- tempdata[tempdata[, factors] %in% names(table(tempdata[, factors]))[table(tempdata[, factors]) > 1], ]
    tempdata[, factors] <- factor(tempdata[, factors])
    if (length(unique(tempdata[, factors])) > 1) {
      form <- formula(paste0(cors, "~", factors))
      fisher <- compute_one_way_test(form, df = tempdata, var.equal = TRUE)
      welch <- compute_one_way_test(form, df = tempdata, var.equal = FALSE)
      kruskal <- compute_kruskal_wallis_test(form, df = tempdata)
      levene.test <- car::leveneTest(form, data = tempdata, center = mean)
      bartlett.test <- stats::bartlett.test(form, data = tempdata)

      df_fisher <- rbind(df_fisher, data.frame(DV = cors, IV = factors, fisher, check.names = FALSE))
      df_welch <- rbind(df_welch, data.frame(DV = cors, IV = factors, welch, check.names = FALSE))
      df_kruskal <- rbind(df_kruskal, data.frame(IV = factors, DV = cors, kruskal, check.names = FALSE))
      df_levene <- rbind(df_levene, data.frame(
        Test = "Levene", DV = cors, IV = factors,
        Statistic = levene.test$`F value`[1],
        df_1 = levene.test$Df[1],
        df_2 = levene.test$Df[2],
        p = levene.test$`Pr(>F)`[1],
        check.names = FALSE
      ))
      df_bartlett <- rbind(df_bartlett, data.frame(
        Test = "Bartlett", DV = cors, IV = factors,
        Statistic = bartlett.test$statistic[[1]],
        df_1 = bartlett.test$parameter[[1]],
        p = bartlett.test$p.value,
        check.names = FALSE
      ))

      post_hoc <- compute_posthoc(tempdata[, cors], tempdata[, factors])
      tukey <- data.frame(Method = "Tukey", IV = factors, DV = cors, LEVEL = rownames(post_hoc$output$tukey), post_hoc$output$tukey, row.names = NULL)
      games.howell <- data.frame(method = "Games Howell", IV = factors, DV = cors, LEVEL = rownames(post_hoc$output$games.howell), post_hoc$output$games.howell, row.names = NULL)
      df_tukey <- rbind(df_tukey, tukey)
      df_games_howell <- rbind(df_games_howell, games.howell)
    }
  }
  close(pb)

  adjustment <- compute_adjustment(0.05, i)$bonferroni
  df_fisher$bonferroni_p <- df_welch$bonferroni_p <- df_kruskal$bonferroni_p <- df_levene$bonferroni_p <- df_bartlett$bonferroni_p <- adjustment
  df_tukey$bonferroni_p <- df_games_howell$bonferroni_p <- adjustment

  df_fisher$significant <- as.character(df_fisher$p < adjustment)
  df_welch$significant <- as.character(df_welch$p < adjustment)
  df_kruskal$significant <- as.character(df_kruskal$p < adjustment)
  df_tukey$significant <- as.character(df_tukey$p < adjustment)
  df_games_howell$significant <- as.character(df_games_howell$p < adjustment)

  homogeneity <- plyr::rbind.fill(df_levene, df_bartlett)
  homogeneity$significant <- as.character(homogeneity$p < adjustment)

  result <- list(
    instructions = instruction,
    fisher = df_fisher, welch = df_welch, kruskal_wallis = df_kruskal, games_howell = df_games_howell, tukey = df_tukey,
    homogeneity = homogeneity
  )

  descriptives <- compute_descriptives(df = df, dv = dv, iv = iv, file = NULL)
  if (plot_diagnostics) {
    diagnostics <- plot_oneway_diagnostics(df, dv, iv, base_size = base_size)
    report_pdf(plotlist = diagnostics, file = file, title = "diagnostics", w = w, h = h, print_plot = FALSE)
  }
  if (plot_means) {
    oneway_means <- plot_oneway(df, dv = dv, iv = iv, base_size = base_size, note = note, title = title, type = type)
    report_pdf(plotlist = oneway_means$plots, file = file, title = "means", w = w, h = h, print_plot = FALSE)
  }

  comment_text <- list(
    DV = "Dependent Variable",
    IV = "Independent Variable",
    bonferroni_p = "Bonferonni adjustment\nadjusted critical value of p for familiwise error",
    significant = "Significant test after familiwise error (Bonferonni) adjustment"
  )

  comment_fisher_welch <- c(comment_text, list(
    formula = "Model spesification",
    ss_effect = "Sum of Squares\nfor Effect",
    ss_error = "Sum of Squares\nfor Error",
    ms_effect = "Mean Sum of Squares\nfor Effect",
    ms_error = "Mean Sum of Squares\nfor Error",
    df_effect = "Degrees of Freedom\nfor Effect",
    df_error = "Degrees of Freedom\nfor Error",
    etasq = "Effect size\neta squared\n0.01 ~ small\n0.06 ~ medium\n0.14 ~ large",
    partial.etasq = "Effect size\npartial eta squared\n0.01 ~ small\n0.06 ~ medium\n0.14 ~ large",
    omegasq = "Effect size\nomega squared\n0.01 ~ small\n0.06 ~ medium\n0.14 ~ large",
    partial.omegasq = "Effect size\npartial omega squared",
    cohens.f = "Effect size\nCohen's f\n0.14 ~ small\n0.39 ~ medium\n0.59 ~ large",
    statistic = "F"
  ))

  if (!is.null(file)) {
    filename <- paste0(file, ".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb <- openxlsx::createWorkbook()
    excel_critical_value(result$fisher, wb, "Fisher",
      critical = list(p = "<0.05"),
      title = instruction$fisher, comment = comment_fisher_welch
    )
    excel_critical_value(result$welch, wb, "Welch",
      critical = list(p = "<0.05"),
      title = instruction$welch, comment = comment_fisher_welch
    )
    excel_critical_value(result$kruskal_wallis, wb, "Kruskal",
      critical = list(p = "<0.05"),
      title = instruction$kruskal,
      comment = c(comment_text, list(
        formula = "Model spesification",
        etasq = "Effect size\neta squared\n0.01 ~ small\n0.06 ~ medium\n0.14 ~ large",
        df = "Degrees of Freedom"
      ))
    )
    excel_critical_value(result$homogeneity, wb, "Homogeneity",
      critical = list(p = "<0.05"),
      title = instruction$homogeneity, comment = comment_text
    )
    excel_critical_value(result$games_howell, wb, "Games-Howell",
      critical = list(p = "<0.05"),
      title = instruction$games_howell, comment = comment_text
    )
    excel_critical_value(descriptives, wb, "Descriptives")
    openxlsx::saveWorkbook(wb = wb, file = filename, overwrite = TRUE)
  }
  return(result)
}

report_factorial_anova <- function(df, dv, wid, within = NULL, within_full = NULL, between = NULL, within_covariates = NULL, between_covariates = NULL,
                                   observed = NULL, diff = NULL, reverse_diff = FALSE, type = 3, white.adjust = TRUE, detailed = TRUE, return_aov = TRUE,
                                   file = NULL, post_hoc_test = TRUE, base_size = 15) {
  comment <- list(
    DFn = "Degrees of Freedom\nfor numerator",
    DFd = "Degrees of Freedom\nfor denominator",
    SSn = "Sum of Squares\nfor numerator",
    SSd = "Sum of Squares\nfor denominator",
    dv = "Dependent Variable",
    df = "Degrees of Freedom",
    sumsq = "Sum of squares",
    meansq = "Mean sum of squares",
    statistic = "F value",
    p.value = "p for F value",
    etasq = "Effect size\neta squared\n  0.01 ~ small\n  0.06 ~ medium\n0.014 ~ large",
    partial.etasq = "Effect size\npartial eta squared",
    omegasq = "Effect size\nomega squared\n  0.01 ~ small\n  0.06 ~ medium\n0.014 ~ large",
    partial.omegasq = "Effect size\npartial omega squared",
    epsilonsq = "Effect size\nepsilon squared",
    cohens.f = "Effect size\nCohen's f\n0.14 ~ small\n0.39 ~ medium\n0.59 ~ large",
    power = "power",
    "DFn[L]" = "Levene test\nDegrees of Freedom\nfor numerator",
    "DFd[L]" = "Levene test\nDegrees of Freedom\nfor denominator",
    "SSn[L]" = "Levene test\nSum of squares\nfor numerator",
    "SSd[L]" = "Levene test\nSum of squares\nfor denominator",
    "F[L]" = "Levene test\nF",
    "p[L]" = "Levene test\np\nif significant, the assumption of homoscedasticity is violated",
    "W[M]" = "Mauchly's Test\nW",
    "p[M]" = "Mauchly's Test\np\nIf significant, the assumption of sphericity is violated",
    "GGe" = "Greenhouse-Geisser\nepsilon",
    "p[GG]" = "Greenhouse-Geisser\np adjusted for violated sphericity",
    "HFe" = "Huynd-Feldt\n epsilon",
    "p[HF]" = "Huynd-Feldt\np adjusted for violated sphericity"
  )
  testdata <- df
  call_arguments <- match.call()
  call_string <- gsub(" ", "", gsub("\"", " ", gsub(", ,", ",", toString(unlist(deparse(call_arguments))))))
  options(contrasts = c("contr.sum", "contr.poly"))
  bonferroni <- compute_adjustment(0.05, length(dv))$bonferroni
  result <- emf <- list()
  post_hoc <- omnibus <- omnibus_effect_size <- data.frame()
  collumn_design <- unique(c(wid, within, within_full, between, within_covariates, between_covariates))
  testdata[, collumn_design] <- lapply(testdata[, collumn_design], as.factor)

  testdata <- plyr::ddply(testdata, collumn_design, plyr::numcolwise(mean, na.rm = TRUE))
  factor_index <- which(names(testdata) %in% unique(c(within, within_full, between)))
  descriptives <- compute_aggregate(df = testdata, iv = factor_index, file = NULL)

  for (dependent in dv) {
    ea_argument <- function(argument) {
      result <- argument
      if (isTRUE(argument)) {
        result <- "TRUE"
      }
      if (isFALSE(argument)) {
        result <- "FALSE"
      }
      if (is.null(argument)) {
        result <- "NULL"
      }
      if (length(argument) > 1) {
        result <- toString(argument)
        result <- paste0(c(".(", result, ")"), collapse = " ")
      }
      return(result)
    }

    ez_text <- paste(
      "ez::ezANOVA(\tdata=testdata,\n",
      "\t\tdv=", ea_argument(dependent), ",\n",
      "\t\twid=", ea_argument(wid), ",\n",
      "\t\twithin=", ea_argument(within), ",\n",
      "\t\twithin_full=", ea_argument(within_full), ",\n",
      "\t\tbetween=", ea_argument(between), ",\n",
      "\t\twithin_covariates=", ea_argument(within_covariates), ",\n",
      "\t\tbetween_covariates=", ea_argument(between_covariates), ",\n",
      "\t\tobserved=", ea_argument(observed), ",\n",
      "\t\tdiff=", ea_argument(diff), ",\n",
      "\t\treverse_diff=", ea_argument(reverse_diff), ",\n",
      "\t\ttype=", ea_argument(type), ",\n",
      "\t\twhite.adjust=", ea_argument(white.adjust), ",\n",
      "\t\tdetailed=", ea_argument(detailed), ",\n",
      "\t\treturn_aov=", ea_argument(return_aov), ")"
    )
    ez <- eval(parse(text = ez_text))

    if (!is.null(ez$`Levene's Test for Homogeneity of Variance`)) {
      ez[[grep("Levene", names(ez))]] <- data.frame(Effect = ez$ANOVA$Effect, ez[[grep("Levene", names(ez))]], check.names = FALSE)
      levene_names <- names(ez[[grep("Levene", names(ez))]])
      names(ez[[grep("Levene", names(ez))]])[2:length(levene_names)] <- paste0(levene_names[2:length(levene_names)], "[L]")
    }
    if (!is.null(ez$`Mauchly's Test for Sphericity`)) {
      mauchly_names <- names(ez[[grep("Mauchly", names(ez))]])
      names(ez[[grep("Mauchly", names(ez))]])[2:length(mauchly_names)] <- paste0(mauchly_names[2:length(mauchly_names)], "[M]")
    }

    result_omnibus <- data.frame(dv = dependent, Reduce(function(x, y) merge(x, y, all = TRUE, sort = FALSE, suffixes = "", no.dups = FALSE), ez[names(ez) != "aov"]), check.names = FALSE, stringsAsFactors = FALSE)
    result_omnibus[, grep("<.05", names(result_omnibus))] <- NULL
    ez$effect_size <- data.frame(dv = dependent, sjstats::anova_stats(ez$aov), check.names = FALSE)
    omnibus <- plyr::rbind.fill(omnibus, result_omnibus)
    omnibus_effect_size <- plyr::rbind.fill(omnibus_effect_size, ez$effect_size)
    iv <- unique(c(within, within_full, between))
    for (i in 1:length(iv)) {
      emf[[i]] <- combn(iv, i)
    }
    for (cf in emf) {
      for (rcf in 1:nrow(cf)) {
        means <- emmeans::emmeans(ez$aov, formula(paste("~", paste(as.character(cf[rcf, ]), collapse = "*"))))
        paired_comparison <- data.frame(dv = dependent, graphics::pairs(means), check.names = FALSE)
        post_hoc <- plyr::rbind.fill(post_hoc, paired_comparison)
      }
    }
    result[[dependent]] <- ez
    # if(!is.null(between)&is.null(within)&is.null(within_full))
    #   plot_diagnostic<-autoplot(ez$aov,which=1:6,ncol=2,label.size=3)+
    #   labs(caption=paste0(deparse(ez$aov$terms),"\nobservations=",nrow(ez$aov$model)))+
    #   theme_bw(base_size=base_size)+
    #   theme(axis.text.x=element_text(angle=45,hjust=1))
  }
  result <- list(omnibus = omnibus, omnibus_effect_size = omnibus_effect_size, post_hoc = post_hoc, object = result)

  if (!is.null(file)) {
    filename <- paste0(file, ".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb <- openxlsx::createWorkbook()
    if (length(omnibus$"p[GG]") > 0) {
      excel_critical_value(omnibus,
        workbook = wb, sheet = "ANOVA within", numFmt = "#0.00", title = paste("Sum of Squares type:", type),
        critical = list(p = "<0.05", "p[M]" = "<0.05", "p[GG]" = "<0.05", "p[HF]" = "<0.05"),
        comment = comment
      )
    }
    if (length(omnibus$"p[L]") > 0) {
      excel_critical_value(omnibus,
        workbook = wb, sheet = "ANOVA between", numFmt = "#0.00", title = paste("Sum of Squares type:", type),
        critical = list(p = "<0.05", "p[L]" = "<0.05"),
        comment = comment
      )
    }
    if (length(omnibus$"p[L]") == 0 & length(omnibus$"p[GG]") == 0) {
      excel_critical_value(omnibus, workbook = wb, sheet = "ANOVA", critical = list(p = "<0.05"), numFmt = "#0.00", title = paste("Sum of Squares type:", type), comment = comment)
    }
    excel_critical_value(omnibus_effect_size, workbook = wb, sheet = "effect size", critical = list("p.value" = "<0.05"), comment = comment, numFmt = "#0.00")
    if (nrow(post_hoc) > 0 & post_hoc_test) {
      excel_critical_value(post_hoc, workbook = wb, sheet = "post hoc", critical = list("p.value" = "<0.05"), numFmt = "#0.00")
    }
    excel_critical_value(descriptives, workbook = wb, sheet = "descriptives", numFmt = "#0.00")
    excel_critical_value(data.frame(call = call_string), workbook = wb, sheet = "call", numFmt = "#0.00")
    openxlsx::saveWorkbook(wb = wb, file = filename, overwrite = TRUE)
  }
  return(result)
}

report_manova <- function(model, file = NULL) {
  pillai <- data.frame(Group = row.names(summary(model, intercept = TRUE, test = c("Pillai"))$stats), summary(model, intercept = TRUE, test = c("Pillai"))$stats, check.names = FALSE)
  wilks <- data.frame(Group = row.names(summary(model, intercept = TRUE, test = c("Wilks"))$stats), summary(model, intercept = TRUE, test = c("Wilks"))$stats, check.names = FALSE)
  hotelling <- data.frame(Group = row.names(summary(model, intercept = TRUE, test = c("Hotelling-Lawley"))$stats), summary(model, intercept = TRUE, test = c("Hotelling-Lawley"))$stats, check.names = FALSE)
  roy <- data.frame(Group = row.names(summary(model, intercept = TRUE, test = c("Roy"))$stats), summary(model, intercept = TRUE, test = c("Roy"))$stats, check.names = FALSE)
  type_three <- car::Anova(model, type = "III")
  pillai$type <- "Pillai"
  wilks$type <- "Wilks"
  hotelling$type <- "Hotelling-Lawley"
  roy$type <- "Roy"
  names(pillai)[3] <- names(wilks)[3] <- names(hotelling)[3] <- names(roy)[3] <- "Statistic"
  pwhr <- rbind(pillai, wilks, hotelling, roy)
  row.names(pwhr) <- NULL
  output_separator("Pillai,Wilks,Hotelling-Lawley,Roy Statistics", output = pwhr)
  output_separator("type Three", output = type_three)
  call <- data.frame(toString(deparse(model$call)))
  if (!is.null(file)) {
    filename <- paste0(file, ".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb <- openxlsx::createWorkbook()
    excel_critical_value(pwhr, wb, "critical", critical = list("Pr(>F)" = "<0.05"), numFmt = "#0.00")
    excel_critical_value(call, wb, "call", numFmt = "#0.00")
    openxlsx::saveWorkbook(wb = wb, file = filename, overwrite = TRUE)
  }
}

compute_aov_es <- function(model, ss = "I") {
  n_total <- nrow(stats::model.frame(model))
  ss1 <- data.frame(summary(model)[[1]], check.names = FALSE)
  ss2 <- data.frame(car::Anova(model, type = "II"), check.names = FALSE)
  ss3 <- data.frame(car::Anova(model, type = "III"), check.names = FALSE)
  ss2$`Mean Sq` <- ss2$`Sum Sq` / ss2$Df
  ss3$`Mean Sq` <- ss3$`Sum Sq` / ss3$Df
  ss2 <- ss2[, c("Df", "Sum Sq", "Mean Sq", "F value", "Pr(>F)")]
  ss3 <- ss3[, c("Df", "Sum Sq", "Mean Sq", "F value", "Pr(>F)")]

  if (ss == "I") {
    summary_aov <- ss1
  }
  if (ss == "II") {
    summary_aov <- ss2
  }
  if (ss == "III") {
    summary_aov <- ss3[2:nrow(ss3), ]
    intercept <- ss3[1, ]
  }

  residual_row <- nrow(summary_aov)
  ms_effect <- summary_aov[1:(residual_row - 1), 3]
  ms_error <- summary_aov[residual_row, 3]
  df_effect <- summary_aov[1:(residual_row - 1), 1]
  df_error <- summary_aov[residual_row, 1]
  ss_effect <- summary_aov[1:(residual_row - 1), 2]
  ss_error <- summary_aov[residual_row, 2]
  ss_total <- rep(sum(summary_aov[1:residual_row, 2]), residual_row - 1)

  omega <- abs((ss_effect - df_effect * ms_error) / (ss_total + ms_error))
  partial_omega <- abs((df_effect * (ms_effect - ms_error)) / (ss_effect + (n_total - df_effect) * ms_error))
  names(omega) <- names(partial_omega) <- trimws(rownames(summary_aov)[1:(residual_row - 1)])
  eta <- ss_effect / ss_total
  partial_eta <- ss_effect / (ss_effect + ss_error)
  cohens_f <- sqrt(partial_eta / (1 - partial_eta))
  epsilon <- (ss_effect - df_effect * ms_error) / ss_total

  if (ss == "III") {
    summary_aov <- rbind_all(intercept, summary_aov)
  }

  summary_aov <- data.frame(
    call = deparse(eval(model$call$formula)),
    ss = ss,
    comparisons = trimws(row.names(summary_aov)),
    summary_aov,
    check.names = FALSE
  )

  result <- data.frame(
    call = deparse(eval(model$call$formula)),
    ss = ss,
    comparisons = names(omega),
    etasq = eta,
    partial_etasq = partial_eta,
    omegasq = omega,
    partial_omegasq = partial_omega,
    epsilonsq = epsilon,
    cohens_f = cohens_f
  )

  result <- merge(summary_aov, result, all = TRUE, sort = FALSE)
  return(result)
}

compute_posthoc <- function(y, x) {
  res <- list(input = list(x = x, y = y))
  res$intermediate <- list(x = factor(x[complete.cases(x, y)]), y = y[complete.cases(x, y)])
  res$intermediate$n <- tapply(y, x, length)
  res$intermediate$groups <- length(res$intermediate$n)
  res$intermediate$df <- sum(res$intermediate$n) - res$intermediate$groups
  res$intermediate$means <- tapply(y, x, mean)
  res$intermediate$variances <- tapply(y, x, var)
  res$intermediate$pairNames <- utils::combn(levels(res$intermediate$x), 2, paste0, collapse = ":")
  res$intermediate$descriptives <- cbind(res$intermediate$n, res$intermediate$means, res$intermediate$variances)
  rownames(res$intermediate$descriptives) <- levels(res$intermediate$x)
  colnames(res$intermediate$descriptives) <- c("n", "means", "variances")
  # Tukey
  res$intermediate$errorVariance <- sum((res$intermediate$n - 1) * res$intermediate$variances) / res$intermediate$df
  res$intermediate$t <- utils::combn(res$intermediate$groups, 2, function(ij) {
    abs(diff(res$intermediate$means[ij])) / sqrt(res$intermediate$errorVariance * sum(1 / res$intermediate$n[ij]))
  })
  res$intermediate$p.tukey <- stats::ptukey(res$intermediate$t * sqrt(2), res$intermediate$groups, res$intermediate$df, lower.tail = FALSE)
  res$output <- list()
  res$output$tukey <- cbind(res$intermediate$t, res$intermediate$df, res$intermediate$p.tukey)
  rownames(res$output$tukey) <- res$intermediate$pairNames
  colnames(res$output$tukey) <- c("t", "df", "p")
  # Games-Howell
  res$intermediate$df.corrected <- utils::combn(res$intermediate$groups, 2, function(ij) {
    sum(res$intermediate$variances[ij] / res$intermediate$n[ij])^2 / sum((res$intermediate$variances[ij] / res$intermediate$n[ij])^2 / (res$intermediate$n[ij] - 1))
  })
  res$intermediate$t.corrected <- utils::combn(res$intermediate$groups, 2, function(ij) {
    abs(diff(res$intermediate$means[ij])) / sqrt(sum(res$intermediate$variances[ij] / res$intermediate$n[ij]))
  })
  res$intermediate$p.gameshowell <- stats::ptukey(res$intermediate$t.corrected * sqrt(2), res$intermediate$groups, res$intermediate$df.corrected, lower.tail = FALSE)
  res$output$games.howell <- cbind(res$intermediate$t.corrected, res$intermediate$df.corrected, res$intermediate$p.gameshowell)
  rownames(res$output$games.howell) <- res$intermediate$pairNames
  colnames(res$output$games.howell) <- c("t", "df", "p")
  res$intermediate <- NULL
  return(res)
}

plot_oneway <- function(df, dv, iv, base_size = 20, type = "se", order_factor = TRUE, title = "", note = "", width = 60) {
  se <- ci <- NULL
  output_data <- function(i) {
    index <- as.character(combinations[i, ])
    tempdata <- df[complete.cases(df[, index]), index]
    if (length(unique(tempdata[, combinations$iv[i]])) > 1) {
      Rmisc::summarySE(tempdata, measurevar = combinations$dv[i], groupvars = combinations$iv[i], na.rm = TRUE)
    }
  }
  output_plot <- function(i) {
    tempdata <- plot_data[[i]]
    if (!is.null(tempdata)) {
      if (order_factor) {
        means_plot <- ggplot(tempdata, aes(x = reorder(tempdata[, 1], -tempdata[, 3]), y = tempdata[, 3]))
      } else {
        means_plot <- ggplot(tempdata, aes(x = tempdata[, 1], y = tempdata[, 3]))
      }
      means_plot <- means_plot +
        geom_point() +
        labs(
          y = str_aes(names(tempdata)[3]),
          x = str_wrap(str_aes(names(tempdata)[1]), width = width),
          title = title,
          caption = note
        ) +
        theme_bw(base_size = base_size) +
        scale_x_discrete(labels = scales::wrap_format(width)) +
        coord_flip()
      if (type == "se") {
        means_plot <- means_plot + geom_errorbar(aes(ymin = tempdata[, 3] - se, ymax = tempdata[, 3] + se), width = .1) +
          labs(caption = paste("Bars are standard errors", note))
      }
      if (type == "ci") {
        means_plot <- means_plot + geom_errorbar(aes(ymin = tempdata[, 3] - ci, ymax = tempdata[, 3] + ci), width = .1) +
          labs(caption = paste("Bars are confidence intervals", note))
      }
      if (type == "sd") {
        means_plot <- means_plot + geom_errorbar(aes(ymin = tempdata[, 3] - sd, ymax = tempdata[, 3] + sd), width = .1) +
          labs(caption = paste("Bars are standard deviations", note))
      }
      minaxis <- ggplot_build(means_plot)$layout$panel_scales_y[[1]]$range$range[[1]]
      if (!is.null(minaxis)) {
        means_plot <- means_plot + annotate("text", x = tempdata[, 1], y = minaxis, label = paste0("N:", tempdata$N), alpha = .5, size = base_size / 10 * 2, hjust = 0, vjust = 2)
      }
      ggpubr::as_ggplot(gridExtra::arrangeGrob(means_plot))
    }
  }

  df[, iv] <- change_data_type(data.frame(df[, iv]), "factor")
  combinations <- expand.grid(names(df)[iv], names(df)[dv])
  names(combinations) <- c("iv", "dv")
  row.names(combinations) <- paste0(combinations$iv, "_", combinations$dv)
  combinations <- change_data_type(combinations, type = "character")

  n_rows <- nrow(combinations)
  n_cores <- parallel::detectCores()
  use_parallel <- n_cores * 4 < n_rows

  if (use_parallel) {
    message("Parallel processing with ", n_cores, " workers for ", n_rows, " plots")
    future::plan(future::multisession, workers = n_cores)
    plot_data <- setNames(
      future.apply::future_lapply(seq_len(n_rows), output_data, future.seed = TRUE),
      row.names(combinations)
    )
    plots <- setNames(
      future.apply::future_lapply(seq_len(n_rows), output_plot, future.seed = TRUE),
      row.names(combinations)
    )
    future::plan(future::sequential)
  } else {
    plot_data <- setNames(lapply(seq_len(n_rows), output_data), row.names(combinations))
    plots <- setNames(lapply(seq_len(n_rows), output_plot), row.names(combinations))
  }

  plot_data_df <- Reduce(plyr::rbind.fill, plot_data)
  names_input_missing <- setdiff(names(df)[c(iv, dv)], names(plot_data_df))
  names_input <- names(df)[c(iv, dv)]
  names_input <- names_input[!names_input %in% names_input_missing]
  plot_data_df <- plot_data_df[, c(names_input, "N", "sd", "se", "ci")]
  return(list(plot_data = plot_data, plot_data_df = plot_data_df, plots = plots))
}

plot_interaction <- function(df, dv, iv, base_size = 20, type = "se", order_factor = TRUE, title = "", note = "") {
  se <- ci <- NULL
  output_data <- function(i) {
    factors <- c(combinations$iv1[i], combinations$iv2[i])
    cors <- combinations$dv[i]
    tempdata_complete_cases <- df[complete.cases(df[, c(factors, cors)]), c(factors, cors)]
    if (nrow(tempdata_complete_cases) > 1) {
      Rmisc::summarySE(tempdata_complete_cases, measurevar = cors, groupvars = factors, na.rm = TRUE, .drop = TRUE)
    }
  }
  output_plot <- function(i) {
    tempdata <- plot_data[[i]]
    if (!is.null(tempdata)) {
      factors <- c(combinations$iv1[i], combinations$iv2[i])
      cors <- combinations$dv[i]
      tempdata_cases <- plyr::ddply(tempdata, factors[1], plyr::numcolwise(sum, na.rm = TRUE))
      if (order_factor) {
        interactions_plot <- ggplot(tempdata, aes(
          x = reorder(tempdata[, factors[1]], -tempdata[, cors]),
          y = tempdata[, cors],
          color = str_wrap(tempdata[, factors[2]], width = 25),
          group = str_wrap(tempdata[, factors[2]], width = 25)
        ))
      } else {
        interactions_plot <- ggplot(tempdata, aes(
          x = tempdata[, factors[1]],
          y = tempdata[, cors],
          color = str_wrap(tempdata[, factors[2]], width = 25),
          group = str_wrap(tempdata[, factors[2]], width = 25)
        ))
      }
      interactions_plot <- interactions_plot +
        scale_color_discrete(breaks = c(levels(tempdata[, factors[2]])), name = factors[2]) +
        geom_line() +
        geom_point(size = 5) +
        theme_bw(base_size = base_size) +
        guides(color = guide_legend(ncol = 1)) +
        labs(
          y = str_wrap(str_aes(cors), width = 25),
          x = str_wrap(str_aes(factors[1]), width = 25),
          title = title,
          caption = note,
          color = str_wrap(str_aes(tempdata[, factors[2]]), width = 25)
        ) +
        scale_x_discrete(labels = scales::wrap_format(100)) +
        coord_flip()
      if (type == "se") {
        interactions_plot <- interactions_plot +
          geom_errorbar(aes(ymin = tempdata[, cors] - se, ymax = tempdata[, cors] + se), width = .1, position = position_dodge(0.1)) +
          labs(caption = paste("Bars are standard errors", note))
      }
      if (type == "ci") {
        interactions_plot <- interactions_plot +
          geom_errorbar(aes(ymin = tempdata[, cors] - ci, ymax = tempdata[, cors] + ci), width = .1, position = position_dodge(0.1)) +
          labs(caption = paste("Bars are confidence intervals", note))
      }
      if (type == "sd") {
        interactions_plot <- interactions_plot +
          geom_errorbar(aes(ymin = tempdata[, cors] - sd, ymax = tempdata[, cors] + sd), width = .1, position = position_dodge(0.1)) +
          labs(caption = paste("Bars are standard deviations", note))
      }
      minaxis <- ggplot_build(interactions_plot)$layout$panel_scales_y[[1]]$range$range[[1]]
      if (!is.null(minaxis)) {
        interactions_plot <- interactions_plot +
          annotate("text", x = tempdata_cases[, factors[1]], y = minaxis, label = paste("N:", tempdata_cases$N), alpha = .5, size = base_size / 10 * 2, hjust = 0, vjust = 2)
      }
      ggpubr::as_ggplot(gridExtra::arrangeGrob(interactions_plot))
    }
  }

  df[, iv] <- change_data_type(df[, iv], type = "factor")
  combinations <- expand.grid(names(df)[iv], names(df)[iv], names(df)[dv])
  names(combinations) <- c("iv1", "iv2", "dv")
  row.names(combinations) <- paste0(combinations$iv1, "_", combinations$iv2, "_", combinations$dv)
  combinations <- change_data_type(combinations, type = "character")
  combinations <- combinations[-which(combinations$iv1 == combinations$iv2), ]
  combinations <- combinations[!duplicated(combinations), ]

  n_rows <- nrow(combinations)
  n_cores <- parallel::detectCores()
  use_parallel <- n_cores * 4 < n_rows

  if (use_parallel) {
    message("Parallel processing with ", n_cores, " workers for ", n_rows, " plots")
    future::plan(future::multisession, workers = n_cores)
    plot_data <- setNames(
      future.apply::future_lapply(seq_len(n_rows), output_data, future.seed = TRUE),
      row.names(combinations)
    )
    plots <- setNames(
      future.apply::future_lapply(seq_len(n_rows), output_plot, future.seed = TRUE),
      row.names(combinations)
    )
    future::plan(future::sequential)
    gc(full = TRUE)
  } else {
    plot_data <- setNames(lapply(seq_len(n_rows), output_data), row.names(combinations))
    plots <- setNames(lapply(seq_len(n_rows), output_plot), row.names(combinations))
  }

  plot_data_df <- Reduce(plyr::rbind.fill, plot_data)
  plot_data_df <- plot_data_df[, c(names(df)[c(iv, dv)], setdiff(c("N", "sd", "se", "ci"), names(df)[c(iv, dv)]))]
  return(list(plot_data = plot_data, plot_data_df = plot_data_df, plots = plots))
}

plot_oneway_diagnostics <- function(df, dv, iv, base_size = 10) {
  output_plot <- function(i) {
    factors <- combinations$iv[i]
    cors <- combinations$dv[i]
    tempdata <- df[complete.cases(df[, c(cors, factors)]), ]
    tempdata <- tempdata[tempdata[, factors] %in% names(table(tempdata[, factors]))[table(tempdata[, factors]) > 1], ]
    tempdata[, factors] <- factor(tempdata[, factors])
    if (length(unique(tempdata[, factors])) > 1) {
      form <- stats::formula(paste0(cors, "~", factors))
      model <- stats::lm(form, data = tempdata)
      autoplot(model, which = 1:6, ncol = 2, label.size = 3) +
        labs(caption = paste0(deparse(model$terms), "\nobservations=", nrow(model$model))) +
        theme_bw(base_size = base_size) +
        theme(axis.text.x = element_text(angle = 45, hjust = 1))
    }
  }

  combinations <- expand.grid(names(df)[iv], names(df)[dv])
  names(combinations) <- c("iv", "dv")
  row.names(combinations) <- paste0(combinations$iv, "_", combinations$dv)
  combinations <- change_data_type(combinations, type = "character")

  n_rows <- nrow(combinations)
  n_cores <- parallel::detectCores()
  use_parallel <- n_cores * 4 < n_rows

  if (use_parallel) {
    message("Parallel processing with ", n_cores, " workers for ", n_rows, " plots")
    future::plan(future::multisession, workers = n_cores)
    plots <- setNames(
      future.apply::future_lapply(seq_len(n_rows), output_plot, future.seed = TRUE),
      row.names(combinations)
    )
    future::plan(future::sequential)
    gc(full = TRUE)
  } else {
    plots <- setNames(lapply(seq_len(n_rows), output_plot), row.names(combinations))
  }

  return(plots)
}

plot_corrplot<-function(mydata,title="",base_size=10,fill_limits=c(-1,0,1)) {
  Var1<-Var2<-value<-NULL
  mydata<-round(mydata,2)
  upper_tri<-matrix_triangle(mydata,type="upper")
  melted_cormat<-reshape2::melt(upper_tri,na.rm=TRUE)
  plot<-ggplot(melted_cormat,aes(Var2,Var1,fill=value))+
    geom_tile(color="white")+
    scale_fill_gradient2(midpoint=fill_limits[2],limit=fill_limits[c(1,3)])+
    geom_text(aes(Var2,Var1,label=value),color="black",size=base_size/4)+
    theme_bw(base_size=base_size)+
    theme(axis.text.x=element_text(angle=45,vjust=1,hjust=1),
          axis.title.x=element_blank(),
          axis.title.y=element_blank(),
          panel.grid.major=element_blank(),
          panel.grid.minor=element_blank(),
          panel.border=element_blank(),
          panel.background=element_blank(),
          legend.justification=c(1,0),
          legend.position="none")+
    guides(fill=guide_colorbar(barwidth=7,barheight=1,title.position="top",title.hjust=0.5))+
    labs(title=title)
  return(plot)
}

compute_power_r<-function(n=100,r=NULL,sig.level=0.05,alternative=c("two.sided","less","greater"),title="",base_size=10) {
  power<-NULL
  df_power<-data.frame()
  for (i in 10:n) {
    result<-pwr::pwr.r.test(n=i,r=r,sig.level=sig.level,power=NULL,alternative=alternative)
    df_result<-data.frame(n=result$n,r=result$r,p=result$sig.level,power=result$power,alternative=result$alternative,method=result$method)
    df_power<-plyr::rbind.fill(df_power,df_result)
  }
  plot<-ggplot(df_power,aes(x=n,y=power))+
    geom_point(alpha=1)+
    geom_line()+
    labs(x="Observations",y="Power",
         title=title,
         caption=paste0("r power curve:"," r = ",round(r,2),", alpha = ",sig.level))+
    lims(y=c(0,1))+
    theme_bw(base_size=base_size)
  result<-list(plot=plot,power_table=df_power)
  return(result)
}

compute_power_r_matrix<-function(m,...) {
  diag(m)<-NA
  minimum<-compute_power_r(r=min(abs(m),na.rm=TRUE),title="Min absolute r in Correlation Matrix",...)
  maximum<-compute_power_r(r=max(abs(m),na.rm=TRUE),title="Max absolute r in Correlation Matrix",...)
  mean<-compute_power_r(r=mean(abs(m),na.rm=TRUE),title="Mean absolute r in Correlation Matrix",...)
  median<-compute_power_r(r=stats::median(abs(m),na.rm=TRUE),title="Median absolute r in Correlation Matrix",...)
  df_power<-rbind(minimum$power_table,maximum$power_table,mean$power_table,median$power_table)
  plot<-plot_multiplot(minimum$plot,maximum$plot,mean$plot,median$plot)
  result<-list(plot=plot,power_table=df_power)
  return(result)
}

report_correlation<-function(x,y=NULL,use="pairwise",method="pearson",adjust="holm",alpha=.05,ci=TRUE,file=NULL,w=10,h=10,base_size=20,scatterplot=TRUE) {
  function_arguments<-c("Use","Method","Adjustment for Probability values","Alpha","Confidence Interval")
  function_values<-c(use,method,adjust,alpha,ci)
  x<-data.frame(change_data_type(x,type="numeric"))
  result<-psych::corr.test(x,y,use,method,adjust,alpha,ci)
  n_lower<-matrix_triangle(result$n,off_diagonal=NA,diagonal=NA,type="lower")
  if(length(n_lower)==1) {
    n_lower[1,1]<-result$n
    n_lower<-data.frame(n_lower)
    names(n_lower)<-"n"
  }
  correlation_result<-list(r_lower=data.frame(matrix_triangle(result$r,off_diagonal=NA,diagonal=NA,type="lower")),
                           r_squared_lower=data.frame(matrix_triangle(result$r*result$r,off_diagonal=NA,diagonal=NA,type="lower")),
                           p_lower=data.frame(matrix_triangle(result$p,off_diagonal=NA,diagonal=NA,type="lower")),
                           p_lower_adjusted=data.frame(matrix_triangle(symmetric_matrix(matrix_triangle(result$p,off_diagonal=NA,diagonal=NA,type="upper"),duplicate="upper",diagonal=NA),type="lower")),
                           t_lower=data.frame(matrix_triangle(result$t,off_diagonal=NA,diagonal=NA,type="lower")),
                           n_lower=n_lower,
                           se_lower=data.frame(matrix_triangle(result$se,off_diagonal=NA,diagonal=NA,type="lower")),
                           ci=data.frame(result$ci,result$ci.adj),
                           call=data.frame(function_arguments,function_values))
  
  corrplot<-plot_corrplot(result$r,base_size=base_size)
  report_pdf(corrplot,file=file,title="corrplot",w=w,h=h)
  if(scatterplot) {
    scatterplot<-plot_scatterplot(x,base_size=base_size,coord_equal=FALSE,all_orders=FALSE,title="",combinations=NULL)
    report_pdf(plotlist=scatterplot,file=file,title="scatterplot",w=w,h=h)
    results=list(scatterplot,correlation_result)
  }
  if(!is.null(file)) {
    filename<-paste0(file,".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb<-openxlsx::createWorkbook()
    excel_matrix(correlation_result$r_lower,wb,sheet="r",conditional_formatting=TRUE,numFmt="#0.00",comment=NULL)
    excel_matrix(correlation_result$r_squared_lower,wb,sheet="r_squared",conditional_formatting=TRUE,numFmt="#0.00",comment=NULL)
    excel_matrix(correlation_result$p_lower,wb,sheet="p",conditional_formatting=TRUE,numFmt="#0.00",comment=NULL)
    excel_matrix(correlation_result$p_lower_adjusted,wb,sheet="p_adjusted",conditional_formatting=TRUE,numFmt="#0.00",comment=NULL)
    excel_matrix(correlation_result$t_lower,wb,sheet="t",conditional_formatting=TRUE,numFmt="#0.00")
    excel_matrix(correlation_result$n_lower,wb,sheet="N",conditional_formatting=TRUE,numFmt="#0")
    excel_matrix(correlation_result$se_lower,wb,sheet="SE",conditional_formatting=TRUE,numFmt="#0.00")
    excel_matrix(correlation_result$ci,wb,sheet="CI",numFmt="#0.00")
    excel_matrix(correlation_result$call,wb,sheet="Call")
    openxlsx::saveWorkbook(wb,file=filename,overwrite=TRUE)
  }
  return(correlation_result)
}

report_choric_serial<-function(x,y=NULL,file=NULL,w=10,h=10,type="tetrachoric",...) {
  if(type=="tetrachoric")
    result<-psych::tetrachoric(x,...)
  if(type=="polychoric")
    result<-psych::polychoric(x,...)
  if(type=="polyserial")
    result<-data.frame(psych::polyserial(x,y,...))
  if(type=="biserial")
    result<-data.frame(psych::biserial(x,y,...))
  
  if(type=="biserial"||type=="biserial") {
    report_pdf(plot_corrplot(result,title=type),w=w,h=h,file=file,title=type)
    report_dataframe(result,sheet=type,file=file)
  }
  
  if(type=="tetrachoric"||type=="polychoric") {
    report_pdf(plot_corrplot(result$rho,title=type),w=w,h=h,file=file,title=type)
    if(!is.null(file)) {
      filename<-paste0(file,".xlsx")
      if (file.exists(filename)) file.remove(filename)
      wb<-openxlsx::createWorkbook()
      excel_matrix(data.frame(result$rho),wb,sheet="R",conditional_formatting=TRUE,comment=NULL)
      excel_matrix(data.frame(result$rho*result$rho),wb,sheet="R Squared",conditional_formatting=TRUE,comment=NULL)
      excel_matrix(data.frame(result$tau),wb,sheet="Tau",comment=NULL)
      excel_matrix(data.frame(Observations=result$n.obs),wb,sheet="Observations",comment=NULL)
      excel_matrix(data.frame(call=toString(result$Call)),wb,sheet="Call",comment=NULL)
      openxlsx::saveWorkbook(wb,file=filename,overwrite=TRUE)
    }
  }
  return(result)
}

plot_loadings<-function(model,matrix_type=NULL,title="",base_size=10,color=c("#5E912C","white","#5F2C91"),sort=TRUE) {
  ncolours<-30
  colfunc<-colorRampPalette(color[c(1,3)])
  palette_color_complementary<-colfunc(ncolours)
  Relation<-variable<-Correlation<-Loading<-Factor<-NULL
  if(is.null(matrix_type))
    stop("specify matrix_type either pattern or structure")
  load<-model_loadings(model,cut=0,matrix_type=matrix_type,sort=sort)
  correlation_matrix<-data.frame(model$r,variable=row.names(model$r))
  correlation_matrix<-correlation_matrix[order(row.names(correlation_matrix)),order(names(correlation_matrix))]
  if(!sort)
    load<-load[order(row.names(load)),order(names(load))]
  factor_names<-setdiff(names(load),c("Matrix","variable"))
  names_order<-row.names(model$r)
  load<-load[,c(c("Matrix","variable"),factor_names)]
  loadings<-reshape2::melt(load,id="variable",variable.name="Factor",value.name="Loading",measure=factor_names,factorsAsStrings=TRUE)
  # loadings<-reshape2::melt(load,id="variable",measure=factor_names,variable.name="Factor",value.name="Loading")
  correlations<-reshape2::melt(correlation_matrix,id="variable",variable.name="Relation",value.name="Correlation")
  # levels(loadings$variable)<-levels(correlations$variable)<-levels(correlations$Relation)<-names_order
  if(is.null(xlim))
    xlim<-max(loadings$Loading)
  correlation_plot<-ggplot(correlations,aes(Relation,variable,fill=Correlation))+
    geom_tile()+
    scale_fill_gradient2(low=color[1],mid=color[2],high=color[3],midpoint=0)+
    geom_text(aes(label=round(Correlation,2)),size=base_size/4)+
    labs(y="Loading",title="Correlation Matrix")+
    theme_bw(base_size=base_size)+
    theme(axis.title.x=element_blank(),
          axis.title.y=element_blank(),
          axis.text.x=element_text(color="white"),
          legend.position="none")
  stacked_loadings<-ggplot(loadings,aes(variable,abs(Loading),fill=Factor))+
    geom_bar(stat="identity")+
    coord_flip()+
    labs(y="Loading",title=paste(str_proper(matrix_type),"Matrix Loadings"))+
    # scale_fill_manual(values=sample(palette_color_complementary,ncolours/4))+
    theme_bw(base_size=base_size)+
    # lims(y=c(0,1))+
    theme(axis.title.y=element_blank(),
          axis.title.x=element_blank(),
          axis.ticks.y=element_blank(),
          axis.text.y=element_blank())
  correlation_loadings<-ggpubr::ggarrange(plotlist=list(correlation_plot,stacked_loadings))
  plot_barplot<-ggplot(loadings,aes(variable,abs(Loading),fill=Loading))+
    facet_wrap(~Factor,nrow=1)+
    geom_bar(stat="identity")+
    scale_fill_gradient2(name="Loading",high=color[1],mid=color[2],low=color[3],midpoint=0)+
    coord_flip()+
    labs(y="Loading",x="",title=paste(str_proper(matrix_type),"Matrix",title))+
    theme_bw(base_size=base_size)+
    lims(y=c(0,1))
  result<-list(correlation_loadings=correlation_loadings,plot_barplot=plot_barplot)
  return(result)
}

plot_scree<-function(df,base_size=15,title="",color=c("#5F2C91","#5E912C")) {
  x<-NULL
  eigenvalues<-data.frame(eigenvalues=eigen(cor(df,use="pairwise.complete.obs"))$values)
  eigenvalues$x<-as.numeric(row.names(eigenvalues))
  kaiser<-length(eigenvalues$eigenvalues[eigenvalues$eigenvalues>1])
  jolliffe<-length(eigenvalues$eigenvalues[eigenvalues$eigenvalues>.7])
  scree_plot<-ggplot(eigenvalues,aes(x=x,y=eigenvalues))+
    geom_hline(yintercept=1,colour=color[1])+
    geom_hline(yintercept=0.7,colour=color[2])+
    geom_line(color=color[1])+
    geom_point(aes(y=eigenvalues),size=base_size/4,color=color[1])+
    scale_x_continuous(labels=eigenvalues$x,breaks=eigenvalues$x)+
    theme_bw(base_size=base_size)+
    labs(x="index",y="Eigenvalue",title=paste("Scree plot",title))+
    annotate("text",x=nrow(eigenvalues),y=max(eigenvalues$eigenvalues),
             label=paste0("Top line: Kaiser criterion:",kaiser,
                          "\nBottom line: Jolliffe criterion:",jolliffe),
             hjust=1,vjust=1,size=base_size/4)+
    theme(legend.title=element_blank(),legend.position="bottom",axis.title.x=element_blank())
  return(scree_plot)
}

model_loadings<-function(model,cut=NULL,matrix_type="pattern",sort=TRUE,...) {
  loading_critical<-data.frame(sample=c(50,60,70,85,100,120,150,200,250,350),
                               critical_loading=c(.75,.70,.65,.60,.55,.50,.45,.40,.35,.30))
  n<-model$n.obs
  if(is.null(cut))
    cut<-loading_critical[which(abs(loading_critical$sample-n)==min(abs(loading_critical$sample-n))),2]
  if(length(model$values)>0){
    loading_matrix_pattern<-round(model$loadings,2)
    loading_matrix_structure<-round(model$Structure,2)
    if(sort){
      loading_matrix_pattern<-psych::fa.sort(round(model$loadings,2),...)
      loading_matrix_structure<-psych::fa.sort(round(model$Structure,2),...)
    }
    loading_matrix_pattern<-data.frame(Matrix="Pattern",
                                       variable=row.names(loading_matrix_pattern),
                                       ifelse(abs(loading_matrix_pattern)<cut,"",loading_matrix_pattern))
    loading_matrix_structure<-data.frame(Matrix="Structure",
                                         variable=row.names(loading_matrix_structure),
                                         ifelse(abs(loading_matrix_structure)<cut,"",loading_matrix_structure))
    switch(matrix_type,
           pattern={
             loading_matrix<-loading_matrix_pattern
           },structure={
             loading_matrix<-loading_matrix_structure
           },all={
             loading_matrix<-rbind(loading_matrix_pattern,loading_matrix_structure,make.row.names=FALSE)
           })
  }
  # loading_matrix[,3:length(loading_matrix)]<-change_data_type(loading_matrix[,3:length(loading_matrix)],type="numeric")
  return(loading_matrix)
}

compute_residual_stats<-function(model,data=NULL) {
  if(!is.null(data))
    residuals<-model-data
  else
    residuals<-as.matrix(model$residual[upper.tri(model$residual)])
  large_residuals<-abs(residuals)>0.05
  n_large_residuals<-sum(large_residuals)
  propLargeResid<-n_large_residuals/nrow(residuals)
  rmsr<-sqrt(mean(residuals^2))
  result<-data.frame(residual_statistics=c("Root Mean Squared Residual",
                                           "Number of absolute residuals > 0.05",
                                           "Proportion of absolute residuals > 0.05"),
                     value=c(rmsr,n_large_residuals,propLargeResid),
                     critical=c(NA,NA,.5),
                     formula=c("sqrt(mean(residuals^2))",
                               "abs(residuals)>0.05",
                               "numberLargeResiduals/nrow(residuals)"))
  return(result)
}

report_efa<-function(model,df,file=NULL,w=10,h=5,cut=0,base_size=10,scores=FALSE) {
  comment<-list("p[bartlett]"=toString(c("Bartlett's test, tests for identity matrix",
                                         "\nAn identity matrix indicates no correlations among data",
                                         "\nSignificance indicates a non identity matrix")),
                determinant="Determinant should be > 0.00001. Lower values indicate problematic correlation matrices if subjected to calculations",
                complexity="Hoffman's index of complexity for each item. {(SUM a_i^2)^2}/{SUM a_i^4} where a_i is the factor loading on the ith factor. Hofmann (1978)",
                communality="communality estimates for each item. These are merely the sum of squared factor loadings for that item",
                uniquenesses="",
                values="eigen values of the common factor solution",
                e.values="eigen values of the original matrix",
                RMSEA="root mean square error of approximation",
                lower="lower bound for rmsea",
                upper="upper bound for rmsea",
                confidence="confidence level for rmsea",
                rms="root mean square error",
                crms="rms adjusted for degrees of freedom",
                tli="tucker lewis index",
                bic="",
                ebic="",
                esabic="",
                fit="",
                fit.off="")
  
  instruction_kaiser<-"Kaiser's criterion is accurate for fewer than 30 variables and communalities greater than .7 or when the sample size exceeds 250 and average communality is greater than .6\n The eigenvalues associated with each factor represent the variance explained by that particular linear component\n Histogram of residuals may show outliers or a bad model fit it may also indicate that we may have to remove items\n"
  instruction_loadings<-"The correlation coefficients between each variable and factor\n Pattern Loadings: Loadings before rotation\n Structure Loadings: Loadings after rotation"
  instruction_communalities<-"h2: Communality, Communality is the proportion of common variance within a variable"
  instruction_loading_critical_values<-data.frame(sample=c(50,60,70,85,100,120,150,200,250,350),
                                                  critical_loading=c(.75,.70,.65,.60,.55,.50,.45,.40,.35,.30))
  ##########################################################################################
  instruction_kmo<-data.frame(value=c("between .0 and .5","between .5 and .7","between .7 and .8","between .8 and .9","between .9 and  1"),
                              "Kaiser (1974)"=c("Unacceptable","Mediocre","Good","Great","Superb"),
                              Source="Hutcheson & Sofroniou (1999)",
                              check.names=FALSE)
  correlationmatrix<-stats::cor(df,use="pairwise.complete.obs")
  bartlett<-psych::cortest.bartlett(correlationmatrix,nrow(df))
  determinant_test<-data.frame(determinant=det(correlationmatrix),above_critical=det(correlationmatrix)>0.00001)
  kmo<-psych::KMO(df)
  kmo_test<-data.frame(Overall_MSA=kmo$MSA,MSA=kmo$MSAi)
  kmo_test$Kaiser_1974<-NA
  
  # if(nrow(kmo_test[kmo_test$MSA<=.5,])>0)
  #   kmo_test[kmo_test$MSA<.5,]$Kaiser_1974<-"Unacceptable"
  # if(nrow(kmo_test[kmo_test$MSA>.5&kmo_test$MSA<=.7,])>0)
  #   kmo_test[kmo_test$MSA>=.5&kmo_test$MSA<=.7,]$Kaiser_1974<-"Mediocre"
  # if(nrow(kmo_test[kmo_test$MSA>.7&kmo_test$MSA<=.8,])>0)
  #   kmo_test[kmo_test$MSA>.7&kmo_test$MSA<=.8,]$Kaiser_1974<-"Good"
  # if(nrow(kmo_test[kmo_test$MSA>.8&kmo_test$MSA<=.9,])>0)
  #   kmo_test[kmo_test$MSA>.8&kmo_test$MSA<=.9,]$Kaiser_1974<-"Great"
  # if(nrow(kmo_test[kmo_test$MSA>.9,])>0)
  #   kmo_test[kmo_test$MSA>.9,]$Kaiser_1974<-"Superb"
  bartlett_test<-data.frame("x_squared[bartlett]"=bartlett$chisq,"df[bartlett]"=bartlett$df,"p[bartlett]"=bartlett$p.value,check.names=FALSE)
  ##########################################################################################
  fit_index<-data.frame(t(model$RMSEA),
                        RMS=model$rms,
                        CRMS=model$crms,
                        TLI=model$TLI,
                        CFI=model$CFI,
                        BIC=model$BIC,
                        SABIC=model$SABIC,
                        EBIC=model$EBIC,
                        ESABIC=model$ESABIC,
                        fit=model$fit,
                        fit.off=model$fit.off)
  
  plot<-list()
  filename<-paste0(file,".xlsx")
  if(length(model$values)>0){
    #parallel<-psych::fa.parallel(df,n.obs=NULL,fm="minres",fa="both",main="Parallel Analysis Scree Plots",n.iter=20,error.bars=TRUE,se.bars=TRUE,SMC=FALSE,ylabel=NULL,show.legend=TRUE,sim=TRUE,quant=.95,cor="cor",use="pairwise")
    plot[["plot_scree"]]<-plot_scree(df,base_size=base_size,title="")
    plot[["plot_loadings_structure"]]<-plot_loadings(model,matrix_type="structure",base_size=base_size)
    plot[["plot_loadings_pattern"]]<-plot_loadings(model,matrix_type="pattern",base_size=base_size)
  }
  plot[["plot_residual_histogram"]]<-plot_histogram(data.frame(data=model$residual[upper.tri(model$residual)])$data,bins=30,title="Histogram of residuals",base_size=base_size)
  report_pdf(plotlist=plot,file=file,w=w,h=h,print_plot=TRUE)
  
  residual_stats<-compute_residual_stats(model)

  model_communality<-data.frame(complexity=model$complexity,
                                communality=model$communality,
                                communalities=model$communalities,
                                uniquenesses=model$uniquenesses,
                                values=model$values,
                                e.values=model$e.values)
  
  correlations<-rbind(data.frame(type="reproduced correlations",model$model),
                      data.frame(type="observed correlations",model$r),
                      data.frame(type="residual correlations",model$residual))
  loadings<-plyr::rbind.fill(model_loadings(model,cut,matrix_type="all"),
                             # data.frame(type="Phi",model$Phi),
                             data.frame(type="variance accounted",row.names(model$Vaccounted),model$Vaccounted))
  model_call<-data.frame(call=call_to_string(model))
  
  result<-list(correlations=correlations,npobs=model$np.obs,residual_stats=residual_stats,determinant_test=determinant_test,bartlett_test=bartlett_test,kmo_test=kmo_test)
  if(length(model$values)>0) {
    result[["loadings"]]<-loadings
    result[["instruction_loading_critical_values"]]<-instruction_loading_critical_values
    result[["weights"]]<-model$weights
  }
  if(scores) {
    result[["scores"]]<-model$scores
  }
  if(!is.null(file)) {
    if(file.exists(filename)) file.remove(filename)
    wb<-openxlsx::createWorkbook()
    excel_matrix(correlations,wb,sheet="r",conditional_formatting=TRUE,numFmt="#0.00")
    excel_matrix(model$np.obs,wb,sheet="n",conditional_formatting=TRUE,numFmt="#0.00")
    excel_matrix(residual_stats,wb,sheet="residual stats",conditional_formatting=FALSE)
    excel_critical_value(fit_index,wb,sheet="fit_index")
    
    if(length(model$values)>0) {
      excel_matrix(loadings,wb,sheet="loadings",conditional_formatting=TRUE,title="structure loadings: loadings after rotation, pattern loadings: loadings before rotation")
      excel_matrix(instruction_loading_critical_values,wb,sheet="loading critical values",conditional_formatting=TRUE)
      excel_matrix(model$weights,wb,sheet="weights",conditional_formatting=FALSE)
    }
    
    excel_critical_value(determinant_test,wb,sheet="determinant")
    excel_critical_value(bartlett_test,wb,sheet="bartlett test")
    excel_critical_value(kmo_test,wb,sheet="msa")
    
    excel_matrix(model_communality,wb,sheet="communalities",conditional_formatting=FALSE)
    if(scores)
      excel_matrix(model$scores,wb,sheet="scores",conditional_formatting=TRUE)
    excel_matrix(model_call,wb,sheet="call")
    openxlsx::saveWorkbook(wb,filename)
  }
  return(result)
}

report_hlr<-function(df,corlist,factorlist,predictor,random_effect,file=NULL,sheet="report") {
  fbaseline<-fpredictor<-frandom_intercept<-frandom_slope<-anova<-NULL
  anova_comparisons<-data.frame()
  # pb<-txtProgressBar(min=0,max=length(corlist),style=3)
  counter=0
  for (i in corlist) {
    temp<-df[,c(i,factorlist,which(predictor==(names(df))))]
    temp<-temp[complete.cases(temp),]
    counter=counter+1
    # setTxtProgressBar(pb,counter)
    dv<-names(df)[i]
    fbaseline<-formula(paste(dv,"~1"))
    fpredictor<-formula(paste(dv,"~",predictor))
    frandom_intercept<-formula(paste("~1|",random_effect))
    frandom_slope<-formula(paste("~",predictor,"|",random_effect))
    
    base<-nlme::gls(formula(fbaseline),method="ML",data=temp)
    random_intercept<-nlme::lme(fixed=formula(fbaseline),random=frandom_intercept,data=temp,method="ML")
    random_intercept_predictor<-nlme::lme(fixed=fpredictor,random=frandom_intercept,data=temp,method="ML")
    fixed<-c(deparse(fbaseline),deparse(fbaseline),deparse(fpredictor))
    random<-c(NA,deparse(frandom_intercept),deparse(frandom_intercept))
    anova_intercept_predictor<-aor<-data.frame(fixed=fixed,
                                               random=random,
                                               anova(base,random_intercept,random_intercept_predictor))
    res<-try(nlme::lme(fixed=fpredictor,random=frandom_slope,data=temp,method="ML"),silent = TRUE)
    if(!class(res)=="try-error") {
      random_intercept_slope<-nlme::lme(fixed=fpredictor,random=frandom_slope,data=temp,method="ML")
      anova_random_intercept_slope<-aor<-data.frame(fixed=c(fixed,deparse(fpredictor)),
                                                    random=c(random,deparse(frandom_slope)),
                                                    anova(base,random_intercept,random_intercept_predictor,random_intercept_slope))
    }
    anova_comparisons<-plyr::rbind.fill(anova_comparisons,data.frame(dv=dv,model=row.names(aor),aor))
  }
  # close(pb)
  report_dataframe(anova_comparisons,sheet=sheet,file=file,type="critical_value",critical=list(p.value="<0.05"))
  return(anova_comparisons)
}

plot_irt_onefactor<-function(model,theta=seq(-6,6,.1),title="",base_size=10) {
  value<-variable<-NULL
  model_names<-names(data.frame(model@Data$data))
  info_item<-data.frame(theta=theta,type="Item Information")
  for(i in model_names)
    info_item[,i]<-testinfo(x=model,Theta=theta,degrees= NULL,group=NULL,individual=FALSE,which.items=grep(i,model_names))
  expected_item<-data.frame(theta=theta,
                            type="Expected Score",
                            expected.test(x=model,Theta=matrix(theta),group=NULL,mins=TRUE,individual=TRUE,which.items=1:extract.mirt(model,"nitems")))
  names(info_item)<-names(expected_item)<-c("theta","type",model_names)
  
  df_total<-data.frame(theta=theta,
                       information=testinfo(x=model,Theta=theta,degrees= NULL,group=NULL,individual=FALSE,which.items=1:extract.mirt(model,"nitems")),
                       expected_score=expected.test(x=model,Theta=matrix(theta),group=NULL,mins=TRUE,individual=FALSE,which.items=NULL))
  
  df_total_melt<-data.frame(type="total",reshape2::melt(df_total,id.vars=c("theta")))
  info_item_melt<-reshape2::melt(info_item,id.vars=c("theta","type"))
  expected_item_melt<-reshape2::melt(expected_item,id.vars=c("theta","type"))
  
  df_result<-plyr::rbind.fill(df_total_melt,info_item_melt,expected_item_melt)

  total<-ggplot(df_result,aes(x=theta,y=value,group=variable,color=variable))+
    geom_line()+
    geom_point()+
    theme_bw(base_size=base_size)+
    theme(legend.position="bottom")+
    labs(title=paste("Total Score / Information",title),y="",x=expression(theta))+
    facet_wrap(type~.,scales="free")
  return(total)
}

report_irt<-function(model,m2=TRUE,file=NULL) {
  comment<-list(a1="discrimination",
                d="difficulty",
                g="guessing",
                u="inattentiveness",
                G2="PARSCALE's G^2",
                # p="",
                TLI="Tucker Lewis Index TLI>0.95",
                CFI="Comparative Fit Index CFI>0.95",
                RMSEA="Root Mean Square Error of Approximation RMSEA<0.07",
                df="degrees of freedom",
                AIC="Akaike Information Criterion",
                AICc="small-sample-size adjusted Akaike Information Criterion",
                BIC="Bayesian Information Criterion",
                SABIC="sample-size adjusted Bayesian Information Criterion",
                DIC="Deviance Information Criterion",
                # HQ="",
                # logLik="",
                # logPrior="",
                # SElogLik="",
                # F1="",
                # h2="",
                "SRMR(SRMSR)"="Standardized Root Mean Square Residual SRMR(SRMSR)<0.08")
  pt<-options(fit.indices=c("GFI","AGFI","RMSEA","NFI","NNFI","CFI","RNI","IFI","SRMR","AIC","AICc","BIC","CAIC"))
  model_coefficients<-data.frame(coef(model,CI=0.95,printSE=FALSE,verbose=FALSE,rotate="none",as.data.frame=FALSE,simplify=TRUE,unique=FALSE)$items)
  model_coefficients_oblimin<-data.frame(flatten_list(coef(model,CI=0.95,printSE=FALSE,verbose=FALSE,rotate="oblimin",as.data.frame=FALSE,simplify=TRUE,unique=FALSE)))
  row.names(model_coefficients_oblimin)[1:length(row.names(model_coefficients))]<-row.names(model_coefficients)
  q3_matrix<-residuals(model,digits=3,type="Q3",QMC=TRUE)
  q3_matrix<-data.frame(matrix_triangle(q3_matrix,off_diagonal=NA,diagonal=NA,type="lower"),check.names=FALSE)
  q3_matrix$min<-remove_nc(apply(q3_matrix,1,min,na.rm=TRUE),value=NA)
  q3_matrix$max<-remove_nc(apply(q3_matrix,1,max,na.rm=TRUE),value=NA)
  q3_matrix<-rbind(q3_matrix,
                   min=apply(q3_matrix,2,min,na.rm=TRUE),
                   max=apply(q3_matrix,2,max,na.rm=TRUE))
  m2_fit<-try(M2(model,type="M2*",calcNull=TRUE,na.rm=TRUE,quadpts=NULL,theta_lim=c(-6,6),CI=0.9,residmat=FALSE,QMC=TRUE),silent=TRUE)
  exp_residuals<-data.frame(residuals(model,digits=3,type="exp",QMC=TRUE),check.names=FALSE)
  item_fit=itemfit(model,na.rm=TRUE)
  g2_fit<-remove_nc(data.frame(model@Fit,check.names=FALSE))
  result<-list(model_coefficients=model_coefficients,
               model_coefficients_oblimin=model_coefficients_oblimin,
               model_options=data.frame(Options=unlist(model@Options),check.names=FALSE),
               model_call=call_to_string(model@Call),
               q3_matrix=q3_matrix,
               exp_residuals=exp_residuals,
               item_fit=item_fit,
               g2_fit=g2_fit,
               m2_fit=m2_fit)
  if(!is.null(file)) {
    filename<-paste0(file,".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb<-openxlsx::createWorkbook()
    excel_critical_value(result$model_coefficients,wb,"Coefficients",numFmt="#0.00",comment=comment)
    excel_critical_value(result$model_coefficients_oblimin,wb,"Coefficients Oblimin",numFmt="#0.00",comment=comment)
    excel_critical_value(result$item_fit,wb,"item fit",numFmt="#0.00",comment=comment)
    excel_critical_value(result$g2_fit,wb,"G2",numFmt="#0.00",comment=comment)
    if(is.data.frame(result$m2_fit))
      excel_critical_value(result$m2_fit,wb,"M2",numFmt="#0.00",title="M2 (Maydeu-Olivares & Joe, 2006) statistic\n when all data are dichotomous",comment=comment)
    excel_matrix(result$q3_matrix,wb,"Q3",title="Test for local independence:\nThere is no concensus about the critical values.\nCritical values may range from absolute of .7 to .1",numFmt="#0.00",conditional_formatting=TRUE)
    excel_critical_value(result$exp_residuals,wb,"Residuals",numFmt="#0.00")
    excel_critical_value(result$model_options,wb,"Model Options",numFmt="#0.00")
    openxlsx::saveWorkbook(wb,filename,overwrite=TRUE)
  }
  return(result)
}

generate_matrix_A<-function(blocks=3,items=3) {
  comparison<-generate_comparisons_matrix(items)
  row_length<-nrow(comparison)
  alpha<-matrix(nrow=row_length*blocks,ncol=items*blocks)
  alpha[is.na(alpha)]<-0
  col_index<-increase_index(blocks=blocks,items=items)
  row_index<-increase_index(blocks=blocks,items=row_length)
  for(i in 1:blocks)
    alpha[row_index[i,],col_index[i,]]<-comparison
  return(alpha)
}

compute_dummy_comparisons<-function(items) {
  comparisons<-items*(items-1)/2
  return(comparisons)
}

generate_unique_comparisons_index<-function(items) {
  result<-data.frame()
  for (i1 in 1:items){
    for (i2 in 1:items)
      result<-plyr::rbind.fill(result,data.frame(i1=i1,i2=i2))
  }
  result<-result[apply(result,1,function(x) length(unique(x[!is.na(x)]))!=1),]
  result<-result[result$i1<result$i2,]
  return(as.matrix(result))
}

increase_index<-function(blocks,items){
  start<-1
  stop<-items
  index<-matrix(seq(start,stop,1),ncol=items)
  for(i in 2:blocks){
    start<-start+items
    stop<-stop+items
    index<-rbind(index,seq(start,stop,1))
  }
  return(index)
}

generate_comparisons_matrix<-function(items) {
  comparisons<-generate_unique_comparisons_index(items)
  result<-matrix(nrow=nrow(comparisons),ncol=items)
  result[is.na(result)]<-0
  for (i in 1:nrow(comparisons)){
    result[i,comparisons[i,1]]<-1
    result[i,comparisons[i,2]]<--1
  }
  return(result)
}

generate_matrix_lambda_hat<-function(blocks=3,items=3) {
  lambda<-matrix(nrow=0,ncol=items)
  for (i in 1:blocks)
    lambda<-rbind(lambda,generate_comparisons_matrix(items))
  return(lambda)
}

rank_to_binary<-function(mydata,items,reverse=TRUE) {
  if(missing(items))
    items<-length(mydata)
  index<-generate_unique_comparisons_index(items)
  binary<-index_name<-list()
    for(i in 1:nrow(index)) {
      index_name[[i]]<-paste0("i",index[i,1],index[i,2])
      binary[[index_name[[i]]]]<-rep(0,nrow(mydata))
      binary[[index_name[[i]]]][which(mydata[,index[i,1]]>mydata[,index[i,2]])]<-1
    }
  binary<-matrix(unlist(binary),nrow=length(binary[[1]]),dimnames=list(NULL,names(binary)))
  if(!reverse)
    binary<-+(!binary)
  return(binary)
}

rank_df_to_binary<-function(mydata,items,reverse=TRUE) {
  binary<-data.frame(index=1:nrow(mydata))
  blocks<-length(mydata)/items
  index<-increase_index(blocks=blocks,items=items)
  for (i in 1:blocks)
    binary<-data.frame(binary,rank_to_binary(mydata[,index[i,]],items,reverse))
  binary$index<-NULL
  return(binary)
}

name_triplet_pairs<-function(n,prefix="i",sep="",strict=TRUE) {
  if (length(n)==1L) {
    if (n %% 3 != 0) {
      if (strict) stop("n must be a multiple of 3") else n<-n-(n %% 3)
    }
    items<-seq_len(n)
  } else {
    # if a vector of indices is passed (e.g.,c(4:18)),use it directly
    items<-n
    if (length(items) %% 3 != 0) {
      if (strict) stop("length(items) must be a multiple of 3") 
      else items<-items[seq_len(length(items)-(length(items) %% 3))]
    }
  }
  # split into triplets and make pair labels
  triplets<-split(items,ceiling(seq_along(items) / 3))
  out<-unlist(lapply(triplets,function(g) {
    if (length(g)<3) return(character(0))
    # columns are c(1,2),c(1,3),c(2,3)
    pairs<-combn(g,2)
    paste0(prefix,pairs[1,],sep,prefix,pairs[2,])
  }),use.names=FALSE)
  out
}

rank3_to_triplets<-function(mydata) {
  item1<-item2<-item3<-rep(NA,nrow(mydata))
  result<-data.frame(item1,item2,item3)
  result[mydata[,1]==1&mydata[,2]==1,]$item1<-3
  result[mydata[,1]==1&mydata[,2]==0,]$item1<-2
  result[mydata[,1]==0&mydata[,2]==1,]$item1<-2
  result[mydata[,1]==0&mydata[,2]==0,]$item1<-1
  result[mydata[,1]==0&mydata[,3]==1,]$item2<-3
  result[mydata[,1]==0&mydata[,3]==0,]$item2<-2
  result[mydata[,1]==1&mydata[,3]==1,]$item2<-2
  result[mydata[,1]==1&mydata[,3]==0,]$item2<-1
  result[mydata[,2]==0&mydata[,3]==0,]$item3<-3
  result[mydata[,2]==1&mydata[,3]==0,]$item3<-2
  result[mydata[,2]==0&mydata[,3]==1,]$item3<-2
  result[mydata[,2]==1&mydata[,3]==1,]$item3<-1
  return(result)
}

response_dimension<-function(response,dimensions,items) {
  response_vector<-c()
  for (i in 1:(length(response)/dimensions)) {
    response_vector<-c(response_vector,response[items])
    response<-response[dimensions+1:length(response)]
  }
  return(response_vector)
}

cfa_icc_index<-function(nitems,nfactors=3) {
  index<-nitems/nfactors
  start_index<-list(1)
  for (i in 2:nfactors)
    start_index[[i]]<-index*(i-1)+1
  for(i in 1:length(start_index))
    start_index[[i]]<-start_index[[i]]:(start_index[[i]]+index-1)
  comparison_matrix<-matrix(unlist(start_index),ncol=nfactors,byrow=FALSE)
  index<-c()
  for(i in 1:nrow(comparison_matrix))
    index<-c(index,as.numeric(comparison_matrix[i,]))
  result<-list(index_vector=index,index_matrix=comparison_matrix)
  return(result)
}

icc_cfa<-function(eta,gamma,lambda,psi) {
  result<-pnorm((-gamma+lambda*eta)/(sqrt(psi)))
  return(result)
}

plot_icc_thurstonian<-function(mydata,title="Item Characteristic Curve") {
  value<-eta<-variable<-NULL
  mydata<-reshape2::melt(mydata,id.vars="eta")
  plot<-ggplot(mydata,aes(y=value,x=eta,group=variable,color=variable))+geom_point(alpha=.1)+geom_line()+theme_bw()+
    labs(y=expression(P(eta)),x=expression(eta),title=title)
  return(plot)
}

compute_icc_thurstonian<-function(eta,gamma,lambda,psi,plot=FALSE) {
  result<-data.frame(eta)
  for(i in 1:length(lambda)) {
    item<-icc_cfa(eta,gamma[i],lambda[i],psi[i])
    result<-data.frame(result,item)
  }
  result<-result[,c(grep("item",names(result),value=TRUE),"eta")]
  names(result)[1:length(lambda)]<-paste0("item",1:length(lambda))
  if(plot)
    plot<-plot_icc_thurstonian(result,title="Item Characteristic Curve")
  return(list(icc=result,plot=plot))
}

compute_ability<-function(response,eta,gamma,lambda,psi,plot=FALSE,map=compute_map(eta=eta,mean=0,sd=1)) {
  result<-compute_icc_thurstonian(eta,gamma,lambda,psi,plot=plot)
  product=1
  for(i in 1:length(response)) {
    product<-product*(result$icc[,i]^response[i])*((1-result$icc[,i])^(1-response[i]))
  }
  product_map=product*map
  ability_ml<-result$icc$eta[which(product==max(product))]
  ability_map<-result$icc$eta[which(product_map==max(product_map))]
  if(plot) {
    repeat {
      if(max(product)<.1)
        product<-product*10
      if(max(product)>=.1)
        break()
    }
    repeat {
      if(max(product_map)<.1)
        product_map<-product_map*10
      if(max(product_map)>=.1)
        break()
    }
    icc_df<-data.frame(product=product,map=product_map,result$icc)
    print(plot_icc_thurstonian(icc_df,title=paste(title="Item Characteristic Curve",
                                                  "ML:",round(ability_ml,2),
                                                  "MAP:",round(ability_map,2),
                                                  "\nResponse:",sum(response),
                                                  "Response Length:",length(response))))
  } else {
    icc_df<-data.frame(product=product,map=product_map,result$icc)
  }
  return(list(product=product,icc=icc_df,ability_ml=ability_ml,ability_map=ability_map))
}

compute_map<-function(eta,mean=0,sd=1) {
  prior_density=stats::dnorm(eta,mean=mean,sd=sd)
  map<-prior_density/sum(prior_density)    # after division sum(AXr)=1
  return(map)
}

extract_tirt_params<-function(fit_lavaan_obj) {
  est<-lavaan::lavInspect(fit_lavaan_obj$fit, "est")
  lambda<-est$lambda
  ind<-rownames(lambda)
  
  # residual variances -- align to lambda by indicator name
  theta_diag<-diag(est$theta)
  if(!is.null(names(theta_diag))) {
    theta_diag<-theta_diag[ind]
  }
  
  # thresholds -- tau rownames look like "i12b1|t1"; strip "|t..." and align
  tau_mat<-est$tau
  tau_names<-sub("\\|.*$", "", rownames(tau_mat))
  tau_vec<-as.numeric(tau_mat)
  names(tau_vec)<-tau_names
  tau_vec<-tau_vec[ind]
  
  # intercepts -- usually fixed at 0 for binary indicators, but check anyway
  nu_vec<-rep(0, length(ind))
  names(nu_vec)<-ind
  if (!is.null(est$nu)) {
    nu_named<-as.numeric(est$nu)
    names(nu_named)<-rownames(est$nu)
    if (all(ind %in% names(nu_named))) {
      nu_vec<-nu_named[ind]
    }
  }
  list(lambda=lambda,theta_diag=theta_diag,tau=tau_vec,nu=nu_vec,Psi=est$psi)
}

score_tirt_pattern<-function(pattern,lambda,theta_diag,tau,Psi,nu=NULL,init=NULL,control=list()) {
  n_traits<-ncol(lambda)
  if (is.null(nu)) 
    nu<-rep(0,nrow(lambda))
  obs<-!is.na(pattern)
  L<-lambda[obs, , drop=FALSE]
  y<-as.numeric(pattern[obs])
  s<-sqrt(theta_diag[obs])
  th<-tau[obs]-nu[obs]
  # iPsi<-solve(Psi)
  iPsi<-compute_solve(Psi)
  nll<-function(eta) {
    z <-(as.numeric(L %*% eta) - th) / s
    p <-pmin(pmax(pnorm(z), 1e-15), 1 - 1e-15)
    ll<-sum(y * log(p) + (1 - y) * log1p(-p))
    lp<--0.5 * sum(eta * (iPsi %*% eta))
    -(ll + lp)
  }
  gnll<-function(eta) {
    z<-(as.numeric(L %*% eta) - th) / s
    p<-pmin(pmax(pnorm(z), 1e-15), 1 - 1e-15)
    phi<-stats::dnorm(z)
    w<-(y - p) * phi / (p * (1 - p)) / s
    -(as.numeric(crossprod(L, w)) - as.numeric(iPsi %*% eta))
  }
  
  if (is.null(init)) init<-rep(0, n_traits)
  ctrl<-utils::modifyList(list(reltol=1e-10, maxit=500), control)
  
  res<-stats::optim(init,nll,gr=gnll,hessian=TRUE,method="BFGS",control=ctrl)
  setNames(res$par, colnames(lambda))
}

compute_solve <- function(a, b) {
  a <- as.matrix(a)
  n <- nrow(a)
  if (ncol(a) != n) stop("'a' must be square")
  
  if (missing(b)) b <- diag(n)        # default: invert a
  b <- as.matrix(b)
  if (nrow(b) != n) stop("'a' and 'b' have incompatible dimensions")
  
  # Build augmented matrix [a | b]
  M <- cbind(a, b)
  
  # Gauss-Jordan elimination with partial pivoting
  for (i in seq_len(n)) {
    # Find pivot row (largest absolute value in column i, from row i down)
    pivot <- which.max(abs(M[i:n, i])) + i - 1
    if (M[pivot, i] == 0) stop("matrix is singular")
    
    # Swap rows if needed
    if (pivot != i) M[c(i, pivot), ] <- M[c(pivot, i), ]
    
    # Normalize pivot row
    M[i, ] <- M[i, ] / M[i, i]
    
    # Eliminate column i in all other rows
    for (j in seq_len(n)) {
      if (j != i) M[j, ] <- M[j, ] - M[j, i] * M[i, ]
    }
  }
  
  # Right half is the solution
  x <- M[, (n + 1):ncol(M)]
  if (ncol(b) == 1) x <- as.vector(x)
  x
}

score_tirt<-function(patterns, lambda, theta_diag, tau, Psi, nu=NULL) {
  patterns<-as.matrix(patterns)
  
  # align columns to lambda rows by name -- the critical step
  if (is.null(rownames(lambda)) || is.null(colnames(patterns))) {
    warning("lambda rows or pattern columns are unnamed; assuming positional alignment.")
  } else {
    miss<-setdiff(rownames(lambda), colnames(patterns))
    if (length(miss) > 0) {
      stop("Pair names in lambda not found in patterns:\n  ",
           paste(miss, collapse=", "))
    }
    patterns<-patterns[, rownames(lambda), drop=FALSE]
  }
  
  scores<-t(apply(patterns,1,score_tirt_pattern,
                  lambda=lambda,
                  theta_diag=theta_diag,
                  tau=tau,
                  Psi=Psi,
                  nu=nu))
  colnames(scores)<-colnames(lambda)
  scores
}

check_heywood<-function(fit_model,verbose=TRUE) {
  # Initialize results
  issues<-list()
  has_issues<-FALSE
  
  # Get parameter estimates
  params<-lavaan::parameterEstimates(fit_model)
  std<-lavaan::standardizedSolution(fit_model)
  
  # 1. Check for negative variances (standard lavaan)
  neg_var<-params[params$op == "~~" & params$lhs == params$rhs & params$est < 0,]
  if (nrow(neg_var) > 0) {
    issues$negative_variances<-neg_var
    has_issues<-TRUE
    if (verbose) {
      cat("\n=== NEGATIVE VARIANCES (~~) ===\n")
      print(neg_var[,c("lhs","op","rhs","est","se","pvalue")])
    }
  }
  
  # 2. Check for negative residual variances (Thurstonian ~*~)
  neg_resid<-params[params$op == "~*~" & params$est < 0,]
  if (nrow(neg_resid) > 0) {
    issues$negative_residuals<-neg_resid
    has_issues<-TRUE
    if (verbose) {
      cat("\n=== NEGATIVE RESIDUAL VARIANCES (~*~) ===\n")
      print(neg_resid[,c("lhs","op","rhs","est","se","pvalue")])
    }
  }
  
  # 3. Check for standardized loadings > 1 or < -1
  problem_loadings<-std[std$op == "=~" & abs(std$est.std) > 1,]
  if (nrow(problem_loadings) > 0) {
    issues$extreme_loadings<-problem_loadings
    has_issues<-TRUE
    if (verbose) {
      cat("\n=== STANDARDIZED LOADINGS > 1 ===\n")
      print(problem_loadings[,c("lhs","op","rhs","est.std","pvalue")])
    }
  }
  
  # 4. Check for correlations outside [-1,1]
  extreme_cors<-std[std$op == "~~" & std$lhs != std$rhs & abs(std$est.std) > 1,]
  if (nrow(extreme_cors) > 0) {
    issues$extreme_correlations<-extreme_cors
    has_issues<-TRUE
    if (verbose) {
      cat("\n=== CORRELATIONS OUTSIDE [-1,1] ===\n")
      print(extreme_cors[,c("lhs","op","rhs","est.std","pvalue")])
    }
  }
  
  # 5. Check for extreme standard errors (might indicate identification issues)
  extreme_se<-params[!is.na(params$se) & params$se > 10,]
  if (nrow(extreme_se) > 0) {
    issues$extreme_se<-extreme_se
    has_issues<-TRUE
    if (verbose) {
      cat("\n=== EXTREME STANDARD ERRORS (> 10) ===\n")
      print(extreme_se[,c("lhs","op","rhs","est","se","pvalue")])
    }
  }
  
  # 6. Check convergence
  converged<-lavaan::lavInspect(fit_model,"converged")
  if (!converged) {
    issues$convergence<-"Model did not converge"
    has_issues<-TRUE
    if (verbose) {
      cat("\n=== CONVERGENCE ISSUE ===\n")
      cat("Model did not converge properly!\n")
    }
  }
  
  # Summary
  if (verbose) {
    cat("\n=== SUMMARY ===\n")
    if (has_issues) {
      cat("⚠️  Issues found:\n")
      if (!is.null(issues$negative_variances)) 
        cat(sprintf(" -%d negative variance(s) (~~)\n",nrow(issues$negative_variances)))
      if (!is.null(issues$negative_residuals)) 
        cat(sprintf(" -%d negative residual variance(s) (~*~)\n",nrow(issues$negative_residuals)))
      if (!is.null(issues$extreme_loadings)) 
        cat(sprintf(" -%d extreme standardized loading(s)\n",nrow(issues$extreme_loadings)))
      if (!is.null(issues$extreme_correlations)) 
        cat(sprintf(" -%d extreme correlation(s)\n",nrow(issues$extreme_correlations)))
      if (!is.null(issues$extreme_se)) 
        cat(sprintf(" -%d extreme standard error(s)\n",nrow(issues$extreme_se)))
      if (!is.null(issues$convergence)) 
        cat(" -Convergence issue\n")
    } else {
      cat("✓ No Heywood cases or major issues detected!\n")
    }
  }
  
  # Return issues list invisibly
  invisible(list(
    has_issues=has_issues,
    issues=issues,
    converged=converged
  ))
}

compute_unidimensional_theta<-function(a,b=0,g=0,i=1,d=1.702,theta=0) {
  e<-exp(-a*d*(theta-b))
  denom<-1+e
  renum<-1-g
  denom[denom==0]<-1e-22
  result<-g+renum/denom
  return(result)
}

compute_unidimensional_ability<-function(a,b,g=NULL,d=1.702,u,lim_theta=c(-6,6)) {
  temp_theta<-0
  computations<-data.frame()
  first_derivative<-function(a,g,d,u,p) {
    result<-(d*a*(u-p)*(p-g))/(p*(1-g))
    return(result)
  }
  second_derivative<-function(a,g,d,u,p) {
    result<-((d*a)/(1-g))^2*((p-g)*(1-p)*(u*g-p^2))/(p*p)
    return(result)
  }
  if(is.null(g))
    g<-rep(0,length(u))
  counter<-1
  repeat {
    counter<-counter+1
    sum_num<-sum_den<-0
    for (i in 1:length(u)) {
      itemtheta<-compute_unidimensional_theta(a=a[i],b=b[i],g=g[i],d=d,theta=temp_theta)
      deriv1<-first_derivative(a=a[i],g=g[i],d=d,u=u[i],itemtheta)
      deriv2<-second_derivative(a=a[i],g=g[i],d=d,u=u[i],itemtheta)
      sum_num<-sum_num+deriv1 # calculate delta for newton-raphson estimation for current item
      sum_den<-sum_den+deriv2 # calculate delta for newton-raphson estimation for current item
      # computations<-plyr::rbind.fill(computations,data.frame(itemtheta=itemtheta,
      #                            temp_theta=temp_theta,
      #                            deriv1=deriv1,
      #                            deriv2=deriv2,
      #                            sum_num=sum_num,
      #                            sum_den=sum_den,
      #                            a=a[i],g=g[i],d=d,u=u[i]))
    }
    delta<-sum_num/sum_den # newton-raphson correction
    difference<-temp_theta-delta
    if(is.nan(abs(difference-temp_theta)))
      break
    if(abs(temp_theta-difference)<0.0001)
      break
    if(counter>10)
      break
    temp_theta<-temp_theta-delta
  }
  if(temp_theta>lim_theta[2])
    temp_theta<-lim_theta[2]
  if(temp_theta<lim_theta[1])
    temp_theta<-lim_theta[1]
  return(temp_theta)
}

compute_info_1pl<-function(b,theta) {
  p_theta<-1/(1+exp(-(theta-b)))
  q<-1-p_theta
  info<-p_theta*q
  return(info)
}

compute_info_2pl<-function(a,b,theta) {
  p_theta<-1/(1+exp(-a*(theta-b)))
  q<-1-p_theta
  info<-(a^2)*p_theta*q
  return(info)
}

compute_info_3pl<-function(a,b,g,theta) {
  p_theta<-g+(1-g)*(1/(1+exp(-a*(theta-b))))
  q<-1-p_theta
  info<-a^2*q/p_theta*(p_theta-g)^2/(1-g)^2
  return(info)
}

compute_se_theta<-function(info){
  result<-1/(sqrt(info))
  return(result)
}

report_lda<-function(model,file=NULL,w=10,h=10,base_size=10,title="") {
  prior_counts<-data.frame(prior=model$prior,counts=model$counts,mean=model$means)
  terms<-model$terms
  scaling<-model$scaling
  model_description<-data.frame(Observations=model$N,SDV=model$svd)
  call<-data.frame(call=stringr::str_replace_all(toString(deparse(model$call)),stringr::fixed(" "),""))
  predicted<-predict(model)
  observed<-stats::get_all_vars(model$call,model.frame(model))[,1]
  cmatrix<-confusion_matrix_percent(observed=observed,predicted=predicted$class)
  result<-list(prior_counts=prior_counts,means=model$means,coeficients=scaling,terms=terms,model_description=model_description,cmatrix=cmatrix,call=call)
  if(!is.null(file)) {
    filename<-paste0(file,".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb<-openxlsx::createWorkbook()
    excel_critical_value(result$coeficients,workbook=wb,sheet="Coefficients",numFmt="#0.00")
    excel_confusion_matrix(cmatrix,wb)
    excel_critical_value(result$prior_counts,workbook=wb,sheet="Priors and Counts",numFmt="#0.00")
    excel_critical_value(result$means,workbook=wb,sheet="Means",numFmt="#0.00")
    excel_critical_value(result$model_description,workbook=wb,sheet="Descriptives",numFmt="#0.00")
    excel_critical_value(result$call,workbook=wb,sheet="Call",numFmt="#0.00")
    openxlsx::saveWorkbook(wb,invisible(paste0(filename)),TRUE)
  }
  return(result)
}

plot_scatterplot <- function(df, method = lm, formula = y ~ x, base_size = 10, coord_equal = FALSE, all_orders = FALSE, title = "", combinations = NULL, str_aes = TRUE) {
  output_plot <- function(i) {
    tempdata <- data.frame(df[, combinations[i, 1]], df[, combinations[i, 2]])
    names(tempdata) <- c(combinations[i, 1], combinations[i, 2])
    tempdata <- tempdata[complete.cases(tempdata), ]
    if (nrow(tempdata) >= 2) {
      if (str_aes) {
        names(tempdata) <- str_aes(names(tempdata))
      }
      pearsonr <- stats::cor(tempdata[, 1], tempdata[, 2], use = "pairwise")
      model <- lm(tempdata[, 2] ~ tempdata[, 1])
      model_coef <- coef(model)
      slope <- model_coef[[2]]
      degrees <- rad2deg(atan(slope))
      if (degrees > 180) {
        degrees <- 360 - degrees
      }
      if (as.character(toString(formula)) == "~, y, x") {
        note <- paste0(
          "Pairwise n = ", nrow(tempdata[complete.cases(tempdata), ]),
          "\nPearson r = ", round(pearsonr, 4),
          "\nExplained Variance = ", round(pearsonr^2, 4) * 100, "%",
          "\ny = ", round(model_coef[[2]], 4),
          "x + ", round(model_coef[[1]], 4),
          "\nAngle = ", round(degrees, 2)
        )
      } else {
        note <- paste0("Pairwise n = ", nrow(tempdata[complete.cases(tempdata), ]))
      }
      scatter <- ggplot(tempdata, aes(x = tempdata[, 1], y = tempdata[, 2])) +
        geom_count(alpha = .1) +
        geom_smooth(method = method, se = TRUE, na.rm = TRUE, formula = formula) +
        labs(x = names(tempdata)[1], y = names(tempdata)[2], title = title, caption = note) +
        geom_rug(size = 0.1, alpha = .1) +
        theme_bw(base_size = base_size) +
        theme(
          legend.position = "left",
          legend.justification = c(0, 1),
          legend.margin = margin(t = -10, r = 0, b = 0, l = 0, unit = "pt")
        )
      if (min(tempdata[, 1], na.rm = TRUE) <= 0 & max(tempdata[, 1], na.rm = TRUE) >= 0) {
        scatter <- scatter + geom_vline(xintercept = 0, alpha = .5, color = "gray25")
      }
      if (min(tempdata[, 1], na.rm = TRUE) <= 0 & max(tempdata[, 1], na.rm = TRUE) >= 0) {
        scatter <- scatter + geom_hline(yintercept = 0, alpha = .5, color = "gray25")
      }
      if (coord_equal) {
        maximum_xy <- max(c(tempdata[, 1], tempdata[, 2]))
        minimum_xy <- min(c(tempdata[, 1], tempdata[, 2]))
        scatter <- scatter + coord_equal() +
          scale_x_continuous(limits = c(minimum_xy, maximum_xy)) +
          scale_y_continuous(limits = c(minimum_xy, maximum_xy))
      }
      ggpubr::as_ggplot(ggExtra::ggMarginal(scatter, type = "histogram", fill = "gray25", color = "gray50"))
    }
  }

  if (is.null(combinations)) {
    combinations <- comparison_combinations(df, all_orders = all_orders)
    names(combinations) <- c("x", "y")
  }
  combinations <- change_data_type(combinations, type = "character")
  combinations <- combinations[!combinations[, 1] == combinations[, 2], ]
  row.names(combinations) <- paste0(combinations[, 1], "_", combinations[, 2])

  n_rows <- nrow(combinations)
  n_cores <- parallel::detectCores()
  use_parallel <- n_cores * 4 < n_rows

  if (use_parallel) {
    message("Parallel processing with ", n_cores, " workers for ", n_rows, " plots")
    future::plan(future::multisession, workers = n_cores)
    scatterplots <- setNames(
      future.apply::future_lapply(seq_len(n_rows), function(i) {
        pdf(NULL)
        output_plot(i)
      }, future.seed = TRUE),
      row.names(combinations)
    )
    future::plan(future::sequential)
    gc(full = TRUE)
  } else {
    scatterplots <- setNames(
      lapply(seq_len(n_rows), output_plot),
      row.names(combinations)
    )
  }
  return(scatterplots)
}

report_regression <- function(model, base_size = 10, title = "", file = NULL, w = 10, h = 10, plot_diagnostics = TRUE) {
  anova <- NULL
  instruction_coefficients <- c(
    "Unstandardized coefficients (b's) indicate the change in the outcome resulting from a unit change in the predictor",
    "Standardized coefficients (for more than one predictors), indicate the change in outcome as a result of a unit change by a standard deviation of the predictor",
    "t-test checks if coefficients are significantly different from 0. Coefficients of 0 indicate no predictor effects",
    "Significance value for t-test"
  )
  instruction_anova <- c(
    "ANOVA tests for differences between the baseline model (model with no coefficient) and the predictive model (model with coefficient). A significant F shows that the predictor(s) significantly changes model predictability",
    "Significance value for ANOVA",
    "Null hypothesis: no variance explained by the predictor"
  )
  instruction_durbin <- c(
    "Test the assumption of independent errors.\nTest values may vary between 0 and 4.\nValues above 3 and bellow 1 are problematic.\nValues of 2 are ideal indicating uncorrelated residuals.
                        \nA value greater than 2 indicates a negative correlation between adjacent residuals.\nA value less than 2 indicates a positive correlation between adjacent residuals.",
    "Autocorrelation",
    "Durbin-Watson Statistic",
    "Significance value for Durbin-Watson Statistic"
  )
  instruction_vif <- c(
    "Variance Inflation Factor VIF indicates whether a predictor has strong linear relationship with other predictors. If the largest VIF is greater than 10 it is problematic Myers(1990).",
    "Tolerance=1/VIF Tolerance bellow .1 indicates serious problem. Tolerance bellow .2 indicates potential problem Field & Myers(2012).",
    "Mean VIF if average VIF is greater than 1 the regression may be biased."
  )
  if (plot_diagnostics) {
    plot <- autoplot(model, which = 1:6, ncol = 2) +
      labs(
        title = title,
        caption = paste0(deparse(model$terms), "\nobservations=", nrow(model$model))
      ) +
      theme_bw(base_size = base_size) +
      theme(axis.text.x = element_text(angle = 20, hjust = 1))
    report_pdf(plot, file = file, title = title, w = w, h = h, print_plot = TRUE)
  }

  outlier_test <- car::outlierTest(model)
  dw <- car::durbinWatsonTest(model)
  vif <- data.frame()
  try(
    {
      vif_result <- car::vif(model, type = "predictor")
      vif <- data.frame(
        vif = vif_result,
        tolerance = 1 / vif_result,
        mean_vif = mean(vif_result),
        check.names = FALSE
      )
    },
    silent = TRUE
  )
  diagnostics <- data.frame(
    simple_residuals = stats::resid(model),
    standard_residuals = stats::rstandard(model),
    student_residuals = stats::rstudent(model),
    fitted = stats::fitted(model),
    cooks_distance = stats::cooks.distance(model),
    dffits = stats::dffits(model),
    hatvalues = stats::hatvalues(model),
    covariance_ratio = data.frame(covariance_ratio = stats::covratio(model)),
    dfbeta = stats::dfbeta(model),
    effects = model$effects,
    check.names = FALSE
  )
  model_coefficients <- Reduce(
    function(x, y) merge(x, y, all = TRUE, sort = FALSE, by = "row.names"),
    list(
      data.frame(standardized = QuantPsyc::lm.beta(model), check.names = FALSE),
      data.frame(summary(model)[[4]], stats::confint(model), check.names = FALSE)
    )
  )
  result <- list(
    r = data.frame(r_squared = summary(model)$r.squared, adjusted_r_squared = summary(model)$adj.r.squared),
    coeficients = model_coefficients,
    anova = anova(model),
    deviance = data.frame(deviance = stats::deviance(model)),
    variance_covariance = data.frame(stats::vcov(model), check.names = FALSE),
    outlier_test = data.frame(
      rstudent = outlier_test$rstudent,
      p = outlier_test$p,
      bonf.p = outlier_test$bonf.p,
      signif = outlier_test$signif,
      cutoff = outlier_test$cutoff
    ),
    durbin_watson = data.frame(
      dw$r,
      dw$dw,
      dw$p,
      dw$alternative
    ),
    vif = vif,
    call = data.frame(call = paste0("lm(", deparse(eval(model$call$formula)), ",data=", model$call$data, ")")),
    diagnostics = diagnostics
  )

  write_txt(
    {
      output_separator("Summary", output = summary(model))
      output_separator("Coefficients", output = result$coeficients, instruction = instruction_coefficients)
      output_separator("ANOVA", output = result$anova, instruction = instruction_anova)
      output_separator("Deviance", output = result$deviance)
      output_separator("Outliers", output = result$outlier_test)
      output_separator("Durbin Watson", output = result$durbin_watson, instruction = instruction_durbin)
      if (nrow(vif) > 0) {
        output_separator("MULTICOLINEARITY", output = result$vif, instruction = instruction_vif)
      }
      output_separator("CALL", output = result$call)
    },
    file = file
  )
  if (!is.null(file)) {
    filename <- paste0(file, ".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb <- openxlsx::createWorkbook()
    excel_critical_value(result$r, workbook = wb, sheet = "r")
    excel_critical_value(result$coeficients,
      workbook = wb, sheet = "Coefficients", title = NULL,
      comment = list(
        Estimate = instruction_coefficients[1],
        standardized = instruction_coefficients[2],
        "t value" = instruction_coefficients[3],
        "Pr(>|t|)" = instruction_coefficients[4],
        "Std. Error" = "Standard Error of Estimates",
        "2.5 %" = "Confidence Intervals",
        "97.5 %" = "Confidence Intervals"
      ),
      critical = list("Pr(>|t|)" = "<0.05"),
      numFmt = "#0.00"
    )
    excel_critical_value(result$anova,
      workbook = wb, sheet = "ANOVA",
      title = instruction_anova[3],
      comment = list(
        "F value" = instruction_anova[1],
        "Pr(>F)" = instruction_anova[2]
      ),
      critical = list("Pr(>F)" = "<0.05"),
      numFmt = "#0.00"
    )
    # excel_critical_value(deviance,workbook=wb,sheet="Deviance",title="fit index",numFmt="#0.00")
    excel_critical_value(result$variance_covariance, workbook = wb, sheet = "Variance Covariance", numFmt = "#0.00")
    excel_critical_value(result$outlier_test, workbook = wb, sheet = "Outliers", numFmt = "#0.00")
    excel_critical_value(result$durbin_watson,
      workbook = wb, sheet = "Durbin Watson", title = toString(instruction_durbin[1]),
      comment = list(
        r = instruction_durbin[2],
        dw = instruction_durbin[3],
        p = instruction_durbin[4]
      ),
      numFmt = "#0.00"
    )
    if (nrow(vif) > 0) {
      excel_critical_value(result$vif,
        workbook = wb, sheet = "VIF", title = toString(instruction_vif),
        comment = list(
          vif = instruction_vif[1],
          tolerance = instruction_vif[2],
          mean_vif = instruction_vif[3]
        ),
        numFmt = "#0.00"
      )
    }
    excel_critical_value(result$diagnostics,
      workbook = wb, sheet = "Diagnostics",
      comment = list(
        standard_residuals = "Problematic values for standardized residuals > +-1.96",
        student_residuals = "Studentized residuals indicate the the ability of the model to predict that case. They follow a t distribution",
        cooks_distance = "Cook's distance indicates leverage. Problematic values for cook's distance > 1 Cook and Weisberg (1982).",
        hatvalues = "Hat values indicate leverage. Problematic values are 2 or 3 times the average (k+1/n),
                                      Hoaglin and Welsch (1978) recommend investigating cases with values greater than twice the average (2(k+1)/n), 
                                      Stevens (2002) recommend investigating cases with values greater than three times the average (3(k+1)/n)",
        dffits = "DFFits indicate the difference between the adjusted predicted value and the original predicted value.
                                      Adjusted predicted value for a case refers to the predicted value of that case, when that case is excluded from model fit."
      ),
      critical = list(standard_residuals = c("<-1.96", ">1.96"), cooks_distance = ">1"),
      numFmt = "#0.00"
    )
    excel_critical_value(result$call, workbook = wb, sheet = "Call", numFmt = "#0.00")
    openxlsx::saveWorkbook(wb = wb, file = filename, overwrite = TRUE)
  }
  return(result)
}

compute_y_logistic<-function(intercept,coefficient,x) {
  y=1/(1+exp(-(intercept+coefficient*x)))
  return(y)
}

plot_logistic_model<-function(df,outcome="outcome",title="",base_size=10) {
  Value<-Predictor<-NULL
  temp<-melt(df,id.vars=outcome)
  names(temp)<-c(outcome,"Predictor","Value")
  plot<-ggplot(temp,aes(x=Value,y=outcome,color=Predictor))+
    labs(x="Observed value",y=paste("Outcome"),title=paste("Logistic function"),caption=paste0("Observations:",nrow(df)))+
    stat_smooth(method="glm",method.args=list(family="binomial"),se=FALSE,alpha=0.1)+
