output_compare_model_logistic<-function(model1,model2) {
  x2<-model1$deviance-model2$deviance
  x2df<-model1$df.residual-model2$df.residual
  x2p<-1-stats::pchisq(x2,x2df)
  result<-data.frame("X^2"=x2,df=x2df,p=x2p)
  return(result)
}

report_logistic<-function(model,validation_data=NULL,file=NULL,title="",w=10,h=10,base_size=10,fast=FALSE) {
  rstandard<-rstudent<-dfbeta<-dffits<-hatvalues<-NULL
  score_notes<-c("Problematic values for standardized residuals > +-1.96",
                 "Problematic values for dfbeta >= 1",
                 "Problematic values for Hat values (leverage) 2 or 3 times the average (k+1/n) where k=number of predictors n=number of participants")
  modelchisquare<-model$null.deviance-model$deviance
  R2<-modelchisquare/model$null.deviance
  modeldf<-model$df.null-model$df.residual
  modelprobability<-1-pchisq(modelchisquare,modeldf)
  chisquare<-data.frame(Chi.Squared=modelchisquare,
                        df=modeldf,
                        p=modelprobability,
                        R2=R2,
                        Note=c("Significance indicates that the model is better than chance at predicting the outcome"))
  R.l<-1-(model$deviance/model$null.deviance)
  R.cs<-1-exp((model$deviance-model$null.deviance)/length(model$fitted.values))
  R.n<-R.cs/(1-(exp(-(model$null.deviance/length(model$fitted.values)))))
  pseudor2<-data.frame(rbind(data.frame(Test="Hosmer and Lemeshow R^2",Statistic=R.l,Notes=""),
                             data.frame(Test="Cox and Snell R^2",Statistic=R.cs,Notes="Cox and Snell R^2 never reaches maximum of 1"),
                             data.frame(Test="Nagelkerke R^2",Statistic=R.n,Notes="")))
  model_summary<-summary(model)
  model_call<-data.frame(call=call_to_string(model))
  VIF<-data.frame()
  if(ncol(model$model)>2)
    try({VIF=car::vif(model)})
  
  scores<-data.frame(variable=model$model,
                     weights=model$weights,
                     prior_weights=model$prior.weights,
                     linear_predictors=model$linear.predictors,
                     effects=model$effects,
                     fitted=model$fitted.values,
                     residuals=model$residuals,
                     standardized_residuals=rstandard(model),
                     student_residuals=rstudent(model),
                     dfbeta=dfbeta(model),
                     dffits=dffits(model),
                     hatvalues=hatvalues(model),
                     check.names=FALSE)
  
  result<-list(model_summary=model_summary,
               result_R2_logistic=pseudor2,
               result_X2_logistic=chisquare,
               coefficients=data.frame(model_summary$coefficients,
                                       "Odds Ratio"=exp(coef(model)),
                                       #  confidence_intervals=confint(model),
                                       check.names=FALSE),
               logistic_output=data.frame(AIC=model$aic,
                                          df.residual=model$df.residual,
                                          df.null=model$df.null,
                                          deviance=model$deviance,
                                          null.deviance=model$null.deviance,
                                          epsilon=model$control$epsilon,
                                          tol=model$qr$tol,
                                          qr.rank=model$qr$rank,
                                          rank=model$rank,
                                          maxit=model$control$maxit,
                                          iteration=model$iter,
                                          method=model$method,
                                          converged=model$converged,
                                          boundary=model$boundary,
                                          trace=model$control$trace),
               scores=scores,
               score_descriptives=compute_descriptives(scores[,sapply(scores,is.numeric)]),
               VIF=data.frame(VIF=VIF,check.names=FALSE),
               model_call=model_call)
  
  if(is.null(validation_data)) {
    predicted<-as.numeric(model$fitted.values)
    observed<-as.numeric(model$model[,1])
  } else {
    predicted<-as.numeric(predict(model,newdata=validation_data))
    observed<-as.numeric(get_all_vars(model,data=validation_data)[,1])
  }
  diagnostics<-autoplot(model)+
    labs(title=title,caption=paste0(deparse(model$terms),"\nobservations=",nrow(model$model)))+
    theme_bw(base_size=base_size)+
    theme(axis.text.x=element_text(angle=20,hjust=1))
  confusion_performance<-result_confusion_performance(observed=observed,predicted=predicted,base_size=base_size,title=title,step=.01)
  separability<-plot_separability(observed=observed,predicted=predicted,base_size=base_size,title=title)
  plotlist<-list(diagnostics,
                 confusion_performance$plot_performance,
                 separability)
  report_pdf(plotlist=plotlist,file=file,title=title,w=w,h=h,print_plot=TRUE)
  cmatrix<-confusion_matrix_percent(observed=observed,predicted=ifelse(predicted>mean(confusion_performance$cut,na.rm=TRUE),1,0))
  write_txt({
    output_separator("Model Summary",output=summary(model))
    output_separator("Summary",output=result$logistic_output)
    output_separator("Confusion Matrix",output=cmatrix)
    output_separator("Confusion Matrix Performance",output=confusion_performance$cut_performance)
    output_separator("Confusion Matrix Best Cut",output=confusion_performance$cut)
    output_separator("Pseudo R^2",output=result$result_R2_logistic)
    output_separator("X^2",output=result$result_X2_logistic)
    output_separator("Variance Inflation Factor",output=result$VIF)
    output_separator("Outlier Descriptives",output=result$score_descriptives,instruction=score_notes)
    output_separator("Call",output=result$model_call)
  },file=file)
  if(!is.null(file)) {
    filename<-paste0(file,".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb<-openxlsx::createWorkbook()
    excel_critical_value(result$logistic_output,wb,"summary",numFmt="#0.00")
    excel_critical_value(result$coefficients,wb,"coefficients",numFmt="#0.00",critical=list("Pr(>|z|)"="<0.05"))
    excel_confusion_matrix(cmatrix,wb)
    excel_critical_value(confusion_performance$cut_performance,wb,"confusion matrix performance",numFmt="#0.00")
    excel_critical_value(result$result_X2_logistic,wb,"X^2",numFmt="#0.00")
    excel_critical_value(result$result_R2_logistic,wb,"pseudo R^2",numFmt="#0.00")
    if(!fast)
      excel_critical_value(result$scores,wb,"scores residuals",comment=toString(score_notes),numFmt="#0.00")
    excel_critical_value(result$score_descriptives,wb,"score residual descriptives",comment=toString(score_notes),numFmt="#0.00")
    if(nrow(result$VIF)>0)
      excel_critical_value(result$VIF,wb,"VIF",comment="VIFs over 10 are problematic",numFmt="#0.00")
    excel_critical_value(result$model_call,wb,"Call",numFmt="#0.00")
    openxlsx::saveWorkbook(wb=wb,file=filename,overwrite=TRUE)
  }
}

report_ttests <- function(df, dv, iv, file = NULL, ...) {
  comment <- list(
    DV = "dependent variable",
    IV = "independent variable",
    level1 = "level 1",
    level2 = "level 2",
    n1 = "sample size for level 1",
    n2 = "sample size for level 2",
    t = "t statistic",
    df = "degrees of freedom for t statistic",
    p = "p value",
    CI_l = "confidence interval lower bound",
    CI_u = "confidence interval upper bound",
    alternative = "alternative hypothesis",
    method = "",
    mean1 = "mean for level 1",
    mean2 = "mean for level 2",
    sd1 = "standard deviation for level 1",
    sd2 = "standard deviation for level 2",
    sd_pooled = "pooled standard deviation\n\ncombined standard deviation of both levels",
    d = "measure of effect size\n\ncohen's d\n\nVery small\t0.01\t\tSawilowsky (2009)\nSmall\t\t0.20\t\tCohen (1988)\nMedium\t\t0.50\t\tCohen (1988)\nLarge\t\t0.80\t\tCohen (1988)\nVery large\t1.20\t\tSawilowsky (2009)\nHuge\t\t12.0\t\tSawilowsky (2009)",
    r = "measure of effect size\n\ncorrelation effect size",
    "k_squared[bartlett]" = "bartlett test for homogeneity of variances\n\n",
    "df[bartlett]" = "bartlett test for homogeneity of variances\n\n",
    "p[bartlett]" = "bartlett test for homogeneity of variances\n\nsignificant values indicate heteroscedasticity",
    bonferroni_p = "bonferroni adjusted critical value for a=0.05",
    significant = "if TRUE result is significant after bonferroni adjustment"
  )

  critical <- list(p = "<0.05", "p[bartlett]" = "<0.05")

  df_ttest <- data.frame()
  combinations <- expand.grid(names(df)[iv], names(df)[dv])
  names(combinations) <- c("iv", "dv")
  row.names(combinations) <- paste0(combinations$iv, "_", combinations$dv)
  combinations <- change_data_type(combinations, type = "character")
  # pb<-txtProgressBar(min=0,max=length(iv)*length(dv),style=3)
  for (i in 1:nrow(combinations)) {
    independent <- combinations$iv[i]
    dependent <- combinations$dv[i]
    # setTxtProgressBar(pb,i)
    tempdata <- df[complete.cases(df[, c(dependent, independent)]), ]
    tempdata[, independent] <- factor(tempdata[, independent])
    combinations_levels <- data.frame(t(utils::combn(unique(as.character(tempdata[, independent])), 2)), stringsAsindependent = FALSE)
    tempdata_all_levels <- df[complete.cases(df[, c(dependent, independent)]), ]
    for (l in 1:nrow(combinations_levels)) {
      f1 <- as.character(combinations_levels$X1[l])
      f2 <- as.character(combinations_levels$X2[l])
      tempdata <- tempdata_all_levels[tempdata_all_levels[, independent] %in% c(f1, f2), ]
      form <- stats::formula(paste0(dependent, "~", independent))
      # ttest <- stats::t.test(form, data = tempdata)
      ttest <- stats::t.test(form, data = tempdata, ...)
      bartlett.test <- stats::bartlett.test(form, data = tempdata)
      mean1 <- mean(tempdata[tempdata[, independent] %in% f1, dependent], na.rm = TRUE)
      mean2 <- mean(tempdata[tempdata[, independent] %in% f2, dependent], na.rm = TRUE)
      sd1 <- stats::sd(tempdata[tempdata[, independent] %in% f1, dependent], na.rm = TRUE)
      sd2 <- stats::sd(tempdata[tempdata[, independent] %in% f2, dependent], na.rm = TRUE)
      n1 <- length(tempdata[tempdata[, independent] %in% f1, dependent])
      n2 <- length(tempdata[tempdata[, independent] %in% f2, dependent])
      sd_pooled <- sqrt((sd1^2 + sd2^2) / 2)
      cohen_d <- abs(mean2 - mean1) / sd_pooled
      # J<-1-(3/(4*(n1+n2)-9))
      # hedges_g<-J*cohen_d
      # r_from_d<-cohen_d/sqrt(cohen_d^2+((n1+n2)^2/(n1*n2)))
      ttest_r <- data.frame(
        DV = independent,
        IV = dependent,
        level1 = f1,
        level2 = f2,
        n1 = n1,
        n2 = n2,
        t = ttest$statistic[[1]],
        df = ttest$parameter[[1]],
        p = ttest$p.value[[1]],
        CI_l = ttest$conf.int[[1]],
        CI_u = ttest$conf.int[[2]],
        alternative = ttest$alternative,
        method = ttest$method,
        mean1 = mean1,
        mean2 = mean2,
        sd1 = sd1,
        sd2 = sd2,
        sd_pooled = sd_pooled,
        d = cohen_d,
        r = cohen_d / (sqrt(cohen_d^2) + (((n1 + n2)^2) / (n1 * n2))),
        "k_squared[bartlett]" = bartlett.test$statistic,
        "df[bartlett]" = as.numeric(bartlett.test$parameter),
        "p[bartlett]" = bartlett.test$p.value,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
      df_ttest <- plyr::rbind.fill(df_ttest, ttest_r)
    }
  }
  # close(pb)
  adjustment <- compute_adjustment(0.05, nrow(df_ttest))
  df_ttest$bonferroni_p <- adjustment$bonferroni
  df_ttest$significant <- as.character(adjustment$bonferroni > df_ttest$p)
  report_dataframe(df_ttest, file = file, sheet = "t test", comment = comment, critical = critical)
  return(df_ttest)
}

report_wtests <- function(df, dv, iv, file = NULL, ...) {
  comment <- list(
    DV = "dependent variable",
    IV = "independent variable",
    level1 = "level 1",
    level2 = "level 2",
    n1 = "sample size for level 1",
    n2 = "sample size for level 2",
    W = "wilcoxon statistic",
    df = "degrees of freedom for t statistic",
    p = "p value",
    CI_l = "confidence interval lower bound",
    CI_u = "confidence interval upper bound",
    alternative = "alternative hypothesis",
    method = "",
    mean1 = "mean for level 1",
    mean2 = "mean for level 2",
    sd1 = "standard deviation for level 1",
    sd2 = "standard deviation for level 2",
    sd_pooled = "pooled standard deviation\n\ncombined standard deviation of both levels",
    d = "measure of effect size\n\ncohen's d\n\nVery small\t0.01\t\tSawilowsky (2009)\nSmall\t\t0.20\t\tCohen (1988)\nMedium\t\t0.50\t\tCohen (1988)\nLarge\t\t0.80\t\tCohen (1988)\nVery large\t1.20\t\tSawilowsky (2009)\nHuge\t\t12.0\t\tSawilowsky (2009)",
    r = "measure of effect size\n\ncorrelation effect size",
    "k_squared[bartlett]" = "bartlett test for homogeneity of variances\n\n",
    "df[bartlett]" = "bartlett test for homogeneity of variances\n\n",
    "p[bartlett]" = "bartlett test for homogeneity of variances\n\nsignificant values indicate heteroscedasticity",
    bonferroni_p = "bonferroni adjusted critical value for a=0.05",
    significant = "if TRUE result is significant after bonferroni adjustment"
  )

  critical <- list(p = "<0.05", "p[bartlett]" = "<0.05")

  df_wtest <- data.frame()
  combinations <- expand.grid(names(df)[iv], names(df)[dv])
  names(combinations) <- c("iv", "dv")
  row.names(combinations) <- paste0(combinations$iv, "_", combinations$dv)
  combinations <- change_data_type(combinations, type = "character")
  # pb<-txtProgressBar(min=0,max=length(iv)*length(dv),style=3)
  for (i in 1:nrow(combinations)) {
    independent <- combinations$iv[i]
    dependent <- combinations$dv[i]
    # setTxtProgressBar(pb,i)
    tempdata <- df[complete.cases(df[, c(dependent, independent)]), ]
    tempdata[, independent] <- factor(tempdata[, independent])
    combinations_levels <- data.frame(t(utils::combn(unique(as.character(tempdata[, independent])), 2)), stringsAsindependent = FALSE)
    tempdata_all_levels <- df[complete.cases(df[, c(dependent, independent)]), ]
    for (l in 1:nrow(combinations_levels)) {
      f1 <- as.character(combinations_levels$X1[l])
      f2 <- as.character(combinations_levels$X2[l])
      tempdata <- tempdata_all_levels[tempdata_all_levels[, independent] %in% c(f1, f2), ]
      form <- stats::formula(paste0(dependent, "~", independent))
      # wtest <- stats::wilcox.test(form, data = tempdata, conf.int = TRUE)
      wtest <- stats::wilcox.test(form, data = tempdata, conf.int = TRUE, ...)
      bartlett.test <- bartlett.test(form, data = tempdata)
      mean1 <- mean(tempdata[tempdata[, independent] %in% f1, dependent], na.rm = TRUE)
      mean2 <- mean(tempdata[tempdata[, independent] %in% f2, dependent], na.rm = TRUE)
      sd1 <- stats::sd(tempdata[tempdata[, independent] %in% f1, dependent], na.rm = TRUE)
      sd2 <- stats::sd(tempdata[tempdata[, independent] %in% f2, dependent], na.rm = TRUE)
      n1 <- length(tempdata[tempdata[, independent] %in% f1, dependent])
      n2 <- length(tempdata[tempdata[, independent] %in% f2, dependent])
      sd_pooled <- sqrt((sd1^2 + sd2^2) / 2)
      cohen_d <- abs(mean2 - mean1) / sd_pooled
      n <- nrow(stats::model.frame(form, data = tempdata))
      z <- stats::qnorm(wtest$p.value / 2, lower.tail = FALSE)
      r <- as.numeric(abs(z) / sqrt(n))
      wtest_r <- data.frame(
        DV = independent,
        IV = dependent,
        level1 = f1,
        level2 = f2,
        n1 = n1,
        n2 = n2,
        W = wtest$statistic[[1]],
        p = wtest$p.value[[1]],
        CI_l = wtest$conf.int[[1]],
        CI_u = wtest$conf.int[[2]],
        alternative = wtest$alternative,
        method = wtest$method,
        mean1 = mean1,
        mean2 = mean2,
        sd1 = sd1,
        sd2 = sd2,
        sd_pooled = sd_pooled,
        d = cohen_d,
        r = r,
        "k_squared[bartlett]" = bartlett.test$statistic,
        "df[bartlett]" = as.numeric(bartlett.test$parameter),
        "p[bartlett]" = bartlett.test$p.value,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
      df_wtest <- plyr::rbind.fill(df_wtest, wtest_r)
    }
  }
  # close(pb)
  adjustment <- compute_adjustment(0.05, nrow(df_wtest))
  df_wtest$bonferroni_p <- adjustment$bonferroni
  df_wtest$significant <- as.character(adjustment$bonferroni > df_wtest$p)
  report_dataframe(df_wtest, file = file, sheet = "t test", comment = comment, critical = critical)
  return(df_wtest)
}

plot_mtmm <- function(df, key, method, subject, title = "") {
  trait_x <- trait_y <- type <- value <- NULL
  trait <- data.frame(subject = df[, subject])
  alpha_result <- list()
  for (z in unique(df[, method])) {
    for (i in names(key)) {
      trait[, paste0(i, ".", z)] <- rowMeans(df[df[, method] %in% z, key[[i]]], na.rm = TRUE)
      alpha_result[[paste0(i, ".", z)]] <- compute_raw_alpha(df[df[, method] %in% z, key[[i]]])
    }
  }
  alphas <- data.frame(scale = names(unlist(alpha_result)), rel = unlist(alpha_result))
  cors <- stats::cor(trait[2:length(trait)], use = "pairwise")
  corm <- reshape2::melt(cors)
  corm <- corm[corm[, "Var1"] != corm[, "Var2"], ]
  rel <- alphas
  names(rel) <- c("Var1", "value")
  rel$Var2 <- rel$Var1
  rel <- rel[which(rel$Var1 %in% colnames(cors)), c("Var1", "Var2", "value")]
  corm <- rbind(corm, rel)
  corm[, c("trait_X", "method_X")] <- stringr::str_split_fixed(corm$Var1, "\\.", n = 2)
  corm[, c("trait_Y", "method_Y")] <- stringr::str_split_fixed(corm$Var2, "\\.", n = 2)
  corm[, c("var1.s", "var2.s")] <- t(apply(corm[, c("Var1", "Var2")], 1, sort))
  corm[which(corm[, "trait_X"] == corm[, "trait_Y"] & corm[, "method_X"] != corm[, "method_Y"]), "type"] <- "monotrait-heteromethod (validity)"
  corm[which(corm[, "trait_X"] != corm[, "trait_Y"] & corm[, "method_X"] == corm[, "method_Y"]), "type"] <- "heterotrait-monomethod"
  corm[which(corm[, "trait_X"] != corm[, "trait_Y"] & corm[, "method_X"] != corm[, "method_Y"]), "type"] <- "heterotrait-heteromethod"
  corm[which(corm[, "trait_X"] == corm[, "trait_Y"] & corm[, "method_X"] == corm[, "method_Y"]), "type"] <- "monotrait-monomethod (reliability)"
  corm$trait_X <- factor(corm$trait_X)
  corm$method_X <- factor(corm$method_X)
  corm$trait_Y <- factor(corm$trait_Y, levels = rev(levels(corm$trait_X)))
  corm$method_Y <- factor(corm$method_Y, levels = levels(corm$method_X))
  corm <- corm[order(corm$method_X, corm$trait_X), ]
  corm <- corm[!duplicated(corm[, c("var1.s", "var2.s")]), ]
  names(corm) <- tolower(names(corm))
  ggplot(data = corm) +
    geom_tile(aes(x = trait_x, y = trait_y, fill = type), size = 5) +
    geom_text(aes(x = trait_x, y = trait_y, label = stringr::str_replace(round(value, 2), "0\\.", "."))) +
    facet_grid(method_y ~ method_x) +
    labs(x = "", y = "", title = paste("Mulitrait Multimethod Matrix", title)) +
    theme_bw(base_size = 10) +
    theme(
      panel.background = element_rect(colour = NA),
      panel.grid.minor = element_blank(),
      axis.line = element_line(),
      strip.background = element_blank(),
      panel.grid = element_blank(),
      axis.text.x = element_text(angle = 45, hjust = 1),
      legend.title = element_blank()
    ) +
    scale_fill_brewer("type")
}

key_to_cfa_model <- function(key) {
  model <- c()
  for (i in names(key)) {
    model <- c(model, c(i, "=~", paste0(key[[i]], collapse = "+"), "\n"))
  }
  model <- (gsub(",", "", toString(model)))
  # model<-nake.names(stringi::stri_trans_general(model,"latin"))
