compute_raw_alpha <- function(df) {
  covariance_matrix <- stats::cov(df, use = "pairwise.complete.obs")
  # if(sapply(df,max)==1 && sapply(df,min)==0) {
  #   tetrachoric<-psych::tetrachoric(df,smooth=FALSE,global=FALSE,na.rm=TRUE,delete=TRUE)$rho
  #   standard_deviation<-as.numeric(sapply(df,sd,na.rm=TRUE))
  #   standard_deviation_matrix<-standard_deviation %*% t(standard_deviation)
  #   covariance_matrix<-standard_deviation_matrix*tetrachoric
  # }
  diagonal <- diag(covariance_matrix)
  numerator <- sum(as.numeric(diag(covariance_matrix)))
  denominator <- sum(reshape2::melt(covariance_matrix)$value)
  result <- length(df) / ((length(df) - 1)) * (1 - (numerator / denominator))
  return(result)
}

compute_alpha_diagnostics <- function(df) {
  corlist0 <- corlist1 <- corlist2 <- c()
  for (i in 1:length(df)) {
    corlist0 <- c(corlist0, compute_raw_alpha(df[, -i]))
    corlist1[i] <- stats::cor(rowSums(df, na.rm = TRUE), df[i], use = "pairwise.complete.obs")
    corlist2[i] <- stats::cor(rowSums(df[-i], na.rm = TRUE), df[i], use = "pairwise.complete.obs")
  }
  result <- data.frame(
    item = names(df),
    alpha.if.item.removed = corlist0,
    item.total.correlation = corlist1,
    item.total.correlation.r.drop = corlist2,
    row.names = names(df)
  )
  return(result)
}

compute_mean_sd_alpha <- function(df, divisor = NULL) {
  if (is.null(divisor)) {
    result <- data.frame(
      MEAN = mean(rowMeans(df, na.rm = TRUE), na.rm = TRUE),
      SD = stats::sd(rowMeans(df, na.rm = TRUE), na.rm = TRUE)
    )
  } else {
    result <- data.frame(
      Mean = mean(rowSums(df, na.rm = TRUE) / divisor, na.rm = TRUE),
      SD = stats::sd(rowSums(df, na.rm = TRUE) / divisor, na.rm = TRUE)
    )
  }
  return(result)
}

report_alpha <- function(df, key = NULL, questions = NULL, reverse = NULL, mini = NULL, maxi = NULL, file = NULL, ...) {
  comment <- list(
    raw_alpha = toString(c(
      "Crombach's alpha",
      "\n\nalpha based on covariances",
      "\n\nLambda 3=(n)/(n-1)(1-tr(Vx)/(Vx) = (n)/(n-1)(Vx-tr(Vx)/Vx=alpha",
      "\n\n0.91-1.00 Excellent (however check for multicolinearity problems)",
      "\n\n0.81-0.90 Good",
      "\n\n0.71-0.80 Good and Acceptable",
      "\n\n0.61-0.70 Acceptable",
      "\n\n0.56-0.60 Marginally Acceptable",
      "\n\n0.01-0.55 Unacceptable"
    )),
    std_alpha = "standarized alpha based on correlations",
    "g6(smc)" = toString(c(
      "Guttman's Lambda 6 reliability",
      "\nsquared multiple correlation",
      "\n\nconsiders the amount of variance in each item that can be accounted for the linear regression of all of the other items",
      "\n\nlambda 6=1-sum(e^2)/Vx = 1-sum(1-r^2(smc))/Vx",
      "\n\nif equal item loadings alpha>G6",
      "\nif unequal item loadings alpha<G6",
      "\nif there is a general factor alpha<G6"
    )),
    average_r = "average interitem correlation",
    median_r = "median interitem correlation",
    "s/n" = toString(c(
      "signal to noise ratio",
      "\n\nindex of the quality of the test that is linear with the number of items and the average correlation",
      "\n\n s/n = n r/(1-r)"
    )),
    ase = "alpha standard error",
    mean = toString(c(
      "for total statistics:",
      "\nmean of the scale formed by averaging or summing the items (depending upon the cumulative option)",
      "\n\nfor item statistics:",
      "\nmean of each item"
    )),
    sd = toString(c(
      "for total statistics:",
      "\nstandard deviation of the total score",
      "\n\nfor item statistics:",
      "\nstandard deviation of each item"
    )),
    alpha_drop = "A data frame with all of the above for the case of each item being removed one by one.",
    n = "number of complete cases for the item",
    raw_r = "correlation of each item with the total score, not corrected for item overlap",
    std_r = "correlation of each item with the total score (not corrected for item overlap) if the items were all standardized",
    r_cor = "item whole correlation corrected for item overlap and scale reliability",
    r_drop = "item whole correlation for this item against the scale without this item",
    response_freq = "the frequency of each item response (if less than 20)",
    scores = toString(c(
      "scores are by default the average response for all items that a participant took",
      "\nIf cumulative=TRUE, then these are sum scores."
    )),
    "boot_ci_2_5%" = "bootstrap confidence interval lower bound 2.5%",
    "boot_ci_50%" = "bootstrap confidence interval 50%",
    "boot_ci_97_5%" = "bootstrap confidence interval lower bound 97.5%",
    miss = "proportion of non answered items",
    "alpha se" = "alpha standard error",
    med_r = "median interitem correlation",
    unidim = "index of unidimensionality",
    kaiser_criterion = "number of eigenvalues > 1"
  )
  if (is.null(key)) {
    key <- list(dimension = names(df))
  }
  call_arguments <- match.call()
  call_string <- data.frame(call = gsub(" ", "", gsub("\"", " ", gsub(", ,", ",", toString(unlist(deparse(call_arguments)))))))
  pb <- txtProgressBar(min = 0, max = length(key), style = 3)
  result_total <- result_boot <- result_item_statistics <- result_dropped <- data.frame()
  counter <- 1
  for (sc in names(key)) {
    counter <- counter + 1
    setTxtProgressBar(pb, counter)
    if (length(key[[sc]]) < 2) next
    temp <- df[, key[[sc]]]
    if (!is.null(reverse)) {
      temp <- data.frame(psych::reverse.code(keys = reverse[[sc]], items = df[, key[[sc]]], mini = rep(mini, length(reverse[[sc]])), maxi = rep(maxi, length(reverse[[sc]]))))
    }
    result <- psych::alpha(temp, ...)
    eigenvalues <- NA
    try({
      eigenvalues <- eigen(cor(temp, use = "pairwise.complete.obs"))$values
    })
    kaiser_criterion <- length(eigenvalues[eigenvalues > 1])
    if (!is.null(result$boot.ci)) {
      boot_CI <- data.frame(t(result$boot.ci), check.names = FALSE)
      result_total_df <- data.frame(
        dimension = sc,
        items = result$nvar,
        kaiser_criterion = kaiser_criterion,
        result$total,
        boot_CI = boot_CI,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
      result_boot_df <- data.frame(
        dimension = sc,
        items = result$nvar,
        kaiser_criterion = kaiser_criterion,
        result$boot,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    } else {
      result_total_df <- data.frame(
        dimension = sc,
        items = result$nvar,
        kaiser_criterion = kaiser_criterion,
        result$total,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    }
    result_total <- plyr::rbind.fill(result_total, result_total_df)
    if (!is.null(result$boot.ci)) {
      result_boot <- plyr::rbind.fill(result_boot, result_boot_df)
    }
    if (is.null(questions)) {
      question <- row.names(result$alpha.drop)
    } else {
      question <- paste(row.names(result$alpha.drop), questions[[sc]])
    }
    result_item_statistics <- plyr::rbind.fill(
      result_item_statistics,
      data.frame(
        dimension = sc,
        question = question,
        raw_alpha = as.numeric(result$total[1]),
        result$item.stats,
        result$response.freq,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    )
    result_dropped <- plyr::rbind.fill(
      result_dropped,
      data.frame(
        dimension = sc,
        question = question,
        scale_alpha = as.numeric(result$total[1]),
        result$alpha.drop,
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
    )
  }
  close(pb)
  names(result_total) <- gsub(".", "_", tolower(names(result_total)), fixed = TRUE)
  if (!is.null(result$boot.ci)) {
    names(result_boot) <- gsub(".", "_", tolower(names(result_boot)), fixed = TRUE)
  }
  names(result_item_statistics) <- gsub(".", "_", tolower(names(result_item_statistics)), fixed = TRUE)
  names(result_dropped) <- gsub(".", "_", tolower(names(result_dropped)), fixed = TRUE)
  result_total$alpha_criterion <- NA
  result_total[result_total$raw_alpha < .6, "alpha_criterion"] <- "Unacceptable"
  result_total[result_total$raw_alpha < .7 & result_total$raw_alpha > .6, "alpha_criterion"] <- "Acceptable"
  result_total[result_total$raw_alpha < .8 & result_total$raw_alpha > .7, "alpha_criterion"] <- "Good and Acceptable"
  result_total[result_total$raw_alpha < .9 & result_total$raw_alpha > .8, "alpha_criterion"] <- "Good"
  result_total[result_total$raw_alpha > .9, "alpha_criterion"] <- "Excellent"

  raw_alpha_critical_value <- ">0.60"
  if (!is.null(file)) {
    filename <- paste0(file, ".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb <- openxlsx::createWorkbook()
    excel_critical_value(result_total, wb, "total statistics", critical = list(raw_alpha = raw_alpha_critical_value), numFmt = "#0.00", comment = comment)
    if (!is.null(result$boot.ci)) {
      excel_critical_value(result_boot, wb, "bootstrap", critical = list(raw_alpha = raw_alpha_critical_value), numFmt = "#0.00", comment = comment)
    }
    excel_critical_value(result_item_statistics, wb, "item statistics", critical = list(raw_alpha = raw_alpha_critical_value), numFmt = "#0.00", comment = comment)
    excel_critical_value(result_dropped, wb, "if dropped", critical = list(scale_alpha = raw_alpha_critical_value, raw_alpha = raw_alpha_critical_value), numFmt = "#0.00", comment = comment)
    excel_critical_value(call_string, wb, "call", numFmt = "#0.00")
    openxlsx::saveWorkbook(wb = wb, file = filename, overwrite = TRUE)
  }
  result <- list(result_total = result_total, result_boot = result_boot, result_item_statistics = result_item_statistics, result_dropped = result_dropped)
  return(result)
}

extract_components <- function(model, title = "") {
  vc_percent <- NULL
  res <- mixlm::Anova(model, type = "III")
  name_components <- row.names(res$anova)
  components <- data.frame(
    component = name_components,
    VC = res$var.comps,
    vc_percent = abs(res$var.comps) / sum(abs(res$var.comps), na.rm = TRUE) * 100
  )
  component <- components
  components$component <- factor(as.character(components$component),
    levels = as.character(components$component)
  )
  component_plot <- ggplot(components, aes(x = component, y = vc_percent)) +
    geom_bar(stat = "identity") +
    geom_line(group = 1, color = "gray25") +
    geom_point(size = 5, color = "gray25") +
    labs(title = title, x = "components", y = "Explained variance (%)") +
    coord_flip() +
    theme_bw()
  result <- list(components = component, plot = component_plot)
  return(result)
}

compute_shrout <- function(sperson, spersonitem, stime, spersontime, serror, m, k) {
  instruction <- data.frame(
    measure = c("r1f", "r1r", "rkf", "rkr", "rc"),
    description = c(
      "Reliability (between persons) of measures taken on the same fixed k time",
      "Reliability (between persons) of measures taken on the same random k time",
      "Reliability (between persons) of average measures taken over fixed m items and fixed k times",
      "Reliability (between persons) of different random time with same number of points k between periods",
      "Reliability (within persons) of change"
    )
  )
  km <- m * k
  r1f <- (sperson + spersonitem / m) / (sperson + spersonitem / m + serror / m)
  r1r <- (sperson + spersonitem / m) / (sperson + spersonitem / m + stime + spersontime + serror / m) # Different people different days
  rkf <- (sperson + spersonitem / m) / (sperson + spersonitem / m + serror / km)
  rkr <- (sperson + spersonitem / m) / (sperson + spersonitem / m + stime / k + spersontime / k + serror / km)
  rc <- (spersontime) / (spersontime + (serror / m))
  result <- data.frame(
    measure = c("r1f", "rkf", "rkr", "r1r", "rc"),
    result = c(r1f, rkf, rkr, r1r, rc = rc)
  )
  result <- merge(result, instruction, all = TRUE)
  return(result)
}

plot_cfa_gg <- function(model,
                        what        = c("std", "est", "eq"),
                        layout      = c("tree", "circle", "spring"),
                        label_size      = 3.2,
                        edge_label_size = 2.6,
                        color_latent    = "#4f8ef7",
                        color_observed  = "#e8eaf0",
                        ...) {
  hh<-hw<-mx<-my<-name<-x<-x_from<-x_to<-y<-y_from<-y_to<-NULL
  
  
  what   <- match.arg(what)
  layout <- match.arg(layout)
  
  # ── 1. Extract parameter table ───────────────────────────────────────────
  pe <- lavaan::parameterEstimates(model, standardized = TRUE)
  
  # Choose which column to display on edges
  edge_col <- switch(what,
                     std = "std.all",
                     est = "est",
                     eq  = "label"
  )
  
  # ── 2. Identify nodes ────────────────────────────────────────────────────
  latent_vars   <- unique(pe$lhs[pe$op == "=~"])
  observed_vars <- unique(pe$rhs[pe$op == "=~"])
  all_nodes     <- unique(c(latent_vars, observed_vars))
  
  node_df <- data.frame(
    name    = all_nodes,
    is_lat  = all_nodes %in% latent_vars,
    stringsAsFactors = FALSE
  )
  
  # ── 3. Compute node layout ───────────────────────────────────────────────
  # Build an igraph just for layout purposes
  edge_list <- pe[pe$op %in% c("=~", "~"), c("lhs","rhs"), drop=FALSE]
  edge_list <- edge_list[edge_list$lhs %in% all_nodes &
                           edge_list$rhs %in% all_nodes, ]
  
  g <- igraph::graph_from_data_frame(
    d        = edge_list,
    directed = TRUE,
    vertices = node_df
  )
  
  coords <- switch(layout,
                   circle = igraph::layout_in_circle(g),
                   tree   = {
                     # root = latent variables
                     roots <- which(igraph::V(g)$name %in% latent_vars)
                     igraph::layout_as_tree(g, root = roots, flip.y = TRUE)
                   },
                   spring = igraph::layout_with_fr(g, niter = 1000)
  )
  
  node_df$x <- coords[, 1]
  node_df$y <- coords[, 2]
  
  # normalise to [0,10] for stable sizing
  rng_x <- range(node_df$x); rng_y <- range(node_df$y)
  safe_scale <- function(v, rng) {
    if (diff(rng) == 0) rep(5, length(v)) else (v - rng[1]) / diff(rng) * 10
  }
  node_df$x <- safe_scale(node_df$x, rng_x)
  node_df$y <- safe_scale(node_df$y, rng_y)
  
  # node half-dimensions
  node_df$hw <- ifelse(node_df$is_lat, 0.90, 0.70)   # half-width
  node_df$hh <- ifelse(node_df$is_lat, 0.55, 0.42)   # half-height
  
  # ── 4. Build edge data for factor loadings (=~) ──────────────────────────
  loadings <- pe[pe$op == "=~", ]
  
  edge_df <- merge(
    loadings,
    node_df[, c("name","x","y")],
    by.x = "lhs", by.y = "name"
  )
  names(edge_df)[names(edge_df) %in% c("x","y")] <- c("x_from","y_from")
  
  edge_df <- merge(
    edge_df,
    node_df[, c("name","x","y")],
    by.x = "rhs", by.y = "name"
  )
  names(edge_df)[names(edge_df) %in% c("x","y")] <- c("x_to","y_to")
  
  # label to display
  edge_df$display <- if (what == "eq") {
    ifelse(is.na(edge_df$label) | edge_df$label == "",
           formatC(edge_df$est, digits = 3, format = "f"),
           edge_df$label)
  } else {
    formatC(edge_df[[edge_col]], digits = 3, format = "f")
  }
  
  # midpoints for edge labels
  edge_df$mx <- (edge_df$x_from + edge_df$x_to) / 2
  edge_df$my <- (edge_df$y_from + edge_df$y_to) / 2
  
  # ── 5. Covariance arcs between latent variables ──────────────────────────
  cov_df <- pe[pe$op == "~~" & pe$lhs != pe$rhs &
                 pe$lhs %in% latent_vars & pe$rhs %in% latent_vars, ]
  
  if (nrow(cov_df) > 0) {
    cov_df <- merge(cov_df, node_df[, c("name","x","y")],
                    by.x = "lhs", by.y = "name")
    names(cov_df)[names(cov_df) %in% c("x","y")] <- c("x_from","y_from")
    cov_df <- merge(cov_df, node_df[, c("name","x","y")],
                    by.x = "rhs", by.y = "name")
    names(cov_df)[names(cov_df) %in% c("x","y")] <- c("x_to","y_to")
    cov_df$display <- formatC(cov_df[[edge_col]], digits = 3, format = "f")
    cov_df$mx <- (cov_df$x_from + cov_df$x_to) / 2
    cov_df$my <- (cov_df$y_from + cov_df$y_to) / 2
  }
  
  # ── 6. Build plot ────────────────────────────────────────────────────────
  plot_title <- switch(what,
                       std = "Standardised Estimates",
                       est = "Unstandardised Estimates",
                       eq  = "Parameters with Equality Constraints"
  )
  
  p <- ggplot2::ggplot() +
    
    # factor loading edges
    ggplot2::geom_segment(
      data = edge_df,
      ggplot2::aes(x = x_from, y = y_from, xend = x_to, yend = y_to),
      colour   = "#555a6b",
      linewidth = 0.55,
      arrow = ggplot2::arrow(length = ggplot2::unit(6, "pt"),
                             type = "closed", ends = "last")
    ) +
    
    # loading labels
    ggplot2::geom_label(
      data = edge_df,
      ggplot2::aes(x = mx, y = my, label = display),
      size      = edge_label_size,
      fill      = "white",
      label.size = 0,
      label.padding = ggplot2::unit(1.5, "pt"),
      colour    = "#333745"
    ) +
    
    # node rectangles — observed
    ggplot2::geom_rect(
      data = node_df[!node_df$is_lat, ],
      ggplot2::aes(
        xmin = x - hw, xmax = x + hw,
        ymin = y - hh, ymax = y + hh
      ),
      fill   = color_observed,
      colour = "#8890a8",
      linewidth = 0.4
    ) +
    
    # node ellipses — latent (drawn as wider rounded rects via annotate_custom;
    # simplest portable approach: just use distinctly-coloured rects)
    ggplot2::geom_rect(
      data = node_df[node_df$is_lat, ],
      ggplot2::aes(
        xmin = x - hw, xmax = x + hw,
        ymin = y - hh, ymax = y + hh
      ),
      fill   = color_latent,
      colour = "#2a5cc7",
      linewidth = 0.5
    ) +
    
    # node labels — observed
    ggplot2::geom_text(
      data   = node_df[!node_df$is_lat, ],
      ggplot2::aes(x = x, y = y, label = name),
      size   = label_size,
      colour = "#222533",
      fontface = "plain"
    ) +
    
    # node labels — latent
    ggplot2::geom_text(
      data   = node_df[node_df$is_lat, ],
      ggplot2::aes(x = x, y = y, label = name),
      size   = label_size,
      colour = "white",
      fontface = "bold"
    ) +
    
    ggplot2::coord_fixed(clip = "off") +
    ggplot2::theme_void(base_size = 11) +
    ggplot2::theme(
      plot.title   = ggplot2::element_text(
        hjust = 0.5, size = 12, margin = ggplot2::margin(b = 8)),
      plot.margin  = ggplot2::margin(20, 20, 20, 20)
    ) +
    ggplot2::labs(title = paste0(plot_title, " — ", layout))
  
  # add covariance arcs if present
  if (nrow(cov_df) > 0) {
    p <- p +
      ggplot2::geom_curve(
        data = cov_df,
        ggplot2::aes(x = x_from, y = y_from, xend = x_to, yend = y_to),
        curvature = 0.35,
        colour    = "#e87c4f",
        linewidth  = 0.5,
        linetype  = "dashed",
        arrow = ggplot2::arrow(length = ggplot2::unit(5, "pt"),
                               type = "open", ends = "both")
      ) +
      ggplot2::geom_label(
        data = cov_df,
        ggplot2::aes(x = mx, y = my, label = display),
        size      = edge_label_size,
        fill      = "#fff5f0",
        label.size = 0,
        colour    = "#993c1d"
      )
  }
  
  return(p)
}

plot_cfa <- function(model, ...) {
  
  layouts  <- c("circle", "tree", "spring")
  whats    <- c("est", "std", "eq")
  what_key <- c(est = "estimates",
                std = "standard_estimates",
                eq  = "parameters_wih_equality_constraints")
  
  plots <- list()
  
  for (lay in layouts) {
    for (wh in whats) {
      key <- paste0(lay, "_", what_key[[wh]])
      plots[[key]] <- tryCatch(
        plot_cfa_gg(model, what = wh, layout = lay, ...),
        error = function(e) {
          message(sprintf("Skipping %s: %s", key, conditionMessage(e)))
          NULL
        }
      )
    }
  }
  
  plots <- Filter(Negate(is.null), plots)
  return(plots)
}

report_cfa<-function(model,file=NULL,w=10,h=10) {
  pt<-options(fit=c("GFI","AGFI","RMSEA","NFI","NNFI","CFI","RNI","IFI","SRMR","AIC","AICc","BIC","CAIC"))
  r_squared<-data.frame(r_squared=lavaan::inspect(model,"rsquare",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE))
  fit<-data.frame(fit=lavaan::inspect(model,"fit",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE))
  unstandardized_estimates<-lavaan::inspect(model,"est",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)
  standardized_estimates<-lavaan::inspect(model,"std",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)
  group<-data.frame()
  if(model@Model@ngroups>1) {
    group<-data.frame(data.frame(GROUP_COLLUMN=lavaan::inspect(model,what="group",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)),
                      data.frame(GROUPS=lavaan::inspect(model,what="group.label",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)),
                      data.frame(NGROUPS=lavaan::inspect(model,what="ngroups",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)),
                      data.frame(OBSERVATIONS=lavaan::inspect(model,what="nobs",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)),
                      data.frame(ORIGINAL_OBSERVATIONS=lavaan::inspect(model,what="norig",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)),
                      data.frame(TOTAL=lavaan::inspect(model,what="ntotal",add.labels=TRUE,add.class=TRUE,list.by.group=TRUE,drop.list.single.group=TRUE)))
  }
  parameters<-data.frame(lavaan::parameterEstimates(model,se=TRUE,zstat=TRUE,pvalue=TRUE,ci=TRUE,level=0.95,boot.ci.type="perc",standardized=TRUE,fmi=FALSE,remove.system.eq=TRUE,remove.eq=FALSE,remove.ineq=FALSE,remove.def=FALSE,rsquare=TRUE,add.attributes=TRUE))
  modification_indices<-data.frame(lavaan::modificationIndices(model,standardized=TRUE,cov.std=TRUE,information="expected",power=TRUE,delta=0.1,alpha=0.05,high.power=0.75,sort.=TRUE,minimum.value=0,free.remove=FALSE,na.remove=TRUE,op=NULL))
  sample_covariance<-data.frame(model@SampleStats@cov)
  if(typeof(lavaan::predict(model))=="list")
    predict<-data.frame(do.call(rbind.data.frame,model@Data@X),do.call(rbind.data.frame,lavaan::predict(model)))
  else
    predict<-data.frame(model@Data@X,lavaan::predict(model))
  call<-data.frame(call=stringr::str_replace_all(deparse(model@call),stringr::fixed(" "),""),stringsAsFactors=FALSE)
  result<-list(r_squared=r_squared,fit_indices=fit,parameters=parameters,modification_indices=modification_indices,sample_covariance=sample_covariance,
               unstandardized_estimates=unstandardized_estimates,standardized_estimates=standardized_estimates,group=group,predict=predict,call=call)
  
  plot<-plot_cfa(model)
  report_pdf(plotlist=plot,file=file,title="diagram",w=w,h=h,print_plot=TRUE)
  write_txt({
    output_separator("SUMMARY",output=lavaan::summary(model,standardized=TRUE,fit.measures=TRUE,rsquare=TRUE))
    output_separator("R_SQUARED",output=data.frame(result$r_squared))
    output_separator("FIT INDICES",output=data.frame(result$fit_indices))
    output_separator("PARAMETERS",output=result$parameters)
    output_separator("UNSTANDARDIZED PARAMETERS",output=result$unstandardized_estimates)
    output_separator("STANDARDIZED PARAMETERS",output=result$standardized_estimates)
    output_separator("SAMPLE COVARIANCE",output=result$sample_covariance)
    output_separator("CALL",output=result$call$call)
  },file=file)
  if(!is.null(file)){
    filename<-paste0(file,".xlsx")
    if (file.exists(filename)) file.remove(filename)
    wb<-openxlsx::createWorkbook()
    excel_critical_value(result$r_squared,workbook=wb,sheet="R_Squared",numFmt="#0.00")
    excel_critical_value(result$fit_indices,workbook=wb,sheet="Fit_Indices",numFmt="#0.00")
    excel_critical_value(result$parameters,workbook=wb,sheet="Parameters",numFmt="#0.00")
    excel_critical_value(result$modification_indices,workbook=wb,sheet="Modification_Indices",numFmt="#0.00")
    excel_critical_value(result$group,workbook=wb,sheet="Groups",numFmt="#0.00")
    excel_matrix(result$sample_covariance,workbook=wb,sheet="Sample_Covariance",numFmt="#0.00")
    excel_matrix(result$predict,workbook=wb,sheet="Scores",numFmt="#0.00")
    excel_critical_value(result$call,workbook=wb,sheet="Call",numFmt="#0.00")
    openxlsx::saveWorkbook(wb=wb,file=filename,overwrite=TRUE)
  }
  return(result)
}

simulate_cfa_fit<-function(model_sim=NULL,model=NULL,df=NULL,minnobs=50,maxnobs=1000,stepping=10,file=NULL,w=10,h=10) {
  sequence<-seq(from=minnobs,to=maxnobs,by=stepping)
  future::plan(future::multisession,workers=parallel::detectCores())
  sim_results<-do.call(rbind,future.apply::future_lapply(sequence,function(nobs) {
    if(!is.null(model_sim))
      sim<-lavaan::simulateData(model=model_sim,model.type="cfa",return.type="data.frame",sample.nobs=nobs,orthogonal=TRUE)
    if(!is.null(df))
      sim<-simulate_correlation_from_sample(df,nrows=nobs)
    fit<-lavaan::cfa(model,data=sim)
    fit_indices<-data.frame(FIT=lavaan::inspect(fit,"fit"))
    data.frame(observations=nobs,data.frame(t(fit_indices)),row.names=NULL)
  },future.seed=TRUE))
  future::plan(future::sequential)
  plot_data<-remove_nc(sim_results,remove_rows=TRUE,aggressive=FALSE,remove_cols=TRUE,remove_zero_variance=TRUE)
  combinations<-data.frame(X1=rep("observations",length(names(plot_data))),X2=names(plot_data),stringsAsFactors=FALSE)
  plots<-plot_scatterplot(df=plot_data,combinations=combinations)
  report_dataframe(sim_results,sheet="simulation",file=file)
  report_pdf(plotlist=plots,w=w,h=w,file=file)
  return(list(sim_results,plots))
}

clear_text<-function(text) {
  text<-tolower(trimws(gsub("\\s+"," ",gsub("[[:punct:]]+"," ",gsub("[[:digit:]]+"," ",text)))))
  return(text)
}

clear_stopwords<-function(text,stopwords=stopwords::stopwords("english")) {
  stopwords_regex=paste(stopwords,collapse='\\b|\\b')
  stopwords_regex=paste0('\\b',stopwords_regex,'\\b')
  text<-str_replace_all(text,stopwords_regex,'')
  text<-clear_text(gsub(" *\\b[[:alpha:]]{1}\\b *"," ",text)) # Remove 1 letter words
  return(text)
}

tag_pos<-function(text) {
  s<-NLP::as.String(text)
  word_token_annotator<-openNLP::Maxent_Word_Token_Annotator()
  a2<-NLP::Annotation(1L,"sentence",1L,nchar(s))
  a2<-NLP::annotate(s,word_token_annotator,a2)
  a3<-NLP::annotate(s,openNLP::Maxent_POS_Tag_Annotator(),a2)
  a3w<-a3[a3$type=="word"]
  POStags<-unlist(lapply(a3w$features,`[[`,"POS"))
  POStagged<-paste(sprintf("%s/%s",s[a3w],POStags),collapse=" ")
  list(POStagged=POStagged,POStags=POStags)
}

compute_text_similarity<-function(text1,text2) {
  tversky<-compute_tversky_index(text1,text2)
  intersect<-length(intersect(text1,text2))
  tb1<-table(text1)
  tb2<-table(text2)
  df_intersect<-data.frame(rbind(tb1[intersect(names(tb1),names(tb2))],
                                 tb2[intersect(names(tb1),names(tb2))]))
  if(length(df_intersect)>0) {
    intersect_weight<-sum(df_intersect[1,]*df_intersect[2,])
  }
  else {
    intersect_weight<-0
  }
  setdiff1<-length(setdiff(text1,text2))
  setdiff2<-length(setdiff(text2,text1))
  lengtht1<-length(text1)
  lengtht2<-length(text2)
  df<-data.frame(tversky,intersect,intersect_weight,setdiff1,setdiff2,lengtht1,lengtht2)
  return(df)
}

stat_word_char<-function(text) {
  text<-clear_text(text)
  data<-strsplit(text," ")
  words<-future.apply::future_sapply(data,length)
  mean_char<-future.apply::future_sapply(data,function(x) mean(nchar(x)[!nchar(x)==0]))
  sd_char<-future.apply::future_sapply(data,function(x) stats::sd(nchar(x)[!nchar(x)==0]))
  max_char<-future.apply::future_sapply(data,function(x) max(nchar(x)[!nchar(x)==0]))
  min_char<-future.apply::future_sapply(data,function(x) min(nchar(x)[!nchar(x)==0]))
  spell_error<-future.apply::future_sapply(data,function(x)
    nrow(spelling::spell_check_text(x,ignore=character(),lang="en_US")))
  result<-data.frame(words,mean_char,sd_char,max_char,min_char,spell_error)
  return(result)
}

compute_tversky_index <- function(x, y, alpha = 0.5, beta = 0.5) {
  x <- as.character(x)
  y <- as.character(y)
  
  intersection <- length(intersect(x, y))
  x_only       <- length(setdiff(x, y))
  y_only       <- length(setdiff(y, x))
  
  intersection / (intersection + alpha * x_only + beta * y_only)
}

